-- Lección: mesopotamia
insert into public.lessons (topic_id, title, body, position, published)
select id, 'Mesopotamia y el nacimiento del Estado', '[{"type":"section","title":"Un medio difícil: agua, sal y trabajo","text":"La llanura aluvial del sur de Irak carece de piedra, de madera de construcción y de metales. Tiene, en cambio, suelos fértiles y dos ríos. Pero su régimen es problemático: el Tigris y el Éufrates crecen en primavera, cuando el cereal ya está en el campo, no antes de la siembra como el Nilo, y lo hacen de manera brusca e impredecible. Cultivar allí exige control activo del agua: canales de derivación, diques, compuertas y drenaje.\n\nEse esfuerzo tuvo un coste ecológico documentado. La irrigación con evaporación intensa deposita sales en el suelo. Los archivos administrativos permiten seguir el proceso: entre 2400 y 1700 a. C., la proporción de cebada —más tolerante a la sal— frente al trigo pasó de un reparto equilibrado a un predominio casi absoluto, mientras los rendimientos registrados descendían. Thorkild Jacobsen y Robert Adams describieron esta salinización progresiva en un influyente artículo de 1958 y la vincularon al desplazamiento del centro político hacia el norte.\n\nLa escasez de materias primas explica otra característica estructural: Mesopotamia dependió siempre del intercambio de larga distancia. La madera venía del Líbano y de los Zagros, el cobre de Omán y Anatolia, el lapislázuli de Afganistán, la cornalina del valle del Indo. Esa dependencia hizo del comercio y del control de rutas un asunto de Estado, y explica buena parte de su política exterior y militar.","callout":"La cebada no solo era alimento: funcionaba como unidad de cuenta y medio de pago de salarios. Los archivos expresan sueldos en litros de cebada y en pesos de plata mucho antes de que existiera la moneda acuñada."},{"type":"section","title":"La revolución urbana de Uruk","text":"Hacia 3500 a. C., Uruk alcanzó una extensión y una población sin precedentes —las estimaciones oscilan entre 20.000 y 50.000 habitantes— y desarrolló una arquitectura monumental de templos sobre terrazas. Gordon Childe llamó a este proceso «revolución urbana» y lo caracterizó por diez rasgos: concentración demográfica, especialización artesanal, tributo, monumentalidad, clases sociales, escritura, ciencia predictiva, arte representativo, comercio exterior y un Estado con territorio.\n\nLa contabilidad precedió a la escritura. Denise Schmandt-Besserat mostró que fichas de arcilla con formas convencionales (tokens) se usaban desde el VIII milenio para registrar cantidades de bienes. Esas fichas se guardaban en bullae —esferas de arcilla selladas— y, para saber qué contenían sin romperlas, se imprimían las formas en la superficie. El paso siguiente fue prescindir del contenido y conservar solo las marcas: la tablilla.\n\nLas primeras tablillas de Uruk IV, hacia 3300 a. C., son documentos económicos: cantidades de grano, cabezas de ganado, raciones, listas de profesiones. No hay poesía ni narración. La escritura nace como tecnología de gestión, no de literatura; los textos literarios llegan siglos después.\n\nEl modelo político dominante durante el Dinástico Arcaico fue la ciudad-Estado: un núcleo urbano con su territorio agrícola, su dios tutelar, su templo y su gobernante —ensi o lugal—. Estas ciudades competían por agua y tierra de forma endémica. La disputa entre Lagash y Umma por la frontera de Guedena está documentada durante más de un siglo y produjo, en la Estela de los Buitres, uno de los primeros relatos de guerra conservados.","callout":null},{"type":"section","title":"Escritura cuneiforme y cultura del archivo","text":"El cuneiforme se escribía imprimiendo un cálamo de caña de sección triangular sobre arcilla fresca. Es un sistema mixto: signos logográficos que valen por una palabra, signos silábicos que valen por un sonido y determinativos que clasifican semánticamente. Se usó durante más de tres milenios y sirvió para lenguas muy distintas —sumerio, acadio, elamita, hitita, urartio—, del mismo modo que el alfabeto latino sirve hoy a lenguas sin parentesco.\n\nLa arcilla es un soporte afortunado para el historiador: cuando un edificio ardía, las tablillas se cocían y se conservaban mejor. Por eso disponemos de archivos enteros. Los de la Tercera Dinastía de Ur suman más de cien mil documentos administrativos y permiten reconstruir la economía de un Estado antiguo con un detalle inalcanzable en otras civilizaciones: rendimientos por parcela, raciones por trabajador, censos de ganado, cuentas de talleres textiles con centenares de operarias.\n\nLa formación de escribas se hacía en la edubba, la «casa de las tablillas». Sus ejercicios —listas léxicas, copias de proverbios, problemas matemáticos, textos de disputa entre estudiantes— revelan un currículo estable. Las matemáticas mesopotámicas usaban un sistema sexagesimal cuyo legado seguimos empleando: sesenta minutos, sesenta segundos, trescientos sesenta grados. La tablilla Plimpton 322 recoge ternas pitagóricas más de mil años antes de Pitágoras.\n\nEl desciframiento moderno se debe sobre todo a Henry Rawlinson, que copió con riesgo considerable la inscripción trilingüe de Behistún, mandada grabar por Darío I en un acantilado. La versión en persa antiguo, más simple, sirvió de puerta de entrada al elamita y al acadio, del mismo modo que el griego lo fue para los jeroglíficos.","callout":"La *Epopeya de Gilgamesh* se conoce sobre todo por la versión estándar de la biblioteca de Asurbanipal. Su relato del diluvio, con un superviviente advertido por un dios, presenta paralelos evidentes con el bíblico y desató una polémica considerable cuando George Smith lo publicó en 1872."},{"type":"section","title":"Templo, palacio y economía: el debate sobre quién manda","text":"La organización económica mesopotámica se ha interpretado de formas muy distintas. A comienzos del siglo XX, Anton Deimel propuso a partir de los archivos de Lagash el modelo de la «ciudad-templo»: el santuario poseería prácticamente toda la tierra y organizaría toda la producción, en una economía redistributiva sin propiedad privada relevante.\n\nLa revisión posterior desmontó esa imagen. Igor Diakonoff mostró que los archivos de Lagash pertenecían a un solo templo y no representaban la totalidad de la ciudad, y documentó la existencia de tierra comunal de familias extensas y de propiedad privada transferible. Hoy se acepta un modelo pluralista: coexistían el sector del templo, el del palacio y un sector privado, con proporciones variables según épocas y ciudades.\n\nEse debate se cruza con otro más amplio, el de la naturaleza de la economía antigua. Karl Polanyi sostuvo que las economías precapitalistas funcionaban por reciprocidad y redistribución, con «puertos de comercio» administrados, y no por mercados formadores de precios. Los asiriólogos que estudiaron el archivo de los mercaderes asirios de Kanesh —cartas privadas de negocios del siglo XIX a. C., con sociedades, créditos, intereses y arbitraje de precios entre Assur y Anatolia— han argumentado en sentido contrario.\n\nLa cuestión no es meramente técnica: determina si cabe hablar de «capital», «mercado» o «beneficio» en el mundo antiguo, o si esos conceptos importan categorías modernas a sociedades que funcionaban con otra lógica. La postura mayoritaria actual es intermedia y empírica: hubo mercados y precios fluctuantes, pero insertos en instituciones —templo, palacio, familia— que los modelaban de forma decisiva.","callout":null},{"type":"section","title":"Derecho, justicia y el problema del Código de Hammurabi","text":"La estela de diorita de Hammurabi, hallada en Susa en 1901, contiene un prólogo, unas 282 disposiciones y un epílogo. Es el texto jurídico antiguo más conocido, aunque no el más antiguo: le preceden las reformas de Urukagina, el código de Ur-Nammu y el de Lipit-Ishtar.\n\nSus disposiciones tienen forma casuística —«si un hombre hace X, entonces Y»— y aplican penas diferenciadas según el estatus del implicado. La sociedad distingue tres categorías: awilum (hombre libre de pleno derecho), mushkenum (dependiente) y wardum (esclavo). Golpear a un awilum y golpear a un esclavo tienen consecuencias distintas; matar a la hija de un hombre puede castigarse ejecutando a la hija del culpable. La ley del talión convive con la compensación económica según quién sea la víctima.\n\nEl debate historiográfico central es qué era realmente este texto. La lectura tradicional lo entendía como un código vigente, aplicable por los tribunales. La objeción decisiva es que los miles de documentos judiciales conservados de la época prácticamente nunca lo citan, y que en ocasiones resuelven en sentido distinto al que la estela prescribe. Jean Bottéro y F. R. Kraus propusieron por ello leerlo como un monumento ideológico: la exhibición de un rey justo ante los dioses y la posteridad, quizá también como colección de precedentes ejemplares para la formación de jueces.\n\nCon todo, el texto documenta bien la estructura social: precios máximos, salarios, responsabilidad profesional del constructor y del médico, régimen del matrimonio y del divorcio, deudas y esclavitud por deudas. Y muestra una preocupación recurrente en la ideología real mesopotámica: la proclamación periódica de misharum, cancelaciones generales de deudas destinadas a impedir que el endeudamiento privara al Estado de contribuyentes y soldados.","callout":"El prólogo de la estela afirma que la ley existe «para que el fuerte no oprima al débil». Es la formulación más antigua conservada de la justicia como límite del poder, aunque su aplicación real fuese muy desigual."},{"type":"section","title":"De la ciudad-Estado al imperio","text":"Sargón de Acad, hacia 2334 a. C., sometió las ciudades sumerias y construyó la primera estructura política que puede llamarse imperio territorial: gobernadores designados, guarniciones, una lengua administrativa común y una hija instalada como sacerdotisa en Ur —Enheduanna, autora de himnos y primera figura literaria de la historia cuyo nombre conocemos—.\n\nLa Tercera Dinastía de Ur llevó la centralización al extremo. Su documentación permite ver un Estado que controla talleres, redistribuye raciones, mide el trabajo en jornadas-hombre y penaliza los déficits de producción. Ese aparato resultó frágil: se derrumbó en pocas décadas por la combinación de presión amorrea, crisis agrarias y rigidez fiscal.\n\nEl imperio neoasirio (siglos IX-VII a. C.) fue la construcción más duradera y también la más brutal de las documentadas. Se apoyó en un ejército permanente, en el uso sistemático del terror como instrumento de disuasión —relieves palaciales que exhiben empalamientos y desollamientos— y en la deportación masiva de poblaciones enteras, calculada en varios millones de personas a lo largo de tres siglos. La política tenía una lógica administrativa: desarraigar élites locales, romper solidaridades y reasentar mano de obra donde se necesitaba.\n\nSu caída fue rápida. La coalición de medos y babilonios tomó Assur en 614 y Nínive en 612 a. C. El imperio neobabilónico de Nabopolasar y Nabucodonosor II heredó el espacio, reconstruyó Babilonia con la puerta de Ishtar y la gran ziggurat, y deportó a las élites de Judá, episodio que la Biblia hebrea convirtió en experiencia fundacional. En 539 a. C., Ciro II de Persia entró en Babilonia; el Cilindro de Ciro presenta la conquista como restauración del culto de Marduk frente a un rey impío, en un ejercicio de propaganda dirigido a la élite sacerdotal local.\n\nMesopotamia dejó de ser un centro político independiente, pero su cultura escrita continuó siglos: hay tablillas astronómicas cuneiformes fechadas ya en época romana. La astronomía babilónica, con sus registros sistemáticos de posiciones planetarias, alimentó directamente a la griega y, a través de ella, a la moderna.","callout":null},{"type":"concepts","items":[{"term":"Cuneiforme","definition":"Escritura de signos en forma de cuña impresos sobre arcilla. Sistema mixto usado para varias lenguas durante tres milenios."},{"term":"Ziggurat","definition":"Templo escalonado sobre terrazas superpuestas, centro simbólico y económico de la ciudad mesopotámica."},{"term":"Ensi / lugal","definition":"Títulos del gobernante sumerio: «gobernador» del dios de la ciudad y «hombre grande» o rey."},{"term":"Ciudad-Estado","definition":"Núcleo urbano con territorio agrícola, dios tutelar y gobierno propio. Modelo político del Dinástico Arcaico."},{"term":"Awilum / mushkenum / wardum","definition":"Las tres categorías jurídicas del Código de Hammurabi: libre pleno, dependiente y esclavo."},{"term":"Misharum","definition":"Cancelación general de deudas proclamada por el rey para evitar la ruina de los contribuyentes."},{"term":"Edubba","definition":"«Casa de las tablillas»: escuela de escribas con un currículo estable de listas, copias y matemáticas."},{"term":"Bulla y tokens","definition":"Fichas de arcilla contables y su envoltura sellada. Precedente directo de la tablilla escrita."},{"term":"Sexagesimal","definition":"Sistema numérico de base 60 mesopotámico, origen de nuestros minutos, segundos y grados."},{"term":"Salinización","definition":"Acumulación de sales en suelos irrigados con fuerte evaporación. Documentada en el paso del trigo a la cebada."}]},{"type":"debates","items":[{"question":"¿Era la economía mesopotámica una economía de templo redistributiva o existían mercados?","positions":[{"school":"Ciudad-templo (Deimel, años 1920-30)","argument":"Los archivos de Lagash mostrarían que el templo poseía la tierra y organizaba la producción y el reparto. No habría propiedad privada significativa ni mercado formador de precios."},{"school":"Revisión pluralista (Diakonoff, Gelb)","argument":"Los archivos de Lagash corresponden a un solo templo, no a la ciudad entera. Existían tierra comunal de familias extensas y propiedad privada transferible junto a los sectores del templo y del palacio."},{"school":"Sustantivismo (Polanyi) frente a formalismo","argument":"Polanyi negaba mercados formadores de precios en el mundo antiguo. Los archivos de los mercaderes asirios de Kanesh, con sociedades, créditos, intereses y arbitraje entre plazas, se han esgrimido en contra."}],"state":"Domina hoy una posición intermedia: hubo precios fluctuantes, crédito y comercio privado, pero insertos en instituciones (templo, palacio, familia) que condicionaban de forma decisiva su funcionamiento. La discusión sigue viva sobre cuánto pesaba cada sector y cómo varía por época y región."},{"question":"¿Fue el Código de Hammurabi derecho aplicado o propaganda real?","positions":[{"school":"Lectura legalista tradicional","argument":"Se trataría de una codificación vigente, destinada a unificar el derecho del reino y a ser aplicada por los tribunales, como sugiere su forma articulada y su exposición pública."},{"school":"Lectura ideológica (Kraus, Bottéro)","argument":"Los miles de documentos judiciales conservados casi nunca lo citan y a veces resuelven en sentido contrario. Sería un monumento de autolegitimación —el rey justo ante Shamash— y, quizá, una colección de precedentes ejemplares para la enseñanza."}],"state":"La lectura ideológica es hoy mayoritaria, pero se reconoce que el texto refleja normas y prácticas reales. Se prefiere hablar de «colección de sentencias» antes que de «código» en sentido moderno."},{"question":"¿Por qué se desplazó el centro de poder del sur hacia el norte de Mesopotamia?","positions":[{"school":"Degradación ecológica (Jacobsen y Adams, 1958)","argument":"La salinización progresiva de los suelos irrigados del sur redujo los rendimientos, forzó la sustitución del trigo por la cebada y minó la base agraria del poder sumerio."},{"school":"Factores políticos y militares","argument":"El desplazamiento se explicaría mejor por la presión de poblaciones amorreas y arameas, por la fragilidad fiscal de Estados hipercentralizados como Ur III y por el control de rutas comerciales del norte."}],"state":"Se admite la salinización como proceso real y bien documentado, pero se rechaza como causa única. La explicación dominante es multifactorial y subraya la interacción entre estrés ecológico, rigidez institucional y presión externa."}]},{"type":"timeline","items":[{"date":"c. 5500 a. C.","event":"Cultura de Ubaid: primeros templos y agricultura irrigada en el sur."},{"date":"c. 3500–3100 a. C.","event":"Periodo Uruk: primera gran ciudad, contabilidad y escritura protocuneiforme."},{"date":"c. 2900–2350 a. C.","event":"Dinástico Arcaico: ciudades-Estado sumerias rivales (Ur, Lagash, Umma, Kish)."},{"date":"c. 2334 a. C.","event":"Sargón de Acad funda el primer imperio territorial conocido."},{"date":"c. 2112–2004 a. C.","event":"Tercera dinastía de Ur: burocracia hiperdocumentada y códigos legales."},{"date":"c. 1792–1750 a. C.","event":"Reinado de Hammurabi de Babilonia; estela de leyes."},{"date":"c. 1595 a. C.","event":"Saqueo hitita de Babilonia; después, dominio casita."},{"date":"c. 1350–1050 a. C.","event":"Imperio asirio medio; expansión desde Assur."},{"date":"883–627 a. C.","event":"Imperio neoasirio: deportaciones sistemáticas y ejército permanente."},{"date":"668–627 a. C.","event":"Asurbanipal reúne en Nínive la gran biblioteca."},{"date":"612 a. C.","event":"Caída de Nínive ante medos y babilonios."},{"date":"605–562 a. C.","event":"Nabucodonosor II: imperio neobabilónico y deportación de Judá."},{"date":"539 a. C.","event":"Ciro II de Persia toma Babilonia; fin de la independencia mesopotámica."}]},{"type":"sources","items":[{"author":"Anónimo","title":"Epopeya de Gilgamesh (versión estándar)","year":"c. s. XII a. C.","kind":"primaria","note":"Conservada sobre todo en la biblioteca de Asurbanipal. Contiene el relato del diluvio."},{"author":"Hammurabi","title":"Estela de leyes","year":"c. 1750 a. C.","kind":"primaria","note":"Prólogo, 282 disposiciones casuísticas y epílogo. Hallada en Susa en 1901."},{"author":"Enheduanna","title":"Himnos a Inanna","year":"c. 2280 a. C.","kind":"primaria","note":"Primera autoría literaria conocida por su nombre. Hija de Sargón y sacerdotisa en Ur."},{"author":"Darío I","title":"Inscripción de Behistún","year":"c. 520 a. C.","kind":"primaria","note":"Texto trilingüe cuya copia por Rawlinson permitió descifrar el cuneiforme."},{"author":"Anónimo","title":"Cilindro de Ciro","year":"539 a. C.","kind":"primaria","note":"Presenta la conquista persa como restauración del culto de Marduk. Documento de propaganda."},{"author":"Thorkild Jacobsen y Robert Adams","title":"«Salt and Silt in Ancient Mesopotamian Agriculture», Science","year":"1958","kind":"estudio","note":"Formula la tesis de la salinización como factor de declive del sur."},{"author":"Igor M. Diakonoff","title":"Structure of Society and State in Early Dynastic Sumer","year":"1959","kind":"estudio","note":"Refuta el modelo de la ciudad-templo de Deimel."},{"author":"Denise Schmandt-Besserat","title":"Before Writing","year":"1992","kind":"estudio","note":"Traza el origen contable de la escritura a partir de las fichas de arcilla."},{"author":"Jean Bottéro","title":"Mésopotamie. L''écriture, la raison et les dieux","year":"1987","kind":"estudio","note":"Reinterpreta el Código de Hammurabi y la racionalidad mesopotámica."},{"author":"Marc Van De Mieroop","title":"A History of the Ancient Near East","year":"2004 (3.ª ed. 2015)","kind":"estudio","note":"Manual de referencia actualizado sobre el conjunto del Próximo Oriente antiguo."},{"author":"Amélie Kuhrt","title":"The Ancient Near East, c. 3000–330 BC","year":"1995","kind":"estudio","note":"Síntesis crítica de amplio alcance, atenta a los problemas de fuentes."}]},{"type":"images","items":[{"src":"/img/mesopotamia/portada.jpg","alt":"Panel de mosaico con incrustaciones de concha y lapislázuli en tres registros con carros, soldados y prisioneros","width":1200,"height":525,"role":"portada","caption":"Cara de la guerra del Estandarte de Ur, hacia 2600 a. C.","author":"Unknown author Unknown author","title":"Standard of Ur - War","year":"2600","source":"Wikimedia Commons","license":"Public domain","url":"https://commons.wikimedia.org/wiki/File:Standard_of_Ur_-_War.jpg"}]}]'::jsonb, 0, true
from public.topics where slug = 'mesopotamia'
on conflict (topic_id, position) do update set
  title = excluded.title, body = excluded.body, published = excluded.published;

-- Lección: mundo-actual
insert into public.lessons (topic_id, title, body, position, published)
select id, 'El mundo desde 1991', '[{"type":"section","title":"El momento unipolar","text":"La década de los noventa empezó con una expectativa. Francis Fukuyama había publicado en 1989 un ensayo que sostenía que la democracia liberal y el mercado no tenían ya rival ideológico y que en ese sentido la historia había terminado. La tesis se caricaturizó mucho, porque no afirmaba que dejaran de ocurrir cosas, sino que no quedaban alternativas sistémicas con pretensión universal. Samuel Huntington respondió en 1993 que los conflictos futuros se librarían entre civilizaciones y no entre ideologías, una tesis igualmente discutida y todavía más citada.\n\nLa realidad de los noventa fue menos limpia que cualquiera de las dos. Hubo una expansión democrática real, con transiciones en América Latina, Europa oriental, Sudáfrica y parte de Asia, y una integración económica sin precedentes tras la creación de la Organización Mundial del Comercio en 1995. Pero también hubo guerras de desintegración estatal en Yugoslavia y en el Cáucaso, un genocidio en Ruanda que la comunidad internacional vio venir y no detuvo, y crisis financieras en México, Asia y Rusia que mostraron la fragilidad de los flujos de capital liberalizados.\n\nEl modelo económico dominante se resumió en lo que John Williamson llamó Consenso de Washington: disciplina fiscal, liberalización comercial y financiera, privatizaciones y desregulación. Se aplicó como condición de los préstamos del Fondo Monetario y del Banco Mundial y produjo resultados muy desiguales. En Europa oriental la terapia de choque provocó un hundimiento del producto y de la esperanza de vida en Rusia; en Asia oriental los países que crecieron lo hicieron con políticas industriales activas que el consenso desaconsejaba.\n\nEuropa siguió su propio camino. Maastricht convirtió en 1992 la Comunidad Económica en Unión Europea, con ciudadanía común y una moneda única que llegaría en 1999. Fue una apuesta política enorme: unificar la moneda sin unificar la política fiscal, con la idea de que la integración monetaria arrastraría al resto. La ampliación al este, entre 2004 y 2007, incorporó a diez países del antiguo bloque soviético y duplicó el número de miembros.\n\nEstados Unidos ejerció una hegemonía que sus propios estrategas describían como un momento unipolar, no como un estado permanente. Intervino en los Balcanes tarde y con eficacia, promovió la ampliación de la OTAN pese a las advertencias de Kennan y otros sobre la reacción rusa, y sostuvo un orden institucional que le beneficiaba y que a la vez le imponía límites. La discusión sobre si ese orden era liberal o simplemente estadounidense sigue abierta.","callout":"Fukuyama no dijo que fueran a dejar de pasar cosas. Dijo que no quedaban alternativas sistémicas con pretensión universal. Treinta años después la primera afirmación es obviamente falsa y la segunda vuelve a discutirse."},{"type":"section","title":"El 11 de septiembre y las guerras del terror","text":"Los atentados del 11 de septiembre de 2001 mataron a casi tres mil personas y reorganizaron la política internacional. La respuesta inmediata, la invasión de Afganistán, contó con amplio apoyo y derribó al régimen talibán en semanas; la ocupación duró veinte años, costó cientos de miles de millones y terminó en 2021 con el regreso del mismo régimen. La invasión de Irak en 2003, en cambio, se hizo sin autorización del Consejo de Seguridad, sobre la base de unas armas de destrucción masiva que no existían, y frente a las mayores manifestaciones simultáneas de la historia.\n\nLas consecuencias fueron mayores que la guerra. Irak se desintegró en una guerra civil sectaria, la disolución del ejército iraquí dejó a cientos de miles de hombres armados sin trabajo, y de ese caos salió una organización que en 2014 proclamó un califato sobre parte de Irak y Siria. El informe Chilcot británico de 2016 concluyó que la acción militar no era el último recurso y que las bases de inteligencia se presentaron con una certeza que no estaba justificada.\n\nLa lucha antiterrorista transformó también el interior de las democracias. Legislación de excepción, vigilancia masiva de comunicaciones revelada en 2013 por documentos filtrados desde la propia inteligencia estadounidense, detenciones indefinidas sin juicio en Guantánamo y un programa de entregas y tortura que varios Estados europeos facilitaron. El debate sobre la compatibilidad entre seguridad y derechos dejó de ser teórico.\n\nEn el mundo árabe, las revueltas de 2011 mostraron el otro lado. Movilizaciones masivas derribaron a gobiernos en Túnez, Egipto, Libia y Yemen, con una organización horizontal en la que las redes sociales tuvieron un papel instrumental que después se exageró. El balance a medio plazo fue duro: consolidación democrática solo en Túnez y de forma frágil, restauración autoritaria en Egipto, y guerras prolongadas en Libia, Siria y Yemen que produjeron la mayor crisis de refugiados desde 1945.\n\nLa conclusión estratégica que muchos extrajeron fue la de los límites del poder militar. Dos décadas de intervenciones no produjeron ni Estados estables ni democracias, y sí un descrédito de la idea de intervención humanitaria que había ganado terreno en los noventa. La doctrina de la responsabilidad de proteger, aprobada por Naciones Unidas en 2005, quedó muy debilitada tras el uso que se hizo de ella en Libia en 2011.","callout":null},{"type":"section","title":"La crisis de 2008 y la política que produjo","text":"La crisis financiera de 2008 comenzó en el mercado hipotecario estadounidense, se propagó por un sistema bancario internacional cargado de productos estructurados cuyo riesgo nadie había medido bien, y se convirtió en la mayor contracción desde los años treinta tras la quiebra de Lehman Brothers en septiembre. Fue una crisis del núcleo del sistema, no de su periferia, y la respuesta requirió rescates públicos de una escala inédita.\n\nAdam Tooze ha mostrado que la crisis fue mucho más transatlántica de lo que se contó: los bancos europeos estaban entre los mayores compradores de activos estadounidenses y sobrevivieron gracias a líneas de dólares abiertas por la Reserva Federal. La eurozona, sin embargo, convirtió una crisis bancaria en una crisis de deuda soberana, porque sus Estados no emitían en una moneda que controlaran y no existía un prestamista de última instancia hasta que el Banco Central Europeo asumió ese papel en 2012.\n\nLa respuesta europea fue la austeridad. Recortes de gasto y reformas estructurales en Grecia, Portugal, Irlanda, España e Italia, con caídas del producto de dos dígitos en el caso griego, paro juvenil superior al cincuenta por ciento y una emigración de jóvenes cualificados. El debate técnico sobre si el ajuste era necesario, excesivo o mal secuenciado se cruzó con otro sobre quién había decidido: los programas los negociaban instituciones sin responsabilidad electoral ante las poblaciones afectadas.\n\nLas consecuencias políticas se vieron pronto. Aparecieron o crecieron partidos que impugnaban el consenso anterior, por la izquierda y sobre todo por la derecha, con una combinación de crítica a la globalización, a la inmigración y a las élites tecnocráticas. El Brexit en 2016 y la elección presidencial estadounidense del mismo año fueron los dos resultados que hicieron visible el cambio en los dos países que habían liderado el orden liberal.\n\nSobre por qué ocurrió hay dos grandes explicaciones. La económica, defendida entre otros por Dani Rodrik, sostiene que la deslocalización industrial, el estancamiento salarial y la crisis produjeron un electorado con motivos objetivos de agravio. La cultural, formulada por Pippa Norris y Ronald Inglehart, sostiene que lo decisivo es una reacción de valores frente al cambio social y generacional. Los datos electorales sostienen parcialmente ambas y no permiten cerrar la discusión.","callout":"La crisis de la eurozona no fue solo un problema de deuda: fue el descubrimiento de que una moneda sin Estado carece de prestamista de última instancia hasta que alguien decide serlo."},{"type":"section","title":"China y el retorno de la geopolítica","text":"El acontecimiento económico más importante del período no ocurrió en Occidente. China creció a tasas de dos dígitos durante tres décadas, sacó de la pobreza extrema a más de setecientos millones de personas y pasó de representar menos del dos por ciento del producto mundial en 1980 a ser la primera economía en paridad de poder adquisitivo. Su ingreso en la Organización Mundial del Comercio en 2001 aceleró la integración de su industria en las cadenas globales de valor.\n\nLa apuesta occidental fue que la integración económica produciría convergencia política. No ocurrió. El sistema chino se consolidó como un Estado de partido único con economía mixta, capacidad de planificación a largo plazo y un aparato de vigilancia tecnológica sin precedentes. Desde 2013, la Iniciativa de la Franja y la Ruta ha financiado infraestructuras en decenas de países, con debate abierto sobre si genera desarrollo o dependencia financiera.\n\nLa reacción estadounidense pasó de la integración a la competencia estratégica, con aranceles desde 2018, restricciones a la exportación de semiconductores avanzados y una política de reindustrialización. El resultado no ha sido una desconexión completa sino una fragmentación selectiva de las cadenas de suministro, con costes crecientes y con terceros países intentando no elegir bando.\n\nRusia recorrió otro camino. La década de los noventa dejó allí un hundimiento económico, una privatización que creó una oligarquía y una humillación nacional que la política posterior explotó. Desde 2000 se consolidó un régimen personalista sostenido por los ingresos energéticos, y desde 2008 en Georgia, 2014 en Crimea y 2022 en Ucrania se recurrió a la fuerza para revisar fronteras. La guerra en Ucrania desde 2022 ha sido el conflicto interestatal más grande en Europa desde 1945 y ha reactivado la OTAN, con la incorporación de Finlandia y Suecia.\n\nEl resultado agregado es un sistema que no es unipolar ni bipolar. India, Brasil, Indonesia, Turquía, los Estados del Golfo y varios países africanos actúan con autonomía creciente y se niegan a alinearse automáticamente, en una actitud que recuerda al No Alineamiento sin su vocabulario. Los organismos multilaterales heredados de 1945 reflejan cada vez peor esa distribución de poder, y su reforma lleva décadas bloqueada.","callout":null},{"type":"section","title":"Digitalización y esfera pública","text":"La web se abrió al uso público en 1993 y en tres décadas ha reorganizado la economía, la política y la vida cotidiana. La primera fase, hasta la crisis de las puntocom en 2000, fue de expansión desordenada; la segunda, desde mediados de la década siguiente, se caracterizó por la concentración: un puñado de plataformas globales que intermedian la búsqueda, la comunicación, el comercio y la publicidad, con una capitalización superior al producto de muchos Estados.\n\nShoshana Zuboff ha descrito ese modelo como capitalismo de vigilancia: un negocio basado en extraer datos de comportamiento para predecir y orientar la conducta futura, con la publicidad como primer producto y con la atención humana como recurso extraído. Otros análisis subrayan más los efectos de red y la lógica de monopolio natural que la novedad del modelo, pero coinciden en el diagnóstico de concentración.\n\nEl efecto sobre la esfera pública ha sido profundo y no unívoco. Las plataformas han permitido organizar movilizaciones sin estructuras previas, dar voz a quien no la tenía y desintermediar el acceso a la información. También han fragmentado el espacio informativo común, premiado la indignación por su rendimiento en atención, abaratado hasta lo trivial la producción de desinformación y hundido el modelo económico del periodismo profesional, que era el principal productor de verificación.\n\nLa vigilancia es la otra cara. Las revelaciones de 2013 sobre los programas de captación masiva de comunicaciones mostraron capacidades estatales que ninguna legislación había autorizado explícitamente. En paralelo, sistemas de reconocimiento facial y de puntuación social han sido desplegados con distintos grados de intensidad, y la Unión Europea ha intentado responder con normativa sobre protección de datos y sobre inteligencia artificial, con efecto extraterritorial de hecho.\n\nLa irrupción de sistemas de inteligencia artificial generativa desde 2022 ha añadido una capa nueva, con efectos sobre el trabajo cualificado, la educación y la propia noción de autoría y de prueba documental. Es demasiado pronto para escribir su historia, y precisamente por eso conviene decirlo: un historiador que en 1995 hubiera pronosticado los efectos de internet se habría equivocado en casi todo.","callout":"El hundimiento económico del periodismo profesional no es un daño colateral de la digitalización: es la retirada del principal actor que producía verificación de manera sistemática."},{"type":"section","title":"Clima, pandemia y balance provisional","text":"El cambio climático es el proceso de fondo del período y el que menos encaja en las periodizaciones políticas. La ciencia está establecida desde hace décadas: la concentración de gases de efecto invernadero ha subido por encima de cualquier nivel de los últimos ochocientos mil años y la temperatura media global ha aumentado más de un grado respecto de la era preindustrial. Los informes sucesivos del panel intergubernamental han ido reduciendo la incertidumbre y acortando los plazos.\n\nLa respuesta institucional ha sido lenta y desigual: del Protocolo de Kioto de 1997, con objetivos vinculantes y sin Estados Unidos, al Acuerdo de París de 2015, con participación casi universal y compromisos voluntarios. El coste de las renovables se ha hundido más rápido de lo que casi nadie preveía, lo que ha hecho viable una transición que hace veinte años parecía inasumible; el ritmo sigue siendo insuficiente respecto de los objetivos declarados. La discusión sobre justicia climática, es decir, sobre quién emitió históricamente y quién sufre las consecuencias, es a la vez científica y política.\n\nLa pandemia de covid-19, desde 2020, fue el primer acontecimiento verdaderamente global y simultáneo de la era digital. Provocó millones de muertes, confinamientos que afectaron a la mayor parte de la humanidad, una contracción económica seguida de una respuesta fiscal y monetaria sin precedentes, y un desarrollo de vacunas en un tiempo récord acompañado de un reparto muy desigual. Puso a prueba la capacidad estatal, la cooperación internacional y la confianza pública en la ciencia, con resultados distintos en cada país y sin una correlación simple con el tipo de régimen.\n\nSobre el balance de la globalización hay datos que apuntan en direcciones opuestas y hay que sostener los dos. La pobreza extrema mundial cayó de cerca del cuarenta por ciento de la población en 1990 a menos del diez antes de la pandemia, la mortalidad infantil se redujo a menos de la mitad y la escolarización se generalizó. Al mismo tiempo, la desigualdad interna creció en la mayoría de los países ricos y en varios emergentes, y la curva del elefante de Branko Milanovic muestra con claridad quién ganó y quién no: las clases medias asiáticas y el uno por ciento global, no los trabajadores industriales de Occidente.\n\nEscribir la historia de este período tiene dos dificultades específicas. La primera es documental: buena parte de las fuentes está clasificada, dispersa en servidores privados o en formatos que se degradan, y la abundancia de datos no equivale a disponibilidad. La segunda es de perspectiva: no sabemos qué acontecimiento de los últimos treinta años resultará decisivo. Es exactamente el problema que tenía en 1935 alguien que intentara explicar 1919, y la única defensa disponible es la misma: describir los procesos con precisión y desconfiar de las conclusiones redondas.","callout":null},{"type":"concepts","items":[{"term":"Momento unipolar","definition":"Situación posterior a 1991 con una sola superpotencia. Sus propios teóricos la describieron como transitoria y no como un estado permanente del sistema."},{"term":"Consenso de Washington","definition":"Paquete de disciplina fiscal, liberalización, privatización y desregulación promovido por los organismos financieros internacionales desde los años noventa."},{"term":"Cadenas globales de valor","definition":"Fragmentación de la producción entre países según ventajas de coste y especialización. Base material de la globalización productiva."},{"term":"Fin de la historia","definition":"Tesis de Fukuyama de 1989: no quedan alternativas sistémicas con pretensión universal frente a la democracia liberal y el mercado."},{"term":"Choque de civilizaciones","definition":"Tesis de Huntington de 1993 según la cual los conflictos futuros seguirían líneas culturales y religiosas en vez de ideológicas."},{"term":"Responsabilidad de proteger","definition":"Principio aprobado por Naciones Unidas en 2005 que admite la intervención ante atrocidades masivas. Muy debilitado tras su uso en Libia en 2011."},{"term":"Vigilancia masiva","definition":"Captación indiscriminada de comunicaciones por servicios de inteligencia, documentada en 2013. Planteó el conflicto entre seguridad y derechos en términos concretos."},{"term":"Crisis de las subprime","definition":"Colapso iniciado en el mercado hipotecario estadounidense en 2007 y extendido por productos estructurados cuyo riesgo estaba mal medido."},{"term":"Austeridad","definition":"Política de recorte del gasto público aplicada en la eurozona tras 2010 para reducir deuda. Su necesidad y su secuencia siguen discutiéndose."},{"term":"Populismo","definition":"Estilo político que opone un pueblo homogéneo a una élite corrupta. Su auge desde 2008 admite explicaciones económicas y culturales que compiten entre sí."},{"term":"Capitalismo de vigilancia","definition":"Modelo descrito por Zuboff basado en extraer datos de comportamiento para predecir y orientar la conducta, con la atención como recurso principal."},{"term":"Franja y la Ruta","definition":"Programa chino de financiación de infraestructuras en decenas de países desde 2013, discutido entre motor de desarrollo y generador de dependencia."},{"term":"Acuerdo de París","definition":"Tratado climático de 2015 con participación casi universal y compromisos nacionales voluntarios, frente al modelo vinculante y parcial de Kioto."},{"term":"Curva del elefante","definition":"Representación de Milanovic del cambio de renta global entre 1988 y 2008: ganan las clases medias asiáticas y el uno por ciento, se estancan los trabajadores occidentales."}]},{"type":"debates","items":[{"question":"¿Cómo hay que interpretar el orden surgido en 1991?","positions":[{"school":"Fin de la historia (Fukuyama, 1989)","argument":"No quedan alternativas sistémicas con pretensión universal. Los conflictos seguirán, pero ya no entre modelos rivales de organización política y económica con vocación de sustituir al liberalismo."},{"school":"Choque de civilizaciones (Huntington, 1993)","argument":"La ideología deja paso a la cultura como línea de fractura. Los conflictos se producirán entre bloques civilizatorios y no dentro de un marco común de valores."},{"school":"Retorno del realismo (Mearsheimer; Kagan)","argument":"La unipolaridad era una anomalía transitoria. Con el ascenso de nuevos polos vuelve la competencia entre grandes potencias, que es la situación normal del sistema internacional."}],"state":"Los tres marcos se citan más de lo que se leen. El período ha desmentido las predicciones concretas de todos ellos y ha dado la razón parcialmente al diagnóstico realista sobre la transitoriedad de la unipolaridad."},{"question":"¿Ha sido positiva la globalización?","positions":[{"school":"Convergencia global (Milanovic)","argument":"La pobreza extrema cayó del cuarenta a menos del diez por ciento de la humanidad y la desigualdad entre países se redujo por primera vez desde la revolución industrial. Es la mayor mejora material de la historia."},{"school":"Coste interno y político (Rodrik; Piketty)","argument":"La desigualdad dentro de los países creció, la desindustrialización destruyó comunidades enteras en Occidente y la liberalización financiera transfirió a los Estados la factura de las crisis."}],"state":"Las dos series de datos son correctas y describen fenómenos distintos: la global y la nacional. La discusión útil se ha desplazado a qué tipo de globalización es compatible con la cohesión política interna."},{"question":"¿Qué explica el auge de los populismos desde 2008?","positions":[{"school":"Explicación económica (Rodrik)","argument":"La deslocalización, el estancamiento salarial, la austeridad y la percepción de que las crisis las pagan siempre los mismos crearon un electorado con motivos objetivos de agravio."},{"school":"Reacción cultural (Norris e Inglehart, 2019)","argument":"Lo decisivo es un rechazo generacional al cambio de valores en materia de género, inmigración y diversidad. El voto correlaciona mejor con actitudes culturales que con renta."},{"school":"Fallo institucional (Levitsky y Ziblatt, 2018)","argument":"El factor crítico es la erosión de las normas no escritas de la competencia democrática y la disposición de partidos establecidos a pactar con fuerzas que no aceptan las reglas."}],"state":"Los datos electorales sostienen parcialmente las tres. La investigación reciente tiende a combinarlas mediante mecanismos: el agravio económico activa marcos culturales preexistentes cuando las instituciones no canalizan el conflicto."}]},{"type":"timeline","items":[{"date":"1991","event":"Disolución de la URSS, primera guerra del Golfo e inicio de las guerras de Yugoslavia."},{"date":"1992–1993","event":"Tratado de Maastricht y nacimiento de la Unión Europea. Entra en vigor el mercado único."},{"date":"1994","event":"Genocidio de Ruanda, con unas ochocientas mil víctimas en cien días y una inacción internacional documentada."},{"date":"1995","event":"Creación de la Organización Mundial del Comercio y matanza de Srebrenica."},{"date":"1999","event":"Nace el euro como moneda de cuenta. Intervención de la OTAN en Kosovo sin mandato del Consejo de Seguridad."},{"date":"2001","event":"Atentados del 11 de septiembre, invasión de Afganistán e ingreso de China en la OMC."},{"date":"2003","event":"Invasión de Irak sin autorización de Naciones Unidas y sin que aparecieran las armas alegadas."},{"date":"2008","event":"Quiebra de Lehman Brothers y crisis financiera global. Recesión y rescates bancarios masivos."},{"date":"2010–2012","event":"Primaveras árabes, crisis de la deuda en la eurozona y políticas de austeridad."},{"date":"2014","event":"Anexión rusa de Crimea y guerra en el este de Ucrania. Fin del orden europeo posterior a 1991."},{"date":"2015","event":"Acuerdo de París sobre el clima y Objetivos de Desarrollo Sostenible de Naciones Unidas."},{"date":"2016","event":"Referéndum del Brexit y elección presidencial estadounidense: dos resultados que reordenan la política occidental."},{"date":"2020–2022","event":"Pandemia de covid-19, con millones de muertos, y guerra a gran escala en Ucrania desde febrero de 2022."}]},{"type":"sources","items":[{"author":"Francis Fukuyama","title":"El fin de la Historia y el último hombre","year":"1992","kind":"primaria","note":"Formulación completa de una tesis que se cita casi siempre en su versión caricaturizada."},{"author":"Samuel Huntington","title":"El choque de civilizaciones","year":"1996","kind":"primaria","note":"Marco alternativo al anterior, enormemente influyente en el debate posterior al 11 de septiembre."},{"author":"Estados miembros de la CE","title":"Tratado de Maastricht","year":"1992","kind":"primaria","note":"Crea la Unión Europea y el compromiso de moneda única. Base jurídica de la integración posterior."},{"author":"John Williamson","title":"What Washington Means by Policy Reform","year":"1990","kind":"primaria","note":"Texto que acuñó la expresión Consenso de Washington, después usada en un sentido más amplio que el original."},{"author":"Naciones Unidas","title":"Informe Carlsson sobre Ruanda","year":"1999","kind":"primaria","note":"Investigación oficial sobre la inacción internacional durante el genocidio de 1994."},{"author":"Comisión Nacional sobre los Ataques Terroristas","title":"Informe del 11-S","year":"2004","kind":"primaria","note":"Reconstrucción oficial de los atentados y de los fallos de coordinación previos."},{"author":"John Chilcot","title":"Informe de la investigación sobre Irak","year":"2016","kind":"primaria","note":"Concluye que la acción militar no fue el último recurso y que la inteligencia se presentó con certeza injustificada."},{"author":"Naciones Unidas","title":"Acuerdo de París","year":"2015","kind":"primaria","note":"Compromisos nacionales voluntarios con revisión periódica. Modelo opuesto al vinculante de Kioto."},{"author":"Grupo Intergubernamental de Expertos sobre el Cambio Climático","title":"Informes de evaluación","year":"1990–2023","kind":"primaria","note":"Síntesis periódica del estado de la ciencia climática, con incertidumbres explicitadas."},{"author":"Naciones Unidas","title":"Objetivos de Desarrollo Sostenible","year":"2015","kind":"primaria","note":"Agenda global para 2030 que sustituye a los Objetivos del Milenio y amplía su alcance."},{"author":"Eric Hobsbawm","title":"Historia del siglo XX","year":"1994","kind":"estudio","note":"Cierra el siglo corto en 1991 y plantea el problema de escribir historia sin distancia."},{"author":"Joseph Stiglitz","title":"El malestar en la globalización","year":"2002","kind":"estudio","note":"Crítica desde dentro de las instituciones financieras internacionales a la condicionalidad de los años noventa."},{"author":"Tony Judt","title":"Postguerra","year":"2005","kind":"estudio","note":"Historia de Europa hasta 2005 que conecta el período posterior a 1991 con la larga posguerra."},{"author":"Branko Milanovic","title":"Desigualdad mundial","year":"2016","kind":"estudio","note":"Origen de la curva del elefante y del análisis de la desigualdad global frente a la nacional."},{"author":"Thomas Piketty","title":"El capital en el siglo XXI","year":"2013","kind":"estudio","note":"Series históricas de largo plazo sobre concentración de renta y patrimonio en los países desarrollados."},{"author":"Dani Rodrik","title":"La paradoja de la globalización","year":"2011","kind":"estudio","note":"Formula el trilema entre hiperglobalización, soberanía nacional y democracia."},{"author":"Adam Tooze","title":"Crash","year":"2018","kind":"estudio","note":"Historia global de la crisis de 2008 que muestra su carácter transatlántico y el papel de la Reserva Federal."},{"author":"Shoshana Zuboff","title":"La era del capitalismo de la vigilancia","year":"2019","kind":"estudio","note":"Analiza el modelo de negocio basado en datos de comportamiento y su efecto sobre la autonomía individual."},{"author":"Steven Levitsky y Daniel Ziblatt","title":"Cómo mueren las democracias","year":"2018","kind":"estudio","note":"Estudio comparado sobre la erosión democrática desde dentro, sin golpes de Estado."},{"author":"Pippa Norris y Ronald Inglehart","title":"Cultural Backlash","year":"2019","kind":"estudio","note":"Defiende la explicación cultural y generacional del voto populista frente a la puramente económica."},{"author":"Peter Frankopan","title":"Las rutas de la seda","year":"2015","kind":"estudio","note":"Relectura de la historia mundial que descentra Europa y ayuda a situar el ascenso asiático actual."},{"author":"Mark Mazower","title":"Gobernar el mundo","year":"2012","kind":"estudio","note":"Historia de las instituciones internacionales y de las ideas de gobierno global desde 1815."}]},{"type":"images","items":[{"src":"/img/mundo-actual/portada.jpg","alt":"Representación gráfica de las conexiones de internet como una maraña radial de líneas de colores sobre fondo negro","width":1200,"height":1200,"role":"portada","caption":"Mapa parcial de internet trazado a partir de rutas de red. Ilustración de datos, no una fotografía.","author":"The Opte Project","title":"Internet map 1024","year":"2005","source":"Wikimedia Commons","license":"CC BY 2.5","url":"https://commons.wikimedia.org/wiki/File:Internet_map_1024.jpg"}]}]'::jsonb, 0, true
from public.topics where slug = 'mundo-actual'
on conflict (topic_id, position) do update set
  title = excluded.title, body = excluded.body, published = excluded.published;

-- Lección: plena-edad-media
insert into public.lessons (topic_id, title, body, position, published)
select id, 'Ciudades, comercio y universidades', '[{"type":"section","title":"El despegue del año mil","text":"Todo lo demás depende de esto: entre el siglo X y el XIV la población europea pasó de unos treinta y cinco o cuarenta millones a unos setenta u ochenta. Las cifras son estimaciones construidas sobre censos fiscales parciales y registros señoriales, con márgenes amplios, pero la dirección no se discute. Ese crecimiento exigió más alimento, y el alimento salió de roturar y de producir mejor.\n\nLa roturación fue el motor menos vistoso y más decisivo: se talaron bosques, se desecaron marismas, se ganó tierra al mar en Flandes y se colonizó hacia el este del Elba. En paralelo se difundieron un conjunto de técnicas que no eran nuevas pero que ahora se combinaron: el arado pesado de vertedera, capaz de voltear los suelos húmedos y arcillosos del norte, la collera rígida que permite tirar del caballo sin ahogarlo, la herradura, el enganche en fila y la rotación trienal, que deja en barbecho un tercio de la tierra en lugar de la mitad y añade una siembra de primavera de leguminosas, con el efecto adicional de fijar nitrógeno y mejorar la dieta.\n\nLa energía hidráulica se generalizó. El Domesday Book de 1086 registra en Inglaterra más de cinco mil quinientos molinos de agua para una población en torno a uno o dos millones de habitantes: un molino por cada pocos centenares de personas. Los molinos no solo molían grano; se aplicaron al batán de los paños, a la sierra, al martillo de forja y al fuelle.\n\nLynn White Jr. defendió en 1962 que estas innovaciones técnicas explican por sí solas la transformación social de Europa. La crítica posterior ha corregido su cronología —el arado pesado y el estribo aparecen antes y se difunden más despacio de lo que él suponía— y ha desconfiado del determinismo: la técnica estaba disponible mucho antes de que se generalizara, así que hay que explicar por qué se adoptó cuando se adoptó. La respuesta apunta a la demanda, a la relativa estabilidad tras el fin de las incursiones vikingas, magiares y sarracenas, y a señores interesados en un excedente comercializable.\n\nSuele añadirse un factor climático, el llamado óptimo medieval de los siglos X a XIII. Conviene manejarlo con cuidado: las reconstrucciones globales muestran que no hubo un calentamiento sincrónico en todo el planeta, sino anomalías regionales, y que en Europa occidental el efecto fue real pero moderado. Es un factor favorable, no una explicación.","callout":"La rotación trienal no solo aumenta la superficie sembrada de la mitad a dos tercios: la siembra de primavera introduce leguminosas, que fijan nitrógeno y aportan proteína. Un cambio de calendario agrícola es también un cambio de dieta."},{"type":"section","title":"La ciudad: un estatuto jurídico antes que un tamaño","text":"En la Edad Media una ciudad no se define por el número de habitantes sino por el derecho. Lo que separa a la villa del campo es una carta —fuero, carta de franquicia, privilegio— que sustituye las obligaciones señoriales por un censo fijo en dinero, reconoce un tribunal propio, una milicia, un mercado y, a menudo, la libertad personal de quien reside en ella un tiempo. La fórmula alemana que resume la práctica, «el aire de la ciudad hace libre al cabo de un año y un día», es una formulación tardía de una costumbre real: el siervo huido que no era reclamado en ese plazo quedaba libre.\n\nLa forma más ambiciosa fue la comuna: una asociación jurada de vecinos que se compromete mutuamente y negocia, compra o arranca por la fuerza el gobierno de la ciudad a su señor u obispo. Aparece en el norte de Italia a finales del siglo XI y se extiende por Flandes, Renania y el norte de Francia. En Italia derivó en repúblicas urbanas con cónsules y después con *podestà*, un magistrado forastero contratado por un año precisamente para que no tuviera clientela local.\n\nDentro de la ciudad, la vida económica se organizó en gremios. Su función declarada era garantizar la calidad, formar aprendices y sostener a viudas y enfermos; su función efectiva incluía fijar precios, limitar la competencia y controlar quién podía ejercer un oficio. Fueron a la vez escuela técnica, seguro social y monopolio, y sus tensiones internas —maestros contra oficiales, oficios mayores contra menores— alimentaron los conflictos urbanos del siglo XIV.\n\nLas magnitudes conviene tenerlas presentes para no exagerar. Hacia 1300 París pudo rondar los doscientos mil habitantes, y Milán, Venecia y Florencia el entorno de los cien mil; pero la inmensa mayoría de las localidades con estatuto urbano tenían entre dos mil y diez mil, y más del ochenta por ciento de la población europea seguía viviendo en el campo. La ciudad fue decisiva por lo que concentraba —capital, derecho, escritura, información—, no por su peso demográfico.\n\nLa explicación clásica del renacimiento urbano la dio Henri Pirenne: las ciudades habrían nacido del comercio de larga distancia, alrededor de mercaderes ambulantes que se asentaban junto a fortalezas y monasterios. La investigación posterior ha invertido buena parte del argumento. Muchas ciudades crecieron sobre sedes episcopales que nunca desaparecieron del todo, el motor inicial fue el excedente agrario y el mercado comarcal, y el comercio internacional llegó a menudo después. La aportación de Pirenne que sí resiste es haber puesto el foco en la ciudad como sujeto histórico con dinámica propia, y no como apéndice del mundo señorial.","callout":null},{"type":"section","title":"Comercio: rutas, crédito e instrumentos","text":"El eje del comercio europeo unió dos polos manufactureros: Flandes, que tejía paños con lana inglesa, e Italia, que los acababa, teñía y redistribuía, y que controlaba el acceso a las especias, la seda y el alumbre del Mediterráneo oriental. Entre ambos se situaron las ferias de Champaña, un ciclo de seis ferias anuales encadenadas en cuatro localidades que funcionó durante casi dos siglos como cámara de compensación de Europa: allí no solo se compraban mercancías, se saldaban deudas y se cambiaban monedas bajo la protección de los condes.\n\nEn el norte, la Hansa articuló el Báltico y el mar del Norte desde Lübeck, con factorías permanentes en Nóvgorod, Bergen, Brujas y Londres, y un comercio de productos de volumen: cereal, madera, pescado salado, cera, pieles. En el sur, Venecia y Génova compitieron por las rutas del Levante y por colonias en el mar Negro; la cuarta cruzada, desviada en 1204 contra Constantinopla, se explica bastante mejor como operación comercial veneciana que como empresa religiosa.\n\nLo que hizo posible ese volumen fue una batería de instrumentos jurídicos y contables. La *commenda* asociaba a quien ponía el capital con quien viajaba y trabajaba, repartiendo el beneficio —habitualmente tres cuartas partes para el capital— y limitando la pérdida al capital aportado: es el antepasado directo de la sociedad en comandita. La letra de cambio permitió pagar en una plaza y cobrar en otra, en otra moneda, sin mover metal. La contabilidad por partida doble aparece en los libros italianos a comienzos del siglo XIV, mucho antes de que Luca Pacioli la codificara en 1494. Y en el siglo XIV se documenta ya el seguro marítimo como contrato autónomo.\n\nTodo esto chocaba con la prohibición canónica de la usura, entendida como cobrar cualquier cosa por encima del principal. La respuesta no fue ignorar la norma sino rodearla con técnica jurídica: el interés se escondía en el diferencial de cambio entre dos monedas y dos plazas, en el reparto del riesgo o en penalizaciones por demora pactadas de antemano. Los teólogos afinaron las excepciones —*damnum emergens*, *lucrum cessans*— y la práctica mercantil avanzó por ese hueco. A los judíos, excluidos de gremios y de la propiedad de la tierra en muchos territorios, se les asignó el papel de prestamistas y después se les reprochó ejercerlo.\n\nEl síntoma más claro del cambio de escala es monetario. Europa llevaba siglos sin acuñar oro de manera regular; en 1252 Génova y Florencia emitieron el genovino y el florín, y Venecia el ducado en 1284. El florín se convirtió en moneda de referencia internacional durante dos siglos.\n\nRobert Lopez llamó a este conjunto «revolución comercial», y la etiqueta ha hecho fortuna. Tiene un problema de perspectiva: los documentos de la Gueniza de El Cairo estudiados por Shelomo Goitein muestran que el mundo islámico usaba mucho antes instrumentos equivalentes —la *suftaya*, comparable a la letra de cambio, y el *qirad*, muy próximo a la *commenda*—, y Abraham Udovitch defendió que la transmisión fue directa. Europa no inventó tanto como difundió, sistematizó y llevó a escala.","callout":"La *commenda* limita la pérdida del inversor al capital aportado y reparte el beneficio con quien viaja. Responsabilidad limitada y separación entre capital y gestión: dos rasgos de la empresa moderna, documentados en Venecia en el siglo XI."},{"type":"section","title":"La universidad: una corporación con privilegios","text":"*Universitas* no significaba universidad sino corporación: el conjunto de personas asociadas para un fin, con personalidad jurídica, estatutos y jurisdicción. La universidad medieval es, literalmente, un gremio de la enseñanza, y ese origen explica casi todo lo demás.\n\nNacieron con dos modelos opuestos. En Bolonia la corporación era de estudiantes: contrataban a los profesores, les fijaban el programa y los multaban si se saltaban una lección o no terminaban el temario. En París la corporación era de maestros, agrupados por facultades y naciones, con el canciller de la catedral como contrapeso. De ahí derivan las dos familias europeas de gobierno universitario. La fecha de 1088 para Bolonia no procede de ningún documento: se fijó en 1888, cuando la ciudad organizó su octavo centenario.\n\nEl instrumento decisivo fueron los privilegios. La *Authentica Habita* de Federico I, en 1155, protegió a los estudiantes en viaje y les permitió ser juzgados por su maestro o por el obispo, no por el tribunal local. Los papas concedieron después la *licentia ubique docendi*, la licencia para enseñar en cualquier lugar de la cristiandad, que es el origen del reconocimiento internacional de títulos. Y las corporaciones descubrieron pronto su arma: la huelga y la dispersión. Tras la revuelta y la represión de 1229, los maestros de París suspendieron las clases y se marcharon dos años; en 1231 Gregorio IX cedió con *Parens scientiarum*, que reconoció a la universidad el derecho a darse estatutos propios y a suspender la docencia.\n\nEl método era tan característico como el contenido. La *lectio* comentaba un texto autorizado; la *quaestio* extraía de él un problema; la *disputatio* enfrentaba en público argumentos y contraargumentos ante un maestro que después determinaba. Abelardo había fijado el procedimiento en *Sic et non*, alineando ciento cincuenta y ocho cuestiones con autoridades contradictorias sobre cada una y dejando al lector la tarea de resolverlas. Pensar consistía en organizar el desacuerdo, no en evitarlo.\n\nEl combustible llegó de fuera. Entre los siglos XII y XIII se tradujo al latín, sobre todo desde el árabe en Toledo y desde el griego en Sicilia, el corpus completo de Aristóteles junto con los comentarios de Avicena y Averroes y la medicina y matemática griegas y árabes. La incorporación fue conflictiva: la enseñanza de la física y la metafísica aristotélicas se prohibió en París en 1210, y las condenas de 1270 y 1277 —esta última con doscientas diecinueve proposiciones— muestran hasta qué punto la institución estaba discutiendo consigo misma sobre los límites entre razón y fe.\n\nConviene no idealizarla. Se estudiaba en latín, se accedía por vía clerical, costaba dinero y las mujeres quedaban excluidas por completo. Fue una institución de una minoría muy pequeña. Su importancia está en otro sitio: creó un cuerpo profesional de intelectuales urbanos asalariados —Jacques Le Goff los llamó los intelectuales de la Edad Media— y una forma corporativa autónoma que ha sobrevivido ocho siglos.","callout":"La huelga de París de 1229 duró dos años y terminó con el papa concediendo a la universidad estatutos propios. El derecho de autogobierno académico nació de un conflicto laboral."},{"type":"section","title":"Reforma, derecho y persecución","text":"La transformación institucional más profunda del periodo empezó dentro de la Iglesia. La reforma gregoriana quiso liberar al clero del control de los poderes laicos: prohibición de la simonía, celibato obligatorio, elección de los obispos sin injerencia. El *Dictatus papae* de 1075 llevó la pretensión hasta el extremo de afirmar la potestad papal para deponer emperadores, y la querella de las investiduras que siguió, con el episodio de Canossa en 1077, terminó en el compromiso de Worms de 1122: el emperador renuncia a la investidura con los símbolos espirituales y conserva la temporal.\n\nHarold Berman propuso leer ese conflicto como una «revolución papal» fundadora de la tradición jurídica occidental. Su argumento es que la separación entre dos jurisdicciones que se reconocen mutuamente competentes obligó a definir con precisión el ámbito de cada una, y de ahí salieron el derecho canónico como sistema, la recuperación del derecho romano y la idea, poco frecuente en la historia, de que el poder está sometido a un derecho que no fabrica él mismo.\n\nLos materiales acompañaron. Hacia 1140 Graciano compuso la *Concordia de los cánones discordantes*, que aplicó al derecho de la Iglesia el mismo método escolástico de armonizar autoridades enfrentadas. En Bolonia, los glosadores reconstruyeron el *Corpus iuris civilis* justinianeo y formaron a generaciones de juristas que las monarquías contrataron de inmediato: el jurista profesional es una figura de este periodo, y el crecimiento del Estado en los siglos siguientes se apoya en él.\n\nLa misma capacidad de organización se aplicó a definir y perseguir la disidencia. El IV Concilio de Letrán de 1215 impuso la confesión anual y la comunión pascual, definió la transustanciación y ordenó signos distintivos para judíos y musulmanes. Los cátaros del Languedoc fueron combatidos con una cruzada interna entre 1209 y 1229, y a partir de los años treinta del siglo XIII se generalizó la *inquisitio*, un procedimiento judicial en el que el tribunal investiga de oficio sin necesidad de acusador, con registro escrito y archivo: una innovación procesal de largo recorrido, adoptada después por la justicia civil europea.\n\nR. I. Moore sintetizó esta deriva en 1987 con una tesis discutida y muy productiva: entre 1000 y 1250 Europa se convirtió en una «sociedad persecutoria», que construyó categorías estables de excluidos —herejes, judíos, leprosos, sodomitas— y desarrolló instituciones permanentes para identificarlos y castigarlos. Su punto decisivo es que la persecución no fue el desbordamiento espontáneo del fanatismo popular, sino el producto de un poder cada vez más letrado y burocrático que necesitaba definir sus fronteras. La crítica le ha reprochado agrupar fenómenos heterogéneos y minusvalorar la hostilidad social preexistente; el marco, sin embargo, se ha impuesto. Inglaterra expulsó a sus judíos en 1290 y Francia en 1306.\n\nA la vez, la religiosidad urbana produjo respuestas que la Iglesia consiguió integrar. Franciscanos y dominicos, fundados entre 1209 y 1216, predicaban en las ciudades, vivían de la limosna y ocuparon con rapidez las cátedras universitarias. Tomás de Aquino y Buenaventura fueron frailes mendicantes y profesores en París: la orden nacida para predicar a los pobres acabó administrando la alta cultura.","callout":null},{"type":"section","title":"Los límites del crecimiento","text":"Hacia 1270 el modelo empezó a agotarse. La roturación había llegado a tierras marginales de rendimiento bajo, las herencias fragmentaban las explotaciones, la relación entre población y superficie cultivable se deterioraba y el precio del grano subía en términos reales. La gran hambruna del norte de Europa de 1315-1317, provocada por varios años de lluvias catastróficas, encontró a una población ya en el límite. La peste negra de 1348 llegaría después sobre ese terreno.\n\nConviene además situar el episodio en su escala real. Mientras Europa redescubría la moneda de oro, la China de los Song tenía ciudades de más de un millón de habitantes, imprenta de tipos móviles desde el siglo XI y papel moneda emitido por el Estado; el mundo islámico manejaba desde antes los instrumentos de crédito que Italia adoptó; y el comercio del océano Índico movía volúmenes que el Mediterráneo no alcanzaba. Lo que distingue a la Europa de estos siglos no es una superioridad técnica ni económica, sino una forma jurídica peculiar: la proliferación de corporaciones autónomas con personalidad propia —comunas, gremios, universidades, órdenes— capaces de contratar, litigar y perdurar más allá de sus miembros. Es un argumento institucional, no una jerarquía de civilizaciones.\n\nTambién quedaron fuera del reparto los de siempre. La condición campesina mejoró en libertad jurídica pero no necesariamente en nivel de vida; las mujeres trabajaban en los oficios urbanos y en algunos casos formaban gremios propios, como los de la seda en París, pero quedaron excluidas de la universidad, de las magistraturas y de la mayoría de los maestrazgos; y las minorías religiosas pasaron de tolerancia interesada a expulsión en poco más de un siglo.\n\nEl balance, sin embargo, es el de una transformación de fondo. En el año mil Europa era un mundo rural, de intercambio local y cultura monástica; en 1300 tenía ciudades con derecho propio, una red mercantil que unía Nóvgorod con Alejandría, instrumentos de crédito reutilizables, un cuerpo de juristas profesionales y una veintena de universidades. Ninguna de esas cosas desapareció con la crisis del siglo XIV: fue el marco dentro del cual se afrontó.","callout":null},{"type":"concepts","items":[{"term":"Roturación","definition":"Puesta en cultivo de bosques, marismas y eriales. Principal fuente de alimento adicional entre los siglos XI y XIII."},{"term":"Rotación trienal","definition":"Ciclo que deja en barbecho un tercio de la tierra en vez de la mitad e introduce una siembra de primavera de leguminosas."},{"term":"Carruca","definition":"Arado pesado de vertedera con ruedas, capaz de voltear los suelos húmedos y arcillosos del norte de Europa."},{"term":"Carta de franquicia","definition":"Documento que concede a una localidad libertades, tribunal y mercado a cambio de un censo fijo. Define jurídicamente la ciudad."},{"term":"Comuna","definition":"Asociación jurada de vecinos que arranca o negocia el gobierno de la ciudad a su señor. Origen de las repúblicas urbanas italianas."},{"term":"Podestà","definition":"Magistrado forastero contratado por un año en las ciudades italianas, precisamente para que no tuviera clientela local."},{"term":"Gremio","definition":"Corporación de oficio. Escuela técnica, seguro social y monopolio a la vez: controlaba calidad, formación, precios y acceso."},{"term":"Ferias de Champaña","definition":"Ciclo de seis ferias anuales que funcionó como cámara de compensación entre Flandes e Italia durante casi dos siglos."},{"term":"Commenda","definition":"Contrato que asocia capital y trabajo viajero, reparte el beneficio y limita la pérdida al capital aportado."},{"term":"Letra de cambio","definition":"Instrumento para pagar en una plaza y cobrar en otra, en otra moneda. Permitía además ocultar el interés en el tipo de cambio."},{"term":"Usura","definition":"Cobro de cualquier cantidad por encima del principal, prohibido por el derecho canónico. Se rodeó con técnica jurídica, no se suprimió."},{"term":"Universitas","definition":"Corporación con personalidad jurídica, estatutos y jurisdicción propias. La universidad es, literalmente, un gremio de la enseñanza."},{"term":"Licentia ubique docendi","definition":"Licencia papal para enseñar en cualquier lugar de la cristiandad. Origen del reconocimiento internacional de títulos."},{"term":"Disputatio","definition":"Ejercicio público de argumentos enfrentados ante un maestro que determina. El método escolástico organiza el desacuerdo en vez de evitarlo."},{"term":"Inquisitio","definition":"Procedimiento en el que el tribunal investiga de oficio, sin acusador, con registro escrito. Innovación procesal adoptada después por la justicia civil."}]},{"type":"debates","items":[{"question":"¿Qué explica el renacimiento urbano europeo?","positions":[{"school":"Comercio de larga distancia (Pirenne)","argument":"Las ciudades nacieron del comercio: mercaderes ambulantes que se asientan junto a fortalezas y monasterios y acaban formando un núcleo con derecho propio. La burguesía es un producto del intercambio internacional."},{"school":"Crecimiento agrario y mercado comarcal","argument":"Primero hubo excedente rural y mercados locales; el comercio internacional llegó después. Muchas ciudades crecieron sobre sedes episcopales que nunca desaparecieron del todo, de modo que la continuidad pesa más que la refundación."}],"state":"La secuencia de Pirenne está invertida por la investigación posterior: el motor inicial fue agrario y local. Lo que se conserva de su aportación es haber tratado la ciudad como sujeto histórico con lógica propia y no como apéndice del mundo señorial."},{"question":"¿Hubo una «revolución comercial» europea?","positions":[{"school":"Revolución comercial (Robert S. Lopez)","argument":"Entre los siglos XI y XIII Europa creó la sociedad mercantil, la letra de cambio, la contabilidad por partida doble, el seguro y la banca, y volvió a acuñar oro. Un cambio de naturaleza, no de grado."},{"school":"Difusión desde el Mediterráneo islámico (Goitein, Udovitch)","argument":"Los documentos de la Gueniza de El Cairo muestran instrumentos equivalentes en uso mucho antes: la *suftaya*, comparable a la letra de cambio, y el *qirad*, muy próximo a la *commenda*. Europa sistematizó y escaló lo que recibió."}],"state":"Se acepta la magnitud del cambio europeo y se rechaza la idea de invención desde cero. La discusión abierta es hasta qué punto la transmisión fue directa o hubo desarrollos paralelos a partir de un fondo mediterráneo común."},{"question":"¿Se convirtió Europa en una «sociedad persecutoria»?","positions":[{"school":"Persecución construida desde arriba (R. I. Moore, 1987)","argument":"Entre 1000 y 1250 se crearon categorías estables de excluidos —herejes, judíos, leprosos, sodomitas— e instituciones permanentes para identificarlos. El motor fue un poder letrado y burocrático que necesitaba definir sus fronteras, no el fanatismo espontáneo."},{"school":"Crítica","argument":"La tesis agrupa fenómenos muy distintos bajo una sola etiqueta e infravalora la hostilidad social previa y los conflictos locales concretos que precipitaron cada episodio."}],"state":"El marco de Moore se ha impuesto como punto de partida, con matices: hoy se estudia la interacción entre la iniciativa institucional y las tensiones locales, en vez de atribuir la persecución a una sola de las dos."}]},{"type":"timeline","items":[{"date":"1075","event":"*Dictatus papae* de Gregorio VII: comienza la querella de las investiduras."},{"date":"1077","event":"Enrique IV ante Gregorio VII en Canossa."},{"date":"1086","event":"Domesday Book: el censo inglés registra más de cinco mil quinientos molinos de agua."},{"date":"c. 1088","event":"Fecha convencional de la escuela de derecho de Bolonia, fijada en 1888."},{"date":"1122","event":"Concordato de Worms: se separan jurisdicción espiritual y temporal."},{"date":"c. 1140","event":"Graciano compone el *Decreto*, base del derecho canónico clásico."},{"date":"1155","event":"*Authentica Habita*: Federico I protege a los estudiantes en camino."},{"date":"Siglos XII–XIII","event":"Ciclo de las ferias de Champaña, bisagra entre Flandes e Italia."},{"date":"1209–1216","event":"Nacen franciscanos y dominicos, órdenes de predicación urbana."},{"date":"1209–1229","event":"Cruzada albigense contra los cátaros del Languedoc."},{"date":"1215","event":"IV Concilio de Letrán: confesión anual, transustanciación y signos distintivos para judíos y musulmanes."},{"date":"1231","event":"*Parens scientiarum*: Gregorio IX consagra los privilegios de la Universidad de París."},{"date":"1252","event":"Génova y Florencia acuñan de nuevo moneda de oro; Venecia lo hará en 1284."},{"date":"1277","event":"El obispo Tempier condena 219 proposiciones enseñadas en París."},{"date":"1290","event":"Expulsión de los judíos de Inglaterra; Francia hará lo propio en 1306."}]},{"type":"sources","items":[{"author":"Gregorio VII","title":"Dictatus papae","year":"1075","kind":"primaria","note":"Veintisiete proposiciones sobre la potestad papal, incluida la de deponer emperadores."},{"author":"Administración de Guillermo I","title":"Domesday Book","year":"1086","kind":"primaria","note":"Censo fiscal de Inglaterra. Base cuantitativa para la economía rural y los molinos."},{"author":"Pedro Abelardo","title":"Sic et non","year":"c. 1120","kind":"primaria","note":"Ciento cincuenta y ocho cuestiones con autoridades contradictorias. Fija el método de la disputa escolástica."},{"author":"Graciano","title":"Concordia discordantium canonum (Decreto)","year":"c. 1140","kind":"primaria","note":"Aplica el método escolástico al derecho de la Iglesia. Base del derecho canónico clásico."},{"author":"Federico I","title":"Authentica Habita","year":"1155","kind":"primaria","note":"Protege a los estudiantes en viaje y los sustrae al tribunal local."},{"author":"Luis VII","title":"Carta de franquicia de Lorris","year":"c. 1155","kind":"primaria","note":"Modelo de fuero urbano copiado por centenares de localidades francesas."},{"author":"IV Concilio de Letrán","title":"Cánones","year":"1215","kind":"primaria","note":"Confesión anual, transustanciación y signos distintivos para judíos y musulmanes."},{"author":"Gregorio IX","title":"Parens scientiarum","year":"1231","kind":"primaria","note":"Reconoce a la Universidad de París estatutos propios tras dos años de huelga."},{"author":"Esteban Tempier","title":"Condena de 219 proposiciones","year":"1277","kind":"primaria","note":"Muestra el conflicto interno de la universidad sobre los límites entre razón y fe."},{"author":"Documentos de la Gueniza de El Cairo","title":"Correspondencia y contratos mercantiles","year":"s. XI–XIII","kind":"primaria","note":"Archivo accidental de una comunidad judía. Fuente central sobre el comercio mediterráneo islámico."},{"author":"Francesco Balducci Pegolotti","title":"La pratica della mercatura","year":"c. 1340","kind":"primaria","note":"Manual de un factor de los Bardi: pesos, monedas, aranceles y rutas hasta China."},{"author":"Henri Pirenne","title":"Las ciudades de la Edad Media","year":"1927","kind":"estudio","note":"Sitúa el origen urbano en el comercio de larga distancia. Secuencia hoy invertida, enfoque conservado."},{"author":"Lynn White Jr.","title":"Medieval Technology and Social Change","year":"1962","kind":"estudio","note":"Atribuye la transformación social a la técnica. Criticado por su cronología y su determinismo."},{"author":"Jacques Le Goff","title":"Los intelectuales en la Edad Media","year":"1957","kind":"estudio","note":"El maestro universitario como trabajador urbano y profesional del pensamiento."},{"author":"S. D. Goitein","title":"A Mediterranean Society","year":"1967-1993","kind":"estudio","note":"Reconstrucción del mundo mercantil islámico y judío a partir de la Gueniza."},{"author":"Robert S. Lopez","title":"The Commercial Revolution of the Middle Ages","year":"1971","kind":"estudio","note":"Formula la idea de revolución comercial entre los siglos X y XIII."},{"author":"Georges Duby","title":"Guerreros y campesinos","year":"1973","kind":"estudio","note":"El despegue agrario como base material de todo el proceso."},{"author":"Harold J. Berman","title":"Law and Revolution","year":"1983","kind":"estudio","note":"La querella de las investiduras como origen de la tradición jurídica occidental."},{"author":"R. I. Moore","title":"The Formation of a Persecuting Society","year":"1987","kind":"estudio","note":"La persecución sistemática como producto de un poder letrado y burocrático."}]},{"type":"images","items":[{"src":"/img/plena-edad-media/portada.jpg","alt":"Miniatura de una clase universitaria medieval: un maestro lee desde una cátedra elevada ante alumnos sentados en bancos","width":1200,"height":969,"role":"portada","caption":"Clase en la Universidad de Bolonia, miniatura de Laurentius de Voltolina, siglo XIV.","author":"Laurentius de Voltolina","title":"Liber ethicorum des Henricus de Alemannia , single sheet. Scena: Henricus de Alemannia con i suoi studenti","year":"571","source":"Wikimedia Commons","license":"Public domain","url":"https://commons.wikimedia.org/wiki/File:Laurentius_de_Voltolina_001.jpg"}]}]'::jsonb, 0, true
from public.topics where slug = 'plena-edad-media'
on conflict (topic_id, position) do update set
  title = excluded.title, body = excluded.body, published = excluded.published;

-- Lección: prehistoria
insert into public.lessons (topic_id, title, body, position, published)
select id, 'Prehistoria y neolitización', '[{"type":"section","title":"Qué es la prehistoria y con qué se estudia","text":"La prehistoria es el periodo anterior a la escritura, y por tanto una categoría relativa: termina en momentos distintos según la región. Mesopotamia sale de ella hacia 3300 a. C.; buena parte del África subsahariana o de Oceanía, milenios después. Esa relatividad ha sido criticada porque hace del alfabetismo el criterio de entrada en la historia, con una carga eurocéntrica evidente. Muchos autores prefieren hoy hablar de «sociedades sin escritura» o usar directamente las secuencias arqueológicas.\n\nLa disciplina se apoya en fuentes materiales y en técnicas de laboratorio. La datación por radiocarbono, desarrollada por Willard Libby en 1949, permitió por primera vez fechar en términos absolutos hasta unos 50.000 años; la termoluminiscencia, el uranio-torio y el potasio-argón cubren horizontes más antiguos. La paleoecología reconstruye climas mediante polen, isótopos de oxígeno y sondeos de hielo.\n\nLa transformación más importante de las últimas dos décadas ha sido la paleogenética. Desde que Svante Pääbo secuenció el genoma neandertal en 2010, el ADN antiguo ha reescrito la historia de las migraciones humanas: ha demostrado el mestizaje entre sapiens y neandertales, ha identificado a los denisovanos a partir de un fragmento de falange, y ha revelado que la Europa actual resulta de al menos tres oleadas superpuestas —cazadores-recolectores locales, agricultores anatolios y pastores esteparios.\n\nConviene una advertencia metodológica: la conservación diferencial sesga lo que vemos. La piedra y el hueso perduran; la madera, la fibra, la piel y el discurso, no. Cualquier reconstrucción de la vida prehistórica trabaja sobre un registro incompleto y sistemáticamente inclinado hacia lo duradero.","callout":"La calibración del radiocarbono corrige la variación del C-14 atmosférico. Por eso las fechas se expresan «cal BP» o «cal a. C.»: una fecha sin calibrar y otra calibrada no son comparables."},{"type":"section","title":"Evolución humana: un arbusto, no una escalera","text":"La imagen popular de una progresión lineal de simio a humano es incorrecta. La evidencia fósil dibuja un arbusto ramificado en el que varias especies de homínidos coexistieron durante largos periodos: australopitecos, parántropos, Homo habilis, Homo erectus, Homo naledi, Homo floresiensis, neandertales, denisovanos y sapiens.\n\nLos rasgos que asociamos a lo humano no aparecieron a la vez. El bipedismo es muy antiguo —las huellas de Laetoli tienen 3,6 millones de años—, mientras que el gran encefalización llegó mucho después. Las herramientas de Lomekwi, de 3,3 millones de años, son anteriores al género Homo, lo que rompe la ecuación entre fabricar útiles y ser humano.\n\nEl control del fuego fue decisivo. Richard Wrangham ha defendido en *Catching Fire* (2009) que la cocción, al externalizar parte de la digestión, permitió reducir el aparato digestivo y sostener un cerebro metabólicamente caro. La cronología exacta se discute: hay indicios en Wonderwerk hacia 1 millón de años, pero el uso sistemático solo está bien documentado desde hace unos 400.000.\n\nEl yacimiento de Atapuerca ha sido central en este debate. La Sima de los Huesos ha entregado más de 6.500 fósiles de al menos 28 individuos, un conjunto sin equivalente, y su análisis genético los sitúa en el linaje neandertal. La Gran Dolina aportó los restos de *Homo antecessor*, con marcas de corte que documentan canibalismo, probablemente de tipo nutricional.\n\nSobre los neandertales, la revisión ha sido drástica. Enterraban a sus muertos, cuidaban de individuos con lesiones incapacitantes, usaban pigmentos, fabricaban adhesivos de brea —un proceso que exige control térmico en ausencia de oxígeno— y construyeron estructuras de espeleotemas en la cueva de Bruniquel hace 176.000 años. Su desaparición como población diferenciada no fue una extinción total: entre el 1 % y el 2 % del genoma de los humanos no africanos actuales es neandertal.","callout":null},{"type":"section","title":"Sociedades cazadoras-recolectoras del Paleolítico","text":"Durante casi toda la prehistoria, los humanos vivieron en grupos móviles de tamaño reducido que explotaban recursos estacionales. Esa movilidad no implica precariedad permanente. Los estudios etnográficos de sociedades cazadoras-recolectoras recientes, sintetizados en el influyente simposio *Man the Hunter* (1968), estimaron dedicaciones de subsistencia de entre tres y cinco horas diarias, lo que llevó a Marshall Sahlins a hablar de «la sociedad opulenta original».\n\nEsa formulación se ha matizado mucho: las poblaciones estudiadas en el siglo XX ocupaban ambientes marginales y no son análogos directos de las paleolíticas. Aun así, la evidencia paleopatológica apunta en la misma dirección: los primeros agricultores presentan, respecto a los cazadores-recolectores previos, menor estatura, más caries, más anemia y más marcadores de estrés nutricional.\n\nLa organización social era probablemente igualitaria en lo económico, con fuertes mecanismos de reparto y de nivelación. Pero el registro funerario muestra excepciones llamativas: los enterramientos de Sunguir (Rusia, c. 34.000 a. C.) incluyen individuos cubiertos con miles de cuentas de marfil que representan miles de horas de trabajo. La desigualdad no espera a la agricultura.\n\nLa división sexual del trabajo tampoco fue tan rígida como se asumió. Los análisis de restos de Wilamaya Patjxa (Perú) y las revisiones de ajuares de caza en las Américas han identificado mujeres enterradas con equipo cinegético, y el estudio de marcadores óseos de actividad muestra patrones menos dicotómicos de lo esperado.","callout":"La recolección aportaba probablemente la mayor parte de las calorías en muchos entornos. La etiqueta «cazadores-recolectores» invierte, en ese sentido, el peso real de cada actividad."},{"type":"section","title":"Arte, símbolo y pensamiento","text":"El arte paleolítico europeo —Chauvet, Lascaux, Altamira, El Castillo, Tito Bustillo— constituye el corpus simbólico más antiguo conservado a gran escala. Sus temas dominantes son animales, signos geométricos y manos en negativo; las figuras humanas son escasas y a menudo esquemáticas.\n\nLas interpretaciones han cambiado con las modas teóricas. La «magia de caza» de Breuil, que veía en las pinturas un ritual propiciatorio, fue sustituida por el estructuralismo de Leroi-Gourhan, que buscaba oposiciones binarias en la distribución de las figuras, y después por lecturas chamánicas como la de David Lewis-Williams en *La mente en la caverna* (2002), basadas en la neuropsicología de los estados alterados de conciencia. Ninguna se impone hoy de forma concluyente.\n\nLa datación por uranio-torio de costras calcáreas ha alterado el marco cronológico: algunas manifestaciones de La Pasiega, Maltravieso y Ardales superarían los 64.000 años, lo que las situaría antes de la llegada de sapiens a Europa y las atribuiría a neandertales. La propuesta sigue siendo discutida metodológicamente, pero, de confirmarse, elimina el último rasgo que se reservaba en exclusiva a nuestra especie.\n\nFuera de Europa el registro es igual de antiguo: las figuras de Sulawesi y Borneo superan los 40.000 años, y en Blombos (Sudáfrica) hay grabados geométricos en ocre de hace 73.000 años. El foco europeo de los manuales refleja la historia de la investigación, no la distribución real del fenómeno.","callout":null},{"type":"section","title":"La neolitización: cómo y por qué","text":"Hacia el final del Pleistoceno, varias poblaciones del suroeste asiático empezaron a cultivar y a domesticar animales. El proceso fue lento —siglos de manipulación previa a la domesticación morfológica— e independiente en al menos siete focos mundiales: Creciente Fértil, China (mijo y arroz), Mesoamérica (maíz), Andes (patata, quinoa), Nueva Guinea (taro), África occidental (sorgo) y este de Norteamérica.\n\nSobre las causas se han propuesto tres grandes familias de explicación. Gordon Childe defendió en los años treinta la «hipótesis del oasis»: la desecación posglacial habría concentrado a humanos, plantas y animales en torno a los puntos de agua. Lewis Binford y Kent Flannery reformularon el problema en clave demográfica: la presión de población en zonas marginales habría obligado a intensificar la producción. Una tercera línea, de Jacques Cauvin en *Naissance des divinités, naissance de l''agriculture* (1994), invierte la causalidad y sitúa primero un cambio simbólico y religioso.\n\nGöbekli Tepe, excavado por Klaus Schmidt desde 1995, es la pieza que más ha forzado la revisión. Sus recintos con pilares en T de hasta cinco metros y relieves de animales datan de c. 9500 a. C. y fueron levantados por poblaciones que aún no practicaban agricultura plena. La construcción monumental precede, aquí, a la economía agrícola, y no al revés.\n\nLas consecuencias de la neolitización fueron ambivalentes. Aumentó la capacidad de carga demográfica y permitió el excedente, el almacenamiento y, con el tiempo, la desigualdad institucionalizada y el Estado. Al mismo tiempo empeoró la dieta media, aumentó la carga de trabajo, favoreció las zoonosis por convivencia con el ganado y aumentó la vulnerabilidad a las malas cosechas. Jared Diamond la llamó provocativamente «el peor error de la historia de la especie humana».\n\nEn Europa el proceso fue sobre todo migratorio, no de difusión de ideas. La paleogenética muestra que los agricultores anatolios se expandieron físicamente por el continente entre 7000 y 5500 a. C., mezclándose en proporciones variables con los cazadores-recolectores locales, y que un tercer componente —los pastores de la estepa póntica asociados a la cultura Yamnaya— llegó hacia 3000 a. C. y transformó de nuevo el paisaje genético y probablemente lingüístico de Europa.","callout":"La domesticación deja huellas morfológicas: espigas que no se disgregan solas, semillas más grandes, cuernos reducidos. Esos cambios tardan siglos en fijarse, así que la frontera entre recolectar y cultivar es un gradiente, no una línea."},{"type":"section","title":"Megalitismo, metalurgia y el umbral de la historia","text":"Entre el V y el III milenio a. C., la fachada atlántica europea levantó dólmenes, menhires, alineamientos y grandes tumbas de corredor. Newgrange, Stonehenge y el conjunto de Antequera implican planificación, movilización de trabajo y conocimientos astronómicos aplicados: varios monumentos están orientados a los solsticios.\n\nLa datación por radiocarbono desmontó la explicación difusionista clásica, que hacía derivar el megalitismo europeo del Mediterráneo oriental. Colin Renfrew mostró en *Before Civilization* (1973) que los megalitos atlánticos son anteriores a las pirámides egipcias, lo que obligó a reconocer desarrollos autónomos y a abandonar el modelo de una civilización que irradia hacia periferias pasivas.\n\nLa metalurgia introdujo un factor nuevo. El cobre primero y el bronce después —aleación con estaño, escaso y de distribución muy desigual— exigieron redes de intercambio de larga distancia y favorecieron a las élites que las controlaban. El ajuar del llamado «arquero de Amesbury», con origen isotópico centroeuropeo y enterrado cerca de Stonehenge, ilustra esa movilidad.\n\nEl final convencional de la prehistoria llega con la escritura, hacia 3300 a. C. en Uruk. Es un corte útil pero arbitrario: no cambia nada en la vida de la mayoría de la población, y a menudo separa artificialmente procesos continuos. Conviene tratarlo como una frontera documental, no como un salto civilizatorio.","callout":null},{"type":"concepts","items":[{"term":"Homínido","definition":"Miembro de la familia Hominidae. En uso corriente, los ancestros y parientes extintos del linaje humano."},{"term":"Industria lítica","definition":"Conjunto de útiles de piedra tallada característico de una tradición técnica (olduvayense, achelense, musteriense)."},{"term":"Calibración","definition":"Corrección de las fechas de radiocarbono según la variación del C-14 atmosférico. Fechas «cal BP» o «cal a. C.»."},{"term":"Paleogenética","definition":"Estudio del ADN antiguo. Ha reescrito la historia de las migraciones y demostrado el mestizaje entre especies humanas."},{"term":"Neolitización","definition":"Proceso de adopción de agricultura, ganadería, cerámica y sedentarismo. Gradual y con focos independientes."},{"term":"Domesticación","definition":"Modificación genética y morfológica de especies por selección humana sostenida durante generaciones."},{"term":"Creciente Fértil","definition":"Arco entre el Levante, Anatolia y Mesopotamia donde se documenta el primer foco de domesticación."},{"term":"Megalitismo","definition":"Tradición constructiva con grandes bloques de piedra en la Europa atlántica del V–III milenio a. C."},{"term":"Yamnaya","definition":"Cultura pastoril de la estepa póntica cuya expansión hacia 3000 a. C. transformó la genética y probablemente la lengua de Europa."},{"term":"Zoonosis","definition":"Enfermedad transmitida de animales a humanos. Su frecuencia aumentó con la convivencia ganadera del Neolítico."}]},{"type":"debates","items":[{"question":"¿Por qué se adoptó la agricultura si empeoró la salud de quienes la practicaban?","positions":[{"school":"Explicación climática (Childe, años 1930)","argument":"La desecación posglacial habría concentrado a humanos, plantas y animales en torno a oasis, forzando una convivencia que desembocó en domesticación. La agricultura sería una respuesta adaptativa a la escasez."},{"school":"Explicación demográfica (Binford, Flannery)","argument":"El crecimiento de población en zonas marginales, tras la ocupación de los mejores territorios, obligó a intensificar la obtención de alimento. La agricultura sería una salida forzada, no una mejora elegida."},{"school":"Explicación simbólica (Cauvin, 1994)","argument":"Un cambio previo en la mentalidad y en las prácticas rituales habría creado las condiciones sociales del sedentarismo. Göbekli Tepe, monumental y preagrícola, apoyaría esta secuencia."}],"state":"No hay una explicación única aceptada. La investigación actual tiende a modelos multicausales y regionales: el peso del clima, la demografía y la religión varía según el foco de domesticación, y el proceso se reconoce mucho más lento y reversible de lo que se creía."},{"question":"¿Se difundió la agricultura en Europa por migración o por adopción de ideas?","positions":[{"school":"Difusión cultural","argument":"Las poblaciones europeas de cazadores-recolectores habrían adoptado técnicas agrícolas por contacto e imitación, sin sustitución poblacional significativa."},{"school":"Difusión démica (Ammerman y Cavalli-Sforza; paleogenética)","argument":"La expansión fue de personas: agricultores procedentes de Anatolia se desplazaron por el continente entre 7000 y 5500 a. C. El ADN antiguo muestra un reemplazo poblacional sustancial, con mezcla variable según regiones."}],"state":"La paleogenética ha resuelto el debate mayoritariamente a favor de la migración, aunque con matices regionales importantes: en el Báltico y en zonas atlánticas la continuidad de los cazadores-recolectores locales fue mayor."},{"question":"¿Produjeron los neandertales arte simbólico?","positions":[{"school":"Atribución neandertal (Hoffmann et al., 2018)","argument":"Las dataciones por uranio-torio de costras sobre pinturas de La Pasiega, Maltravieso y Ardales superan los 64.000 años, antes de la llegada de sapiens a Europa. Sumadas a los pigmentos, adornos y estructuras de Bruniquel, indicarían capacidad simbólica plena."},{"school":"Escepticismo metodológico (White et al., 2020)","argument":"La datación de costras calcáreas puede sobrestimar la edad por contaminación y por sistemas abiertos al agua. Las fechas no datan el pigmento, sino el carbonato depositado sobre él."}],"state":"La discusión sigue abierta y es sobre todo técnica. La tendencia general de la disciplina, sin embargo, ha sido reducir la lista de capacidades exclusivamente sapiens: el debate ya no es si los neandertales eran simbólicos, sino en qué grado y con qué cronología."}]},{"type":"timeline","items":[{"date":"c. 3,3 M a. C.","event":"Herramientas líticas de Lomekwi (Kenia), anteriores al género Homo."},{"date":"c. 1,9 M a. C.","event":"Homo erectus: mayor capacidad craneal, bifaces achelenses y primeras salidas de África."},{"date":"c. 400.000 a. C.","event":"Uso controlado del fuego bien documentado; Sima de los Huesos (Atapuerca)."},{"date":"c. 300.000 a. C.","event":"Restos de Homo sapiens en Jebel Irhoud (Marruecos)."},{"date":"c. 45.000 a. C.","event":"Sapiens en Europa; coexistencia con neandertales durante milenios."},{"date":"c. 40.000 a. C.","event":"Arte figurativo en Chauvet, El Castillo y Sulawesi."},{"date":"c. 40.000 a. C.","event":"Extinción de los neandertales como población diferenciada."},{"date":"c. 11.600 a. C.","event":"Fin del Younger Dryas: comienza el Holoceno, cálido y estable."},{"date":"c. 9500 a. C.","event":"Göbekli Tepe: santuarios monumentales de sociedades aún no agrícolas."},{"date":"c. 8500 a. C.","event":"Domesticación de trigo, cebada, oveja y cabra en el Creciente Fértil."},{"date":"c. 7000 a. C.","event":"Çatalhöyük: gran poblado agrícola en Anatolia."},{"date":"c. 5600 a. C.","event":"La agricultura alcanza la península ibérica por vía mediterránea."},{"date":"c. 4500–2500 a. C.","event":"Megalitismo atlántico europeo: Stonehenge, Newgrange, Antequera."},{"date":"c. 3300 a. C.","event":"Metalurgia del bronce y primeras escrituras: fin convencional de la prehistoria."}]},{"type":"sources","items":[{"author":"V. Gordon Childe","title":"Man Makes Himself","year":"1936","kind":"estudio","note":"Formula la «revolución neolítica» y la hipótesis del oasis. Referencia histórica del debate."},{"author":"Richard B. Lee e Irven DeVore (eds.)","title":"Man the Hunter","year":"1968","kind":"estudio","note":"Simposio que reformuló la imagen de las sociedades cazadoras-recolectoras."},{"author":"Colin Renfrew","title":"Before Civilization: The Radiocarbon Revolution and Prehistoric Europe","year":"1973","kind":"estudio","note":"Demuestra la anterioridad del megalitismo atlántico y liquida el difusionismo clásico."},{"author":"Jacques Cauvin","title":"Naissance des divinités, naissance de l''agriculture","year":"1994","kind":"estudio","note":"Defiende la primacía del cambio simbólico sobre el económico."},{"author":"David Lewis-Williams","title":"The Mind in the Cave","year":"2002","kind":"estudio","note":"Interpretación neuropsicológica y chamánica del arte paleolítico."},{"author":"Richard Wrangham","title":"Catching Fire: How Cooking Made Us Human","year":"2009","kind":"estudio","note":"La cocción como motor de la encefalización."},{"author":"Svante Pääbo","title":"Neanderthal Man: In Search of Lost Genomes","year":"2014","kind":"estudio","note":"Relato de primera mano de la secuenciación del genoma neandertal."},{"author":"David Reich","title":"Who We Are and How We Got Here","year":"2018","kind":"estudio","note":"Síntesis del impacto del ADN antiguo sobre la historia de las migraciones."},{"author":"James C. Scott","title":"Against the Grain: A Deep History of the Earliest States","year":"2017","kind":"estudio","note":"Cuestiona el relato progresista de la neolitización y del Estado temprano."},{"author":"Klaus Schmidt","title":"Sie bauten die ersten Tempel","year":"2006","kind":"estudio","note":"Excavación e interpretación de Göbekli Tepe por su director."}]},{"type":"images","items":[{"src":"/img/prehistoria/portada.jpg","alt":"Pintura rupestre de Lascaux con caballos y bóvidos trazados en ocre y negro sobre la roca","width":1200,"height":787,"role":"portada","caption":"Las pinturas de Lascaux, en la Dordoña, tienen unos 17.000 años.","author":"EU","title":"Lascaux painting","year":"2006","source":"Wikimedia Commons","license":"Public domain","url":"https://commons.wikimedia.org/wiki/File:Lascaux_painting.jpg"}]}]'::jsonb, 0, true
from public.topics where slug = 'prehistoria'
on conflict (topic_id, position) do update set
  title = excluded.title, body = excluded.body, published = excluded.published;

-- Lección: reforma
insert into public.lessons (topic_id, title, body, position, published)
select id, 'Reforma, Contrarreforma y guerras de religión', '[{"type":"section","title":"Qué pedía Lutero y qué no","text":"El detonante fue una operación financiera. Alberto de Brandeburgo quería acumular el arzobispado de Maguncia con otras sedes, lo que exigía una dispensa cara; se endeudó con la banca Fugger y obtuvo del papa el derecho a predicar en sus territorios una indulgencia para la basílica de San Pedro, con la mitad de lo recaudado destinada a saldar su deuda. El dominico Johann Tetzel la predicó con métodos comerciales agresivos. Lutero, profesor de teología en Wittenberg, reaccionó contra esa predicación.\n\nEl 31 de octubre de 1517 envió las noventa y cinco tesis al propio Alberto en una carta que se conserva. La escena de las tesis clavadas en la puerta de la iglesia del castillo no aparece en ningún texto de Lutero: la cuenta Melanchthon en 1546, después de su muerte. Puede haber ocurrido —era la forma habitual de convocar una disputa universitaria— pero no está documentada, y el gesto fundacional de la Reforma es, con toda probabilidad, un recuerdo posterior.\n\nEl contenido inicial es moderado. Las tesis no niegan el purgatorio ni la autoridad papal: sostienen que la indulgencia no puede sustituir al arrepentimiento interior y que vender la remisión de penas engaña a los fieles. Lutero pedía una discusión académica, y en su carta al arzobispo daba por supuesto que este ignoraba los abusos de sus predicadores.\n\nLa radicalización llegó por el propio proceso. En la disputa de Leipzig de 1519, presionado por Johann Eck, Lutero admitió que también los concilios podían errar, lo que dejaba a la Escritura como única autoridad final. En 1520 publicó tres tratados que sí eran revolucionarios: *A la nobleza cristiana de la nación alemana* apelaba a los príncipes para reformar la Iglesia y negaba la distinción entre estado clerical y laico; *La cautividad babilónica* reducía los sacramentos y negaba la transustanciación; *La libertad del cristiano* formulaba la justificación por la fe. Ese mismo año llegó la bula *Exsurge Domine*, y en 1521, la excomunión y la comparecencia ante Carlos V en la dieta de Worms.\n\nLas tres fórmulas que resumen su teología —solo la fe, solo la Escritura, solo la gracia— tienen consecuencias institucionales inmediatas. Si la salvación no depende de las obras ni de la mediación sacramental, sobra buena parte del aparato eclesiástico; si la Escritura es la única autoridad, hace falta que la gente pueda leerla, y de ahí la traducción alemana que Lutero emprendió refugiado en Wartburgo y que fijó de paso la lengua literaria alemana.","callout":"La escena de las tesis clavadas en la puerta la relata Melanchthon en 1546, después de la muerte de Lutero. Lo documentado es la carta al arzobispo de Maguncia. El gesto fundacional de la Reforma es probablemente un recuerdo posterior."},{"type":"section","title":"Por qué prendió: imprenta, príncipes y agravios","text":"Wyclif y Hus habían sostenido tesis comparables un siglo antes, y el segundo terminó en la hoguera. La diferencia decisiva es de comunicación. Lutero escribió en alemán, breve y polémico, en opúsculos de pocas hojas y precio bajo, ilustrados con grabados para quien no sabía leer. Andrew Pettegree ha calculado que cerca de un tercio de todos los libros impresos en alemán entre 1518 y 1525 salieron de su pluma: es el primer autor superventas de la historia europea y el primer movimiento político que se organiza mediante un mercado editorial.\n\nLa segunda condición fue política. El Imperio no era una monarquía centralizada sino un mosaico de príncipes, ciudades libres y obispados con intereses propios. Federico el Sabio de Sajonia protegió a Lutero sin compartir del todo sus tesis, porque un profesor famoso daba prestigio a su universidad y porque las apelaciones a Roma erosionaban su jurisdicción. Muchos príncipes tenían agravios acumulados contra la fiscalidad pontificia, y la Reforma ofrecía además un incentivo material inmediato: secularizar los bienes eclesiásticos de sus territorios. Carlos V, que sí quería reprimirla, estuvo ocupado durante décadas con Francia, con el Mediterráneo otomano y con el avance turco sobre Hungría y Viena.\n\nLa tercera fue urbana. Bernd Moeller mostró que la Reforma triunfó primero en las ciudades libres del Imperio, donde encajaba con una tradición de autogobierno comunal: la elección del predicador por la comunidad, la administración local de la caridad y el control ciudadano sobre el clero eran demandas anteriores a Lutero que su teología legitimaba. Peter Blickle amplió el argumento al campo y habló de una «reforma comunal», protagonizada por comunidades campesinas y urbanas que leyeron el evangelio como fundamento de sus derechos.\n\nConviene por eso desconfiar del relato del monje solitario. La Reforma prendió porque conectó una crítica teológica con agravios fiscales, con ambiciones territoriales, con una tradición de autogobierno local y con una tecnología de difusión que ninguno de sus predecesores había tenido.","callout":null},{"type":"section","title":"1525: el límite social de la Reforma","text":"La reforma comunal se puso a prueba en 1524-1525. Decenas de miles de campesinos del sur y el centro de Alemania se levantaron contra las cargas señoriales, y su programa más difundido, los Doce Artículos de Memmingen, argumentaba con citas bíblicas: reclamaba elegir al párroco, suprimir el diezmo menor, abolir la servidumbre porque Cristo redimió a todos por igual, y recuperar el uso de bosques y aguas comunales. Fue uno de los primeros textos europeos que formula derechos colectivos y se imprimió en unas veinticinco ediciones en dos meses.\n\nLutero respondió primero con una exhortación a la paz que repartía culpas y después, cuando la revuelta se extendió, con un panfleto de una violencia extrema, *Contra las hordas asesinas y ladronas de campesinos*, en el que llamaba a los príncipes a matar sin misericordia. La represión causó entre setenta mil y cien mil muertos.\n\nLas consecuencias fueron decisivas y de largo alcance. La Reforma dejó de ser un movimiento comunal y pasó a ser un asunto de príncipes y magistrados: la llamada reforma magisterial, en la que la autoridad civil organiza la iglesia territorial, nombra a los pastores y disciplina a los fieles. El campesinado alemán quedó desmovilizado durante siglos. Y quienes mantuvieron la lectura radical del evangelio —bautismo solo de adultos, comunidad de bienes, separación de la iglesia respecto del Estado, a menudo negativa a jurar y a portar armas— quedaron fuera de la ley para católicos y protestantes por igual.\n\nEsos radicales, agrupados bajo la etiqueta genérica de anabaptistas, se dieron en 1527 una confesión propia en Schleitheim que optaba por la separación pacífica del mundo. El episodio que marcó su imagen fue el opuesto: en 1534-1535 un grupo milenarista tomó Münster, proclamó la nueva Jerusalén, impuso la comunidad de bienes y la poligamia y resistió un asedio hasta ser aniquilado. Münster sirvió durante siglos como argumento para justificar la persecución de todo el movimiento, incluidas sus ramas pacifistas, de las que descienden menonitas, huteritas y amish.","callout":"Los Doce Artículos de Memmingen piden abolir la servidumbre porque Cristo redimió a todos por igual. La Reforma dio a los campesinos un lenguaje para formular derechos; Lutero se alineó con quienes los aplastaron."},{"type":"section","title":"Las otras reformas","text":"El protestantismo se fragmentó desde el principio, y no por accidente: si la Escritura es la única autoridad, no hay instancia que zanje las lecturas divergentes. En Zúrich, Ulrico Zuinglio impulsó desde 1519 una reforma más radical en materia de imágenes y de culto, sostenida por el consejo municipal. El coloquio de Marburgo de 1529 reunió a Lutero y a Zuinglio para unificar posiciones ante la amenaza imperial: acordaron catorce de los quince artículos y se rompieron en el decimoquinto, la presencia real de Cristo en la eucaristía. La Reforma nació incapaz de unificarse.\n\nJuan Calvino dio al movimiento su forma más exportable. La *Institución de la religión cristiana*, publicada en 1536 y ampliada hasta 1559, ofrecía un sistema teológico completo y ordenado, con la predestinación como consecuencia lógica de la soberanía absoluta de Dios: la salvación no depende en absoluto del mérito humano. En Ginebra organizó desde 1541 una iglesia con pastores, doctores, ancianos y diáconos y un consistorio que vigilaba la conducta de los ciudadanos. La ejecución de Miguel Servet en 1553 por negar la Trinidad mostró que la tolerancia no formaba parte del programa de ninguno de los bandos.\n\nEl calvinismo se difundió por Francia, Escocia, los Países Bajos, partes de Alemania y Hungría, y con él una estructura eclesiástica de sínodos y consistorios que podía funcionar sin apoyo del príncipe e incluso contra él. Esa autonomía organizativa explica su papel en las guerras civiles francesas y en la revuelta neerlandesa.\n\nInglaterra siguió un camino distinto. La ruptura de Enrique VIII en 1534 fue dinástica y jurisdiccional antes que teológica: el Acta de Supremacía lo hizo cabeza de la Iglesia de Inglaterra para resolver su sucesión, y la disolución de los monasterios entre 1536 y 1541 transfirió a la corona y a la nobleza un patrimonio inmenso, creando un grupo social con interés material en que la ruptura no se revirtiera. El contenido doctrinal llegó después, con Eduardo VI, se revirtió con María I y se estabilizó en 1559 en una fórmula deliberadamente ambigua que dejó dentro a sensibilidades muy distintas y fuera a católicos y a puritanos.","callout":null},{"type":"section","title":"¿Contrarreforma o Reforma católica?","text":"El término «Contrarreforma» lo acuñó la historiografía protestante del siglo XIX y describe la respuesta católica como pura reacción. Hubert Jedin propuso en 1946 distinguir dos procesos: una reforma católica de impulso interno, con raíces anteriores a 1517 —la observancia en las órdenes religiosas, el humanismo cristiano, la reforma española de Cisneros, los oratorios italianos—, y una contrarreforma propiamente dicha, de combate contra el protestantismo. La distinción se ha impuesto, con la advertencia de que ambos procesos se entrelazan tanto que separarlos es un ejercicio analítico y no cronológico.\n\nEl Concilio de Trento, reunido en tres periodos entre 1545 y 1563, hizo dos cosas. En doctrina cerró toda posibilidad de acuerdo: reafirmó la justificación por fe y obras, los siete sacramentos, la transustanciación, el purgatorio, el culto a los santos, la tradición junto a la Escritura como fuente de revelación y la Vulgata como texto oficial. En disciplina fue mucho más innovador de lo que suele recordarse: obligó a los obispos a residir en sus diócesis, creó los seminarios para formar al clero, impuso el registro sistemático de bautismos y matrimonios y reguló la predicación y la catequesis.\n\nEse aparato disciplinar necesitaba instrumentos. La Inquisición romana se reorganizó en 1542, el primer Índice de libros prohibidos se publicó en 1559 y la censura previa se generalizó en los territorios católicos. La Compañía de Jesús, aprobada en 1540, aportó una orden móvil, sin coro ni hábito propio, con cuarto voto de obediencia al papa, especializada en educación y en misión: sus colegios formaron a las élites católicas europeas durante dos siglos, y sus misioneros llegaron a la India, Japón, China y América.\n\nLa cultura fue también instrumento. El decreto tridentino sobre las imágenes de 1563 reafirmó su valor didáctico frente al iconoclasmo protestante y exigió decoro y claridad; de ahí arranca buena parte de la estética barroca, concebida para conmover y persuadir a un público amplio. Es un uso deliberadamente propagandístico del arte, y funciona.\n\nJunto a la disciplina hubo renovación espiritual genuina: Teresa de Ávila y Juan de la Cruz, los capuchinos, las ursulinas dedicadas a la educación de niñas, la extensión de la confesión individual y de la dirección espiritual. Reducir todo el catolicismo del periodo a represión es tan parcial como reducir la Reforma a Lutero.","callout":null},{"type":"section","title":"Guerras, paces y confesionalización","text":"La primera solución fue territorial. La paz de Augsburgo de 1555 estableció que cada príncipe del Imperio fijaba la confesión de su territorio y que los súbditos disconformes podían emigrar; el principio se resumiría después en la fórmula *cuius regio, eius religio*. Reconocía solo el catolicismo y la confesión luterana de Augsburgo, dejando fuera al calvinismo, que crecía. Fue una tregua con fecha de caducidad incorporada.\n\nFrancia se desangró en ocho guerras civiles entre 1562 y 1598, con la matanza de San Bartolomé de 1572 —varios miles de hugonotes asesinados en París y en provincias— como episodio más conocido. El conflicto terminó cuando Enrique de Navarra se convirtió al catolicismo para acceder al trono y promulgó en 1598 el Edicto de Nantes, que concedía a los protestantes libertad de conciencia, culto restringido y plazas de seguridad. Fue tolerancia por agotamiento, no por principio, y sería revocada en 1685.\n\nEn los Países Bajos, la revuelta contra Felipe II combinó desde 1568 defensa de privilegios locales, fiscalidad y calvinismo, y terminó ochenta años después con la independencia de las siete provincias del norte. Y la guerra de los Treinta Años, iniciada en 1618 en Bohemia como conflicto confesional, acabó siendo una guerra europea de hegemonía en la que la Francia católica financió y después combatió junto a los príncipes protestantes contra los Habsburgo. El coste demográfico en el Imperio fue devastador: se estima una pérdida en torno al veinte por ciento de la población total, con regiones enteras por encima del cincuenta por ciento.\n\nLa paz de Westfalia de 1648 añadió el calvinismo a las confesiones reconocidas, fijó 1624 como año normativo para las posesiones eclesiásticas y consagró la práctica de resolver los conflictos europeos en congresos multilaterales. Conviene, eso sí, desconfiar del relato que la presenta como acta de nacimiento de la soberanía estatal moderna: Andreas Osiander mostró en 2001 que esa lectura es una construcción del siglo XIX proyectada hacia atrás, y que los tratados no contienen nada parecido a una doctrina general de soberanía ni de no injerencia.\n\nEl efecto de fondo lo describe la tesis de la confesionalización, formulada por Wolfgang Reinhard y Heinz Schilling: la construcción de identidades confesionales nítidas y la construcción del Estado moderno fueron el mismo proceso. Catequesis obligatoria, escuelas, registros parroquiales, visitas de inspección, control de la moral y del matrimonio, expulsión de los disidentes: católicos, luteranos y calvinistas hicieron lo mismo con instrumentos casi idénticos, y en todos los casos el resultado fue una población más alfabetizada, más vigilada y más encuadrada.\n\nDe ahí arranca la discusión económica más famosa del periodo. Max Weber propuso en 1904-1905 que la ética del calvinismo —vocación profesional, ascetismo intramundano, inquietud ante la incertidumbre de la salvación— favoreció la acumulación capitalista. La objeción moderna más eficaz es de Sascha Becker y Ludger Woessmann, que en 2009 midieron con datos de la Prusia del siglo XIX la distancia de cada comarca a Wittenberg y concluyeron que la ventaja económica protestante se explica por la alfabetización derivada de la obligación de leer la Biblia, no por una ética específica. La conexión entre religión y economía se mantiene; el mecanismo propuesto cambia.","callout":"Westfalia no inventó la soberanía estatal. Esa lectura es una retroproyección del siglo XIX: los tratados no contienen doctrina alguna de soberanía ni de no injerencia."},{"type":"concepts","items":[{"term":"Indulgencia","definition":"Remisión de la pena temporal por el pecado. Su predicación comercial en 1517 fue el detonante de la protesta de Lutero."},{"term":"Sola scriptura","definition":"Principio según el cual la Escritura es la única autoridad final en materia de fe. Al no haber árbitro, hace inevitable la fragmentación."},{"term":"Justificación por la fe","definition":"La salvación se recibe por gracia mediante la fe, no por las obras. Priva de fundamento a buena parte de la mediación sacramental."},{"term":"Flugschrift","definition":"Opúsculo impreso, breve y barato, a menudo ilustrado. Instrumento de difusión que convirtió a Lutero en el primer autor superventas."},{"term":"Reforma comunal","definition":"Lectura de Blickle: la Reforma como movimiento de comunidades urbanas y campesinas que reclaman autogobierno, derrotado en 1525."},{"term":"Reforma magisterial","definition":"Modelo posterior a 1525 en el que la autoridad civil organiza la iglesia territorial, nombra pastores y disciplina a los fieles."},{"term":"Anabaptismo","definition":"Corriente radical partidaria del bautismo de adultos y de la separación entre iglesia y Estado. Perseguida por católicos y protestantes."},{"term":"Predestinación","definition":"Doctrina calvinista: la salvación depende únicamente del decreto divino, no del mérito humano. Consecuencia de la soberanía absoluta de Dios."},{"term":"Consistorio","definition":"Órgano ginebrino de pastores y ancianos encargado de vigilar la conducta de los ciudadanos. Modelo de disciplina eclesiástica calvinista."},{"term":"Acta de Supremacía","definition":"Ley de 1534 que hace al rey de Inglaterra cabeza de su iglesia. Ruptura jurisdiccional y dinástica antes que teológica."},{"term":"Concilio de Trento","definition":"Asamblea de 1545-1563. Cierra la doctrina frente al protestantismo y crea seminarios, residencia episcopal y registros parroquiales."},{"term":"Cuius regio, eius religio","definition":"Principio de Augsburgo (1555): el príncipe fija la confesión de su territorio. Dejaba fuera al calvinismo, que seguía creciendo."},{"term":"Confesionalización","definition":"Tesis de Reinhard y Schilling: construir identidad confesional y construir Estado moderno fueron un mismo proceso disciplinar."},{"term":"Año normativo","definition":"Fecha de referencia fijada en Westfalia —1624— para determinar la titularidad de los bienes eclesiásticos en el Imperio."}]},{"type":"debates","items":[{"question":"¿Contrarreforma o Reforma católica?","positions":[{"school":"Contrarreforma (historiografía protestante del siglo XIX)","argument":"La respuesta católica fue esencialmente reacción: Trento, Inquisición romana, Índice y Compañía de Jesús se explican como maquinaria de combate contra el protestantismo."},{"school":"Dos procesos (Hubert Jedin, 1946)","argument":"Existía una reforma católica de impulso interno anterior a 1517 —observancia religiosa, humanismo cristiano, reforma española, oratorios italianos— sobre la que después se superpuso la reacción antiprotestante."}],"state":"La distinción de Jedin es hoy la norma, con la advertencia de que los dos procesos se entrelazan tanto que separarlos es un recurso analítico y no una secuencia cronológica limpia."},{"question":"¿Fue la Reforma un movimiento de príncipes o de comunidades?","positions":[{"school":"Reforma comunal (Moeller, Blickle)","argument":"Triunfó primero en ciudades libres y comunidades rurales con tradición de autogobierno, que reclamaban elegir a su predicador y administrar la caridad. Los Doce Artículos de 1525 son su programa."},{"school":"Reforma de príncipes","argument":"Sin la protección de Federico el Sabio y sin el interés de los príncipes en secularizar bienes eclesiásticos y recortar la jurisdicción romana, el movimiento habría terminado como el de Hus."}],"state":"Se acepta que ambas dimensiones existieron y que 1525 fue la bisagra: aplastada la revuelta campesina, la Reforma quedó en manos de príncipes y magistrados y la vía comunal desapareció como opción."},{"question":"¿Explica la ética protestante la ventaja económica del norte de Europa?","positions":[{"school":"Ética protestante (Max Weber, 1904-1905)","argument":"La vocación profesional, el ascetismo intramundano y la inquietud ante la incertidumbre de la salvación generaron una disposición al ahorro, al trabajo metódico y a la reinversión que favoreció la acumulación capitalista."},{"school":"Capital humano (Becker y Woessmann, 2009)","argument":"Midiendo la distancia de cada comarca prusiana a Wittenberg, la ventaja económica protestante desaparece al controlar por alfabetización: lo decisivo fue la obligación de leer la Biblia, no una ética específica."}],"state":"La correlación entre confesión y desarrollo se mantiene; el mecanismo propuesto por Weber está muy discutido. Hoy se explica sobre todo por educación y capital humano, y se subraya que la tesis original describía afinidades, no causalidad simple."}]},{"type":"timeline","items":[{"date":"1517","event":"Lutero envía sus 95 tesis al arzobispo de Maguncia."},{"date":"1520–1521","event":"Excomunión y Dieta de Worms: «no puedo ni quiero retractarme»."},{"date":"1522–1534","event":"Traducción de la Biblia al alemán, del Nuevo Testamento a la obra completa."},{"date":"1524–1525","event":"Guerra de los campesinos: Doce Artículos de Memmingen y represión con decenas de miles de muertos."},{"date":"1529","event":"Coloquio de Marburgo: Lutero y Zuinglio no logran acordar la eucaristía."},{"date":"1534","event":"Acta de Supremacía en Inglaterra; reino anabaptista de Münster."},{"date":"1536–1541","event":"Calvino publica la *Institución* y organiza Ginebra."},{"date":"1540","event":"Aprobación de la Compañía de Jesús."},{"date":"1545–1563","event":"Concilio de Trento en tres periodos."},{"date":"1555","event":"Paz de Augsburgo: cada príncipe fija la confesión de su territorio."},{"date":"1562–1598","event":"Guerras de religión en Francia; matanza de San Bartolomé en 1572."},{"date":"1568–1648","event":"Revuelta de los Países Bajos contra la monarquía hispánica."},{"date":"1598","event":"Edicto de Nantes: tolerancia limitada para los hugonotes."},{"date":"1618–1648","event":"Guerra de los Treinta Años."},{"date":"1648","event":"Paz de Westfalia: se reconoce también el calvinismo."}]},{"type":"sources","items":[{"author":"Martín Lutero","title":"Noventa y cinco tesis y carta a Alberto de Maguncia","year":"1517","kind":"primaria","note":"La carta está documentada; el clavado en la puerta lo relata Melanchthon en 1546."},{"author":"Martín Lutero","title":"A la nobleza cristiana de la nación alemana","year":"1520","kind":"primaria","note":"Apela a los príncipes para reformar la Iglesia y niega la distinción entre clérigos y laicos."},{"author":"Comunidades campesinas de Suabia","title":"Doce Artículos de Memmingen","year":"1525","kind":"primaria","note":"Programa de derechos colectivos fundado en citas bíblicas. Veinticinco ediciones en dos meses."},{"author":"Martín Lutero","title":"Contra las hordas asesinas y ladronas de campesinos","year":"1525","kind":"primaria","note":"Llama a los príncipes a reprimir sin misericordia. Documento clave del giro magisterial."},{"author":"Hermandad de Schleitheim","title":"Confesión de Schleitheim","year":"1527","kind":"primaria","note":"Programa anabaptista de separación pacífica del mundo, anterior al episodio de Münster."},{"author":"Felipe Melanchthon","title":"Confesión de Augsburgo","year":"1530","kind":"primaria","note":"Exposición oficial de la doctrina luterana presentada ante Carlos V."},{"author":"Parlamento inglés","title":"Acta de Supremacía","year":"1534","kind":"primaria","note":"Convierte al rey en cabeza de la Iglesia de Inglaterra por razones sucesorias y jurisdiccionales."},{"author":"Juan Calvino","title":"Institución de la religión cristiana","year":"1536-1559","kind":"primaria","note":"Sistema teológico completo y exportable. Base organizativa del calvinismo internacional."},{"author":"Concilio de Trento","title":"Decretos y cánones","year":"1545-1563","kind":"primaria","note":"Doctrina cerrada frente al protestantismo y reforma disciplinar del clero y de la parroquia."},{"author":"Enrique IV de Francia","title":"Edicto de Nantes","year":"1598","kind":"primaria","note":"Tolerancia limitada por agotamiento tras ocho guerras civiles. Revocado en 1685."},{"author":"Plenipotenciarios europeos","title":"Tratados de Osnabrück y Münster","year":"1648","kind":"primaria","note":"Reconocen el calvinismo y fijan 1624 como año normativo. No contienen doctrina de soberanía."},{"author":"Max Weber","title":"La ética protestante y el espíritu del capitalismo","year":"1904-1905","kind":"estudio","note":"Propone una afinidad entre ascetismo calvinista y acumulación capitalista."},{"author":"Hubert Jedin","title":"Katholische Reformation oder Gegenreformation?","year":"1946","kind":"estudio","note":"Distingue reforma católica interna y contrarreforma antiprotestante."},{"author":"Peter Blickle","title":"La revolución del hombre común","year":"1975","kind":"estudio","note":"La reforma comunal y la guerra campesina de 1525 como movimiento con programa propio."},{"author":"Diarmaid MacCulloch","title":"Reformation: Europe s House Divided","year":"2003","kind":"estudio","note":"Síntesis general del periodo, atenta a las periferias y a la Reforma radical."},{"author":"Andreas Osiander","title":"Sovereignty, International Relations and the Westphalian Myth","year":"2001","kind":"estudio","note":"Desmonta la lectura de 1648 como acta de nacimiento de la soberanía estatal."},{"author":"Sascha Becker y Ludger Woessmann","title":"Was Weber Wrong?","year":"2009","kind":"estudio","note":"Atribuye la ventaja económica protestante a la alfabetización y no a la ética."},{"author":"Andrew Pettegree","title":"Brand Luther","year":"2015","kind":"estudio","note":"La Reforma como fenómeno editorial y Wittenberg como centro de impresión."}]},{"type":"images","items":[{"src":"/img/reforma/portada.jpg","alt":"Retrato de medio cuerpo de Martín Lutero con hábito oscuro sobre fondo azul","width":1200,"height":1286,"role":"portada","caption":"Martín Lutero retratado por Lucas Cranach el Viejo en 1529.","author":"Lucas Cranach the Elder","title":"Martin Luther","year":"1529","source":"Wikimedia Commons","license":"Public domain","url":"https://commons.wikimedia.org/wiki/File:Martin_Luther%2C_1529.jpg"},{"src":"/img/reforma/tesis.jpg","alt":"Impreso antiguo a dos columnas en latín con las noventa y cinco tesis numeradas","width":1200,"height":675,"role":"figura","section":0,"caption":"Impresión temprana de las noventa y cinco tesis. La difusión por imprenta es lo que convirtió una disputa académica en un conflicto europeo.","author":"Ferdinand Pauwels","title":"Luther95theses","year":"1872","source":"Wikimedia Commons","license":"Public domain","url":"https://commons.wikimedia.org/wiki/File:Luther95theses.jpg"}]}]'::jsonb, 0, true
from public.topics where slug = 'reforma'
on conflict (topic_id, position) do update set
  title = excluded.title, body = excluded.body, published = excluded.published;

-- Lección: renacimiento
insert into public.lessons (topic_id, title, body, position, published)
select id, 'Renacimiento y Humanismo', '[{"type":"section","title":"«Renacimiento»: historia de una palabra","text":"El concepto no lo inventaron los historiadores: lo inventaron los interesados. Giorgio Vasari publicó en 1550, y ampliado en 1568, las *Vidas de los más excelentes arquitectos, pintores y escultores*, donde organizó tres siglos de arte italiano como una *rinascita*: un declive tras la Antigüedad, un despertar con Cimabue y Giotto, una madurez con Masaccio y Donatello y una perfección con Miguel Ángel. Vasari escribía desde Florencia, sobre artistas casi todos toscanos y con Miguel Ángel vivo como punto de llegada. La periodización que aún manejamos nació como propaganda cultural de una ciudad y de un gremio.\n\nLa palabra se convirtió en periodo histórico general en el siglo XIX. Jules Michelet tituló «La Renaissance» un volumen de su historia de Francia en 1855, y cinco años después Jacob Burckhardt publicó *La cultura del Renacimiento en Italia* (1860), el libro que fijó la imagen todavía dominante: el Estado italiano como obra de arte calculada, el descubrimiento del mundo y del hombre, el nacimiento del individuo frente a la conciencia corporativa medieval y una atmósfera paganizante y secular. Burckhardt no trabajaba con archivos, sino con textos literarios; construyó un retrato de época extraordinariamente influyente y muy poco verificable.\n\nLa réplica llegó desde el medievalismo. Charles Homer Haskins tituló provocadoramente *The Renaissance of the Twelfth Century* (1927) para demostrar que las universidades, la recuperación del derecho romano, la entrada de Aristóteles a través del árabe, la poesía latina y una nueva ciencia natural son fenómenos del siglo XII, no del XV. Antes ya se hablaba del renacimiento carolingio y del otoniano. Si «renacimiento» significa recuperación deliberada de la Antigüedad, la Edad Media tuvo varios.\n\nJohan Huizinga había atacado el mismo relato desde otro ángulo en *El otoño de la Edad Media* (1919). Estudiando los mismos siglos XIV y XV en Borgoña y Francia, encontró una cultura sobremadura, obsesionada con la muerte, el ceremonial y el simbolismo caballeresco: un final, no un comienzo. Los mismos años leídos desde Flandes o desde Florencia producen dos épocas distintas, lo que dice más del observador que del periodo.\n\nLa misma etiqueta «Edad Media» procede del bando humanista. Fueron ellos quienes describieron los siglos intermedios como *tenebrae* y como *media aetas*: un hueco sin valor propio entre la Antigüedad admirada y su propia obra restauradora. Los historiadores heredaron sin discutirla la periodización redactada por una de las partes en litigio.\n\nHoy el término sobrevive como convención cronológica útil, drenado de su contenido de ruptura. Nadie sostiene ya que Europa despertara de mil años de oscuridad, y la mayoría de los especialistas subraya la continuidad de instituciones, técnicas y formas de pensar entre el siglo XIII y el XVI. Lo que sigue discutiéndose es si una categoría acuñada por sus propios protagonistas con fines de autopromoción puede funcionar como herramienta analítica o solo como etiqueta de archivo.","callout":"La expresión «Edad Media» la acuñaron los humanistas para nombrar el hueco entre la Antigüedad y ellos mismos. Seguimos usando la periodización escrita por una de las partes en litigio."},{"type":"section","title":"El humanismo era un método, no una filosofía","text":"El humanismo no fue una doctrina sobre el hombre, sino un programa de estudios y una profesión. Los *studia humanitatis* comprendían cinco disciplinas concretas: gramática, retórica, poesía, historia y filosofía moral, todas basadas en la lectura directa de los autores griegos y latinos. Quedaban fuera la lógica, la filosofía natural, la metafísica, el derecho, la medicina y la teología, que siguieron enseñándose en las facultades universitarias sin apenas alteración.\n\nPaul Oskar Kristeller fue quien impuso esta definición sobria. Los humanistas, sostuvo, eran profesionales de esas disciplinas —maestros de gramática, secretarios de cancillería, cronistas de corte, editores— y no miembros de una escuela filosófica: los hubo platónicos, aristotélicos, escépticos, devotos y libertinos. Buscar una «filosofía humanista» unitaria es un error de categoría. Frente a él, Eugenio Garin defendió que el humanismo sí implicaba una concepción del hombre y de la historia, y Hans Baron formuló la tesis del humanismo cívico.\n\nLa herramienta que sí distingue al humanismo es la filología. El principio *ad fontes* —ir a las fuentes— exigía leer el texto en su lengua original, en la versión manuscrita más antigua disponible y depurado de los errores acumulados por siglos de copia. Petrarca es el caso fundacional: escribía cartas a Cicerón y a Livio como si estuvieran vivos, buscaba códices en bibliotecas catedralicias y, cuando encontró en Verona en 1345 las cartas privadas de Cicerón, descubrió a un político ambicioso e inseguro que arruinó la imagen que él mismo había construido. El método puede volverse contra quien lo aplica.\n\nLa demostración decisiva de su potencia la dio Lorenzo Valla en 1440. La Donación de Constantino era el documento con el que el papado justificaba su soberanía temporal sobre Roma y Occidente: en él, Constantino cedía el poder al papa Silvestre. Valla probó que era una falsificación posterior analizando su lengua. El texto usa vocabulario inexistente en el siglo IV, emplea términos como *satrapa* que no pertenecen a la administración romana, comete errores sobre instituciones de la época y escribe un latín tardío imposible en la cancillería constantiniana. Nació así la crítica textual moderna: un documento puede fecharse por cómo está escrito, con independencia de lo que afirme.\n\nLa filología tuvo consecuencias políticas inmediatas. En 1516 Erasmo publicó el *Novum Instrumentum*, primera edición impresa del Nuevo Testamento griego acompañada de una traducción latina nueva que corregía la Vulgata. Donde la Vulgata decía *poenitentiam agite* —«haced penitencia»—, el griego decía *metanoeite*, «cambiad de mentalidad», «arrepentíos». La base textual del sacramento de la penitencia quedaba en el aire, y Lutero abrió con exactamente ese argumento la primera de sus 95 tesis en 1517. Una corrección de traducción se convirtió en una fractura religiosa.\n\nEn la península ibérica el mismo impulso produjo la *Gramática de la lengua castellana* de Nebrija (1492), primera gramática de una lengua romance, y la Biblia Políglota Complutense (1514-1517), promovida por el cardenal Cisneros, que imprimió en columnas paralelas los textos hebreo, arameo, griego y latino. Ese programa se cerró con rapidez: el Índice de 1559 prohibió la obra completa de Erasmo, y el biblismo humanista quedó bajo sospecha permanente en España e Italia.","callout":"La refutación de Valla acabó incluida en el Índice de libros prohibidos. Su método, en cambio, se volvió imprescindible para la propia Iglesia: sin crítica textual no hay edición fiable de las Escrituras ni de los concilios."},{"type":"section","title":"Ciudades, guerra y mecenazgo: quién pagaba","text":"Italia no era un Estado, y esa fragmentación explica buena parte del fenómeno. Cinco potencias —Venecia, Milán, Florencia, los Estados Pontificios y Nápoles— más una constelación de señoríos menores competían entre sí, y tras la Paz de Lodi (1454) mantuvieron durante cuarenta años un equilibrio inestable basado en la diplomacia permanente y en ejércitos mercenarios mandados por condotieros. Las repúblicas comunales fueron derivando hacia señoríos personales: los Médicis gobernaron Florencia de hecho desde 1434 sin ocupar cargo formal, los Sforza tomaron Milán en 1450, los Montefeltro hicieron de Urbino una corte con el dinero de la guerra.\n\nEl dinero venía de la lana y la seda florentinas, de la banca —el banco Médicis manejaba las cuentas pontificias a través de una red de filiales— y del comercio veneciano con Levante, Egipto y el Imperio otomano. El otro gran pagador era el papado, que en el siglo XVI financió la nueva basílica de San Pedro y sus decoraciones con recursos ordinarios y con indulgencias predicadas por toda Europa. La cumbre artística del Renacimiento romano y el detonante de la Reforma comparten fuente de financiación.\n\nPor qué ese dinero fue a parar al arte es objeto de un debate económico clásico. Robert Lopez propuso la tesis de las «hard times»: tras la peste negra la riqueza por habitante subió, pero la rentabilidad de la inversión productiva cayó, y el capital se desplazó hacia el lujo, el prestigio y el consumo suntuario. El Renacimiento sería, en esa lectura, un síntoma de estancamiento económico. Richard Goldthwaite lo rebatió documentando lo contrario: una expansión real y sostenida de la demanda de bienes, una industria de la construcción enorme y una cultura del consumo doméstico que llenó las casas urbanas de objetos. La discusión sigue abierta y depende mucho de qué ciudad y qué décadas se midan.\n\nMichael Baxandall cambió la manera de mirar los cuadros en *Pintura y vida cotidiana en el Renacimiento* (1972). Los contratos de encargo conservados especifican el plazo de entrega, la calidad del azul de ultramar y la cantidad de oro, y con frecuencia exigen que determinadas figuras las pinte el maestro en persona y no el taller. Baxandall añadió la noción de «ojo de la época»: el público leía las pinturas con destrezas adquiridas fuera de ellas, la geometría de los mercaderes formados en escuelas de ábaco para calcular volúmenes de barriles, los repertorios de gestos de la predicación y las figuras de la danza. La pintura era una mercancía por encargo dirigida a un público entrenado, no una expresión libre.\n\nEl mecenazgo era además un instrumento político. Las capillas familiares, los retablos donados y las fachadas costeadas anunciaban jerarquía en el espacio público. Julio II movilizó a Bramante, Miguel Ángel y Rafael como programa de afirmación pontificia; Isabel de Este convirtió su *studiolo* de Mantua en un encargo intelectual documentado carta a carta; Ludovico Sforza retuvo a Leonardo en Milán casi veinte años, en buena medida como ingeniero militar y organizador de fiestas.\n\nLisa Jardine, en *Worldly Goods* (1996), y Jerry Brotton han insistido en un punto que el relato burckhardtiano ocultaba: el Renacimiento fue también una cultura de la adquisición, y sus objetos de deseo eran en gran parte orientales. Tapices flamencos, sedas, alfombras otomanas y mamelucas, papel, pigmentos y vidrio circulaban por las mismas rutas que las ideas. Mehmet II, el conquistador de Constantinopla, pidió a Venecia un retratista en 1479 y recibió a Gentile Bellini. La frontera cultural era mucho más porosa de lo que el mito de una Europa que redescubre sus raíces clásicas permite ver.\n\nEl ciclo italiano se cerró por la guerra. La invasión francesa de 1494 abrió cuarenta años de conflicto entre Francia y el Imperio con Italia como campo de batalla, y el saco de Roma de 1527 dispersó a artistas y humanistas. A partir de entonces los centros se multiplicaron: Venecia, Fontainebleau, Amberes, la corte imperial, Toledo. La difusión europea del Renacimiento fue en buena medida consecuencia de una derrota.","callout":"El contrato de la *Virgen de las rocas* (1483) fija plazos, materiales y qué figuras debía pintar Leonardo de su mano. El artista solitario y libre es una construcción romántica del siglo XIX proyectada hacia atrás."},{"type":"section","title":"Perspectiva, anatomía y el nuevo estatuto del artista","text":"Hacia 1413 Brunelleschi realizó en Florencia un experimento óptico con dos tablillas: pintó el Baptisterio en perspectiva, hizo un agujero en el punto de fuga y usó un espejo para que el espectador comparara imagen y edificio real. Alberti convirtió el hallazgo en método escrito en *De pictura* (1435), con la construcción de la pirámide visual y la pintura entendida como ventana. Masaccio ya lo había aplicado en la *Trinidad* de Santa Maria Novella hacia 1427. La perspectiva lineal no es un descubrimiento sobre la naturaleza, sino una convención geométrica: una manera de representar el espacio que resultó culturalmente triunfal, no la única posible.\n\nSu éxito tuvo una base social concreta. Las escuelas de ábaco formaban a los hijos de mercaderes en geometría práctica para medir mercancías y calcular capacidades, y esa alfabetización matemática hizo legible e incluso deseable la nueva pintura. Piero della Francesca escribió tanto un tratado de perspectiva como un manual de aritmética comercial: la misma cabeza para ambas cosas.\n\nLa anatomía siguió un camino paralelo. La disección de cadáveres humanos, autorizada en Bolonia y Padua desde el siglo XIV, se separó lentamente del comentario de Galeno. Leonardo realizó unas treinta disecciones y dejó láminas que no llegaron a publicarse. Quien completó la ruptura fue Andrés Vesalio en *De humani corporis fabrica* (1543): corrigió a Galeno mostrando que había descrito animales y no humanos, y presentó su argumento en forma de imágenes grabadas de altísima calidad. Solo la imprenta permitía que una lámina anatómica fuese idéntica para todos los lectores, y por tanto discutible: la reproducción exacta convirtió al dibujo en prueba.\n\nEl estatuto del artista cambió con ello. En 1400 el pintor era un artesano agremiado que compraba pigmentos y firmaba contratos; en 1560 Miguel Ángel tenía dos biografías publicadas en vida, correspondencia con papas y un funeral de Estado en Florencia. Alberti y Leonardo reivindicaron la pintura como actividad intelectual —el *paragone* discutía su superioridad sobre la escultura y la poesía—, y la fundación de la Accademia del Disegno en 1563, impulsada por Vasari, institucionalizó la separación entre artista y artesano. Fue una promoción de gremio conseguida, en buena parte, escribiendo la propia historia.\n\nTras 1527 la historiografía habló durante mucho tiempo de decadencia manierista: figuras alargadas, espacios inestables, colores ácidos en Pontormo, Rosso Fiorentino o Parmigianino. Walter Friedländer primero y John Shearman después revirtieron el juicio: el manierismo no es un fallo de la norma clásica, sino un arte de la *maniera*, deliberadamente refinado y dirigido a un público de conocedores capaz de apreciar la variación sobre modelos conocidos.\n\nConviene resistir la tentación de convertir todo esto en el arranque de la revolución científica. Copérnico publicó en 1543 un sistema heliocéntrico movido por una insatisfacción estética muy tradicional —quería recuperar el movimiento circular uniforme que Ptolomeo había abandonado— y con una precisión predictiva no superior a la del modelo anterior. La filosofía natural renacentista incluía además astrología, alquimia y magia natural sin percibir contradicción: Ficino escribió sobre talismanes planetarios, Pico integró la cábala en la apologética cristiana, Paracelso mezcló química y ocultismo. Frances Yates llegó a sostener que la tradición hermética fue el motor de la nueva ciencia; la tesis se considera exagerada, pero sirvió para desmontar la imagen de un Renacimiento racionalista avant la lettre.","callout":null},{"type":"section","title":"La imprenta: qué cambió y qué no","text":"Los tipos móviles no se inventaron en Europa. China los usaba desde el siglo XI con Bi Sheng y Corea imprimió con tipos metálicos el *Jikji* en 1377. La aportación específica de Gutenberg hacia 1450 fue un sistema industrial completo: un procedimiento de punzón y matriz para fundir en serie tipos metálicos idénticos y reutilizables, una aleación adecuada, una tinta grasa que se adhería al metal y una prensa adaptada del sector vinícola. Funcionó porque el alfabeto latino necesita pocos caracteres, algo que penalizaba a los sistemas de escritura asiáticos.\n\nLa escala del cambio es difícil de exagerar. Antes de 1501 se imprimieron unas 30.000 ediciones distintas —los incunables—, con tiradas medias de varios centenares de ejemplares: entre ocho y veinte millones de libros según las estimaciones, más de lo que todos los copistas europeos habían producido en el milenio anterior. Hacia 1500 funcionaban prensas en unas 250 ciudades, y Venecia era la capital editorial del continente. Allí Aldo Manuzio creó el formato en octavo y el tipo cursivo, es decir, el clásico portátil y barato: un cambio de objeto tan importante como el de tecnología.\n\nElizabeth Eisenstein defendió en *The Printing Press as an Agent of Change* (1979) que la imprenta fue el agente causal de la modernidad intelectual. Su argumento central es la fijeza: un texto impreso es idéntico en miles de copias, puede compararse edición con edición, permite acumular correcciones en lugar de acumular errores de copia y hace posible que los datos, las tablas y las láminas circulen sin degradarse. Sin esa estabilidad, sostuvo, no habría ni ciencia acumulativa ni Reforma.\n\nAdrian Johns replicó en *The Nature of the Book* (1998) que la fijeza no fue un efecto automático de la máquina. El siglo XVI y el XVII están llenos de ediciones piratas, textos mal compuestos, pies de imprenta falsificados y atribuciones fraudulentas; los propios autores se quejaban de no reconocer sus obras. La fiabilidad del libro impreso hubo que construirla socialmente, con gremios, privilegios, censura y reputaciones. El consenso actual sitúa la imprenta como condición necesaria pero no suficiente: sus efectos dependieron de instituciones, mercados y derecho.\n\nLa Reforma fue el primer acontecimiento mediático de masas. Entre 1517 y 1525 circularon miles de ediciones de opúsculos en alemán, muchos de Lutero, breves, baratos e ilustrados con grabados para quien no sabía leer. Pero la imprenta no difundió solo humanismo y crítica. El *Malleus maleficarum*, manual para identificar y perseguir brujas publicado en 1487, tuvo alrededor de treinta ediciones y acompañó la fase más dura de la caza de brujas; los almanaques astrológicos y las profecías fueron géneros de gran venta. La tecnología amplificó lo que ya circulaba, en todas direcciones.\n\nLa reacción llegó pronto. El primer Índice romano de libros prohibidos (1559) incluyó la obra completa de Erasmo y decenas de autores más; se generalizaron la licencia previa, el *imprimatur* y la vigilancia de las aduanas sobre los libros. En España e Italia la censura recortó la circulación de la filología bíblica y del pensamiento político durante generaciones, mientras los centros editoriales se desplazaban a Basilea, Ginebra, Amberes y más tarde Ámsterdam.\n\nHay que evitar además exagerar el alcance social. Las estimaciones de alfabetización dan porcentajes bajos y muy desiguales: minorías urbanas masculinas de entre el diez y el treinta por ciento en las ciudades más avanzadas, cifras mucho menores en el campo y entre las mujeres. La lectura en voz alta en talleres, tabernas y plazas, y el grabado como argumento visual, extendieron el efecto mucho más allá de quienes sabían leer, pero el libro siguió siendo un objeto minoritario.","callout":"La misma tecnología multiplicó la crítica filológica y el *Malleus maleficarum*. La imprenta no racionalizó Europa: amplificó lo que ya circulaba por ella."},{"type":"section","title":"Quién quedó fuera","text":"En 1977 Joan Kelly publicó un artículo con un título que reorganizó el campo: «¿Tuvieron las mujeres un Renacimiento?». Su respuesta fue que no, o no en el mismo sentido. En el paso de la sociedad feudal a los Estados y las cortes del Renacimiento, las mujeres de la nobleza perdieron funciones económicas y políticas que sí habían tenido antes; la dama del *Cortesano* de Castiglione existe para adornar la conversación del hombre; las dotes se dispararon y con ellas la reclusión de las hijas excedentes en conventos; la exigencia de castidad y obediencia se endureció. Una mujer instruida resultaba sospechosa: la elocuencia pública se consideraba incompatible con la virtud femenina.\n\nLa investigación posterior ha matizado la tesis sin desactivarla. Existieron humanistas como Isotta Nogarola, Laura Cereta y Cassandra Fedele, pintoras profesionales como Sofonisba Anguissola y Lavinia Fontana, y mecenas de primer orden como Isabel de Este. La *querella de las mujeres*, abierta en el siglo XV por Christine de Pizan, produjo hacia 1600 obras como *El mérito de las mujeres* de Moderata Fonte y la réplica de Lucrezia Marinella. La conclusión hoy dominante es que la respuesta depende de la clase, la ciudad y la década, pero que la pregunta de Kelly demostró algo más general: una periodización construida sobre la experiencia de una minoría masculina no describe automáticamente a toda la sociedad.\n\nLa Italia del Renacimiento tampoco era una sociedad sin esclavitud. Génova, Venecia y Florencia mantuvieron esclavitud doméstica documentada en contratos notariales, con personas tártaras, circasianas, griegas y balcánicas, y desde el siglo XV también subsaharianas. Esos años coinciden con la apertura del comercio atlántico portugués de esclavos a partir de 1444 y, tras 1492, con la encomienda y el trabajo forzado en América. La *Oración sobre la dignidad del hombre* de Pico y la controversia de Valladolid entre Sepúlveda y Las Casas (1550-1551) sobre la humanidad y los derechos de los indígenas pertenecen al mismo mundo intelectual.\n\nLas minorías religiosas europeas vivieron un endurecimiento simultáneo. Los decretos de 1492 en Castilla y Aragón y de 1497 en Portugal expulsaron o forzaron la conversión de las comunidades judías; en 1516 Venecia encerró a la suya en el barrio de las fundiciones, el *ghetto*, dando nombre a una institución que se extendió por Italia, incluida Roma en 1555. Y a la vez florecía el hebraísmo cristiano: Reuchlin defendió la conservación de los libros hebreos, Pico construyó una cábala cristiana y las prensas italianas imprimieron textos hebreos de referencia. Interés erudito por una cultura y persecución de quienes la encarnaban avanzaron juntos.\n\nConviene recordar además la escala. Entre el ochenta y cinco y el noventa por ciento de la población europea era rural y quedaba fuera de este circuito. La revolución de los precios del siglo XVI erosionó los salarios reales, y las hambrunas y epidemias siguieron marcando la demografía. Peter Burke, en un estudio prosopográfico de unos seiscientos creadores italianos del periodo, encontró un grupo abrumadoramente urbano, masculino, concentrado en el centro-norte de Italia y procedente de familias de artesanos y mercaderes: una élite pequeña y geográficamente muy concentrada.\n\nPor último, el mito de un Renacimiento secular no resiste el recuento. La inmensa mayoría de los encargos artísticos fueron religiosos; Ficino era sacerdote; Pico murió reconciliado con Savonarola, cuya república teocrática florentina de 1494-1498 es tan producto del Renacimiento como la corte de Lorenzo de Médicis; Bruno acabó en la hoguera en 1600 y Galileo sería juzgado en 1633. El individuo moderno y pagano de Burckhardt es en gran medida una proyección del siglo XIX sobre unas fuentes escogidas.\n\nLo que queda, retirado el mito, es sustancial: un método crítico para tratar los textos y los documentos, una tecnología que transformó la escala del saber, un régimen de imágenes basado en la perspectiva y en el grabado reproducible, y una autodescripción cultural —Europa como heredera legítima de la Antigüedad— que el continente seguiría empleando durante siglos para definirse frente a los demás.","callout":null},{"type":"concepts","items":[{"term":"Studia humanitatis","definition":"Programa de cinco disciplinas —gramática, retórica, poesía, historia y filosofía moral— basado en la lectura directa de los autores antiguos."},{"term":"Ad fontes","definition":"Principio de acudir a la fuente original, en su lengua y en el manuscrito más antiguo disponible, en lugar de a comentarios y traducciones."},{"term":"Filología crítica","definition":"Método para depurar y fechar textos por su lengua y sus anacronismos. Su acta de nacimiento es la refutación de la Donación de Constantino."},{"term":"Humanismo cívico","definition":"Tesis de Hans Baron según la cual el humanismo florentino nació como ideología de la libertad republicana frente a la amenaza de Milán."},{"term":"Mecenazgo","definition":"Financiación del arte y las letras por príncipes, papas, gremios y familias. Combinaba devoción, prestigio y afirmación política."},{"term":"Perspectiva lineal","definition":"Convención geométrica que representa el espacio mediante un punto de fuga único. Codificada por Alberti en 1435 tras el experimento de Brunelleschi."},{"term":"Ojo de la época","definition":"Concepto de Baxandall: destrezas visuales adquiridas fuera de la pintura —geometría mercantil, gesto predicatorio, danza— con las que el público leía las imágenes."},{"term":"Neoplatonismo florentino","definition":"Corriente impulsada por Ficino en torno a los Médicis, que tradujo a Platón y el *Corpus hermeticum* y unió filosofía, magia natural y teología."},{"term":"Incunable","definition":"Libro impreso antes de 1501. Se conservan unas 30.000 ediciones distintas."},{"term":"Signoria","definition":"Régimen de poder personal que sustituyó a las repúblicas comunales italianas. Los Médicis lo ejercieron en Florencia sin cargo formal desde 1434."},{"term":"Condotiero","definition":"Jefe mercenario contratado por un Estado italiano. Algunos, como los Montefeltro de Urbino, convirtieron el botín en corte humanista."},{"term":"Manierismo","definition":"Arte posterior a 1527 basado en la variación refinada sobre modelos clásicos. La historiografía dejó de leerlo como decadencia."},{"term":"Querella de las mujeres","definition":"Polémica europea sobre la capacidad y la dignidad femeninas, de Christine de Pizan a Moderata Fonte y Lucrezia Marinella."}]},{"type":"debates","items":[{"question":"¿Existió el Renacimiento como ruptura histórica?","positions":[{"school":"Ruptura (Burckhardt, 1860)","argument":"El siglo XV italiano inaugura la modernidad: el Estado como obra de arte calculada, el descubrimiento del mundo y del hombre, el nacimiento del individuo y una cultura secular frente a la conciencia corporativa medieval."},{"school":"Continuidad medieval (Haskins, 1927; Huizinga, 1919)","argument":"Las universidades, el derecho romano y la recuperación de Aristóteles son del siglo XII, y hubo antes un renacimiento carolingio. Leídos desde Borgoña, los mismos siglos XIV y XV son el otoño sobremaduro de la cultura medieval, no un amanecer."},{"school":"Categoría heredada de los propios protagonistas","argument":"La periodización procede de Vasari y de los humanistas, que acuñaron «Edad Media» para nombrar el hueco entre la Antigüedad y ellos mismos. Es una autodescripción interesada convertida sin filtro en categoría académica."}],"state":"Nadie defiende ya el despertar tras mil años de oscuridad. El término se conserva como convención cronológica, sin contenido de ruptura, y se discute si una etiqueta acuñada como propaganda puede funcionar como herramienta analítica o solo como marca de archivo."},{"question":"¿Qué era el humanismo: un programa de estudios o una filosofía?","positions":[{"school":"Programa profesional (Kristeller)","argument":"Los humanistas eran profesionales de cinco disciplinas concretas —gramática, retórica, poesía, historia y filosofía moral—, no una escuela de pensamiento. Los hubo platónicos, aristotélicos, escépticos y devotos: buscar una filosofía común es un error de categoría."},{"school":"Humanismo cívico (Baron, 1955; Garin)","argument":"El humanismo florentino nació como ideología política en la crisis de 1402 frente a Milán: una defensa de la vida activa, la ciudadanía y la libertad republicana frente al ideal contemplativo anterior."}],"state":"La definición de Kristeller es hoy la operativa. La cronología de los textos ha desmontado buena parte de la reconstrucción de Baron, y se ha señalado que su experiencia como exiliado de la Alemania nazi orientó la lectura. Aun así, la tesis obligó a estudiar el humanismo en su contexto político y no solo como erudición."},{"question":"¿Tuvieron las mujeres un Renacimiento?","positions":[{"school":"No (Joan Kelly, 1977)","argument":"Las mujeres de la nobleza perdieron funciones económicas y políticas que habían tenido en la sociedad feudal. Se endurecieron las normas de castidad y obediencia, se dispararon las dotes y creció la reclusión conventual: el periodo empeoró su posición mientras mejoraba la de los varones de su clase."},{"school":"Revisión documental","argument":"Están documentadas humanistas como Nogarola, Cereta y Fedele, pintoras profesionales como Anguissola y Fontana, mecenas como Isabel de Este y una querella de las mujeres con obras propias hacia 1600. La respuesta varía según clase, ciudad y década."}],"state":"La tesis se acepta con matices de clase y geografía. Su efecto duradero es metodológico: mostró que una periodización construida sobre la experiencia de una minoría masculina no describe por sí sola al conjunto de la sociedad."}]},{"type":"timeline","items":[{"date":"1341","event":"Petrarca es coronado poeta laureado en el Capitolio de Roma."},{"date":"1397","event":"Manuel Crisoloras empieza a enseñar griego en Florencia."},{"date":"1435","event":"Alberti codifica la perspectiva lineal en *De pictura*."},{"date":"1440","event":"Lorenzo Valla demuestra que la Donación de Constantino es una falsificación."},{"date":"c. 1450","event":"Gutenberg imprime con tipos móviles metálicos en Maguncia."},{"date":"1453","event":"Caída de Constantinopla; llegan a Italia eruditos y manuscritos griegos."},{"date":"1462","event":"Ficino traduce a Platón y el *Corpus hermeticum* para Cosme de Médici."},{"date":"1486","event":"Pico della Mirandola escribe la *Oración sobre la dignidad del hombre*."},{"date":"1494","event":"Invasión francesa de Italia: comienzan las guerras italianas."},{"date":"1508–1512","event":"Miguel Ángel pinta la bóveda de la Capilla Sixtina."},{"date":"1516","event":"Erasmo publica el Nuevo Testamento en griego con traducción latina nueva."},{"date":"1527","event":"Saco de Roma por las tropas imperiales."},{"date":"1543","event":"*De revolutionibus* de Copérnico y *De humani corporis fabrica* de Vesalio."},{"date":"1559","event":"Primer Índice romano de libros prohibidos: la obra completa de Erasmo entra en él."},{"date":"1600","event":"Giordano Bruno es quemado en el Campo dei Fiori de Roma."}]},{"type":"sources","items":[{"author":"Petrarca","title":"Cartas familiares","year":"c. 1350","kind":"primaria","note":"Incluye las cartas a autores muertos y el hallazgo en 1345 de la correspondencia privada de Cicerón."},{"author":"Leon Battista Alberti","title":"De pictura","year":"1435","kind":"primaria","note":"Primera formulación escrita de la perspectiva lineal como método."},{"author":"Lorenzo Valla","title":"Sobre la falsamente creída donación de Constantino","year":"1440","kind":"primaria","note":"Demuestra la falsificación por anacronismos de lengua. Acta de nacimiento de la crítica textual."},{"author":"Pico della Mirandola","title":"Oración sobre la dignidad del hombre","year":"1486","kind":"primaria","note":"Texto emblemático del periodo. Su autor era además cabalista cristiano y acabó cercano a Savonarola."},{"author":"Erasmo de Róterdam","title":"Novum Instrumentum","year":"1516","kind":"primaria","note":"Nuevo Testamento griego con traducción latina nueva. Corrige *poenitentiam agite* por *metanoeite*."},{"author":"Nicolás Maquiavelo","title":"El príncipe","year":"1513","kind":"primaria","note":"Escrito tras la caída de la república florentina; publicado en 1532. Analiza el poder por su eficacia, no por su legitimidad."},{"author":"Baltasar de Castiglione","title":"El cortesano","year":"1528","kind":"primaria","note":"Modelo europeo de conducta cortesana. Fuente central para el argumento de Joan Kelly."},{"author":"Andrés Vesalio","title":"De humani corporis fabrica","year":"1543","kind":"primaria","note":"Corrige a Galeno desde la disección directa. La lámina impresa convertida en prueba."},{"author":"Giorgio Vasari","title":"Vidas de los más excelentes pintores, escultores y arquitectos","year":"1550, ampliada en 1568","kind":"primaria","note":"Inventa el relato de la *rinascita* y su periodización, con Florencia en el centro."},{"author":"Moderata Fonte","title":"El mérito de las mujeres","year":"1600","kind":"primaria","note":"Diálogo veneciano de la querella de las mujeres, publicado póstumamente."},{"author":"Jacob Burckhardt","title":"La cultura del Renacimiento en Italia","year":"1860","kind":"estudio","note":"Fija la imagen del individuo moderno y del Estado como obra de arte. Aún es el punto de partida de toda discusión."},{"author":"Johan Huizinga","title":"El otoño de la Edad Media","year":"1919","kind":"estudio","note":"Lee los siglos XIV y XV desde Borgoña como final de una cultura, no como comienzo."},{"author":"Charles H. Haskins","title":"The Renaissance of the Twelfth Century","year":"1927","kind":"estudio","note":"Traslada al siglo XII las novedades atribuidas al XV: universidades, derecho romano, Aristóteles."},{"author":"Hans Baron","title":"The Crisis of the Early Italian Renaissance","year":"1955","kind":"estudio","note":"Formula el humanismo cívico a partir de la crisis florentina de 1402."},{"author":"Paul Oskar Kristeller","title":"Renaissance Thought","year":"1961","kind":"estudio","note":"Define el humanismo como programa de estudios profesional y no como filosofía. Definición hoy operativa."},{"author":"Michael Baxandall","title":"Pintura y vida cotidiana en el Renacimiento","year":"1972","kind":"estudio","note":"Los contratos de encargo y el «ojo de la época» como claves de lectura de la pintura."},{"author":"Joan Kelly","title":"¿Tuvieron las mujeres un Renacimiento?","year":"1977","kind":"estudio","note":"Reformula la periodización desde la historia de las mujeres."},{"author":"Elizabeth Eisenstein","title":"The Printing Press as an Agent of Change","year":"1979","kind":"estudio","note":"La fijeza del texto impreso como condición de la ciencia acumulativa y de la Reforma."},{"author":"Adrian Johns","title":"The Nature of the Book","year":"1998","kind":"estudio","note":"Réplica a Eisenstein: la fiabilidad del impreso se construyó socialmente, no la garantizó la máquina."},{"author":"Lisa Jardine","title":"Worldly Goods","year":"1996","kind":"estudio","note":"El Renacimiento como cultura del consumo y de la adquisición, con Oriente como proveedor."}]},{"type":"images","items":[{"src":"/img/renacimiento/portada.jpg","alt":"Venus emerge del mar de pie sobre una concha, con vientos a su izquierda y una figura que le ofrece un manto a su derecha","width":1200,"height":754,"role":"portada","caption":"El nacimiento de Venus, de Sandro Botticelli (hacia 1485).","author":"Sandro Botticelli","title":"Narodziny Wenus The Birth of Venus","year":"1485","source":"Wikimedia Commons","license":"Public domain","url":"https://commons.wikimedia.org/wiki/File:Sandro_Botticelli_-_La_nascita_di_Venere_-_Google_Art_Project_-_edited.jpg"}]}]'::jsonb, 0, true
from public.topics where slug = 'renacimiento'
on conflict (topic_id, position) do update set
  title = excluded.title, body = excluded.body, published = excluded.published;

-- Lección: revolucion-cientifica
insert into public.lessons (topic_id, title, body, position, published)
select id, 'La revolución científica', '[{"type":"section","title":"El cosmos que había que romper","text":"El modelo heredado no era una superstición ingenua: era un sistema coherente, empíricamente respaldado y con siglos de refinamiento. La Tierra ocupaba el centro porque los cuerpos pesados caen hacia él; los cielos eran de una materia distinta, incorruptible, y se movían en círculos porque el círculo es el movimiento perfecto y sin principio. La física de Aristóteles explicaba el mundo sublunar por tendencias naturales de los cuatro elementos, y la astronomía de Ptolomeo salvaba los fenómenos con epiciclos, deferentes y ecuantes.\n\nEse sistema funcionaba. Predecía eclipses con precisión razonable y encajaba con la experiencia inmediata: no notamos que la Tierra se mueva, y si girase, un objeto lanzado hacia arriba debería quedarse atrás. La objeción no era estúpida; refutarla exigió una física nueva, no solo una astronomía nueva.\n\nTambién tenía problemas conocidos. La acumulación de círculos hacía el modelo inelegante, el ecuante violaba el principio de movimiento circular uniforme que se suponía defender, y el calendario juliano acumulaba un desfase visible que la Iglesia quería corregir. Copérnico trabajó justamente en ese contexto de reforma calendárica.\n\nConviene además desmontar la idea de un vacío científico anterior. La astronomía de la escuela de Maraga, en el siglo XIII, había desarrollado modelos geométricos —el par de Tusi, los modelos de Ibn al-Shatir— matemáticamente equivalentes a los que Copérnico usó. George Saliba ha documentado la coincidencia y sostiene que hubo transmisión, no invención paralela. La cuestión de la ruta exacta sigue abierta.","callout":"Los modelos lunares y planetarios de Ibn al-Shatir (siglo XIV) son matemáticamente idénticos a los de Copérnico. La discusión no es si se parecen, sino por qué vía llegaron a Cracovia."},{"type":"section","title":"Copérnico, Tycho, Kepler","text":"*De revolutionibus orbium coelestium* se publicó en 1543, el año de la muerte de su autor. Copérnico ponía el Sol en el centro para recuperar la pureza del movimiento circular uniforme, no para romper con la tradición: su sistema seguía necesitando círculos auxiliares y no era mucho más preciso que el de Ptolomeo. Andreas Osiander añadió sin permiso un prefacio anónimo que presentaba la hipótesis como un mero recurso de cálculo, lo que amortiguó la reacción durante décadas.\n\nLa objeción empírica más seria era la ausencia de paralaje estelar: si la Tierra se mueve, las estrellas deberían parecer desplazarse a lo largo del año. No se observaba. Los copernicanos respondieron que las estrellas están inimaginablemente lejos, lo cual era cierto pero, en su momento, indistinguible de una excusa. La primera medida de paralaje llegó en 1838.\n\nTycho Brahe aportó lo que faltaba: datos. Desde el observatorio de Uraniborg midió posiciones planetarias con una precisión sin telescopio de alrededor de un minuto de arco, diez veces mejor que la tradición. Sus observaciones de la nova de 1572 y del cometa de 1577 mostraron fenómenos cambiantes más allá de la Luna y por tanto la falsedad de las esferas cristalinas incorruptibles. Su propio modelo era híbrido: los planetas giran alrededor del Sol y el conjunto alrededor de una Tierra inmóvil.\n\nJohannes Kepler heredó esos datos y los tomó en serio hasta el final. Su discrepancia de ocho minutos de arco en la órbita de Marte, que cualquier otro habría atribuido a error de observación, le llevó a abandonar el círculo. En 1609 publicó que las órbitas son elipses con el Sol en un foco y que el radio vector barre áreas iguales en tiempos iguales; en 1619 añadió la relación entre periodo y distancia. Con ello desapareció la necesidad de epiciclos.\n\nKepler no era un moderno con bata. Buscaba las armonías musicales del cosmos y encajó las órbitas en sólidos platónicos. La revolución científica la hicieron personas cuyas motivaciones nos resultan hoy extrañas, y ese desajuste forma parte del objeto de estudio.","callout":null},{"type":"section","title":"Galileo: el instrumento y el conflicto","text":"En 1609 Galileo construyó su propio telescopio y en marzo de 1610 publicó el *Sidereus nuncius*: montañas en la Luna, innumerables estrellas invisibles a simple vista y cuatro satélites girando alrededor de Júpiter, que bautizó como astros mediceos en un movimiento de mecenazgo tan eficaz como calculado. Las fases de Venus, observadas poco después, refutaban el modelo ptolemaico puro, aunque no el de Tycho.\n\nSu aportación decisiva fue física, no astronómica: la ley de caída de los graves, el principio de inercia en su forma inicial y la relatividad del movimiento uniforme, que respondía a la vieja objeción de la piedra que cae al pie del mástil de un barco en marcha. Sin esa física, el heliocentrismo era indefendible.\n\nEl conflicto con Roma se ha contado durante siglo y medio como choque entre ciencia y religión, según el esquema de Draper y White del siglo XIX. La investigación moderna lo ha complicado. En 1616 el Santo Oficio declaró la doctrina heliocéntrica formalmente herética y Belarmino advirtió a Galileo; el criterio expresado era que, sin demostración concluyente, no procedía reinterpretar la Escritura. En 1632 Galileo publicó el *Diálogo sobre los dos máximos sistemas* con licencia, pero puso los argumentos del papa Urbano VIII en boca del personaje llamado Simplicio.\n\nPesaron el género literario elegido, el vulgar toscano en lugar del latín, la ruptura de un patronazgo personal, la presión sobre un papa acusado de blandura en plena guerra de los Treinta Años y la hostilidad de los aristotélicos universitarios, que perdían autoridad. Nada de esto convierte la condena en un episodio menor, pero explica mejor que la fórmula «ciencia contra fe» por qué ocurrió en 1633 y no antes.","callout":"La condena de 1633 no fue el choque de dos bloques. Fue un conflicto de jurisdicción sobre quién interpreta la Escritura, agravado por el mecenazgo roto y por la guerra en Alemania."},{"type":"section","title":"Métodos, instrumentos y hechos públicos","text":"Francis Bacon propuso en el *Novum Organum* de 1620 una alternativa al silogismo: recoger historias naturales, ordenar tablas de presencia y ausencia y ascender por inducción a axiomas cada vez más generales. Su modelo era colectivo y cooperativo, y su imagen de la Casa de Salomón inspiraría a los fundadores de la Royal Society. Nunca hizo un descubrimiento relevante, pero definió una institución.\n\nDescartes fue en dirección contraria: certeza deductiva a partir de principios evidentes, mundo reducido a extensión y movimiento, animales como máquinas. El mecanicismo cartesiano expulsó de la naturaleza las cualidades ocultas y las causas finales; su física resultó falsa casi por completo, y aun así fijó el vocabulario en el que se discutiría durante un siglo.\n\nLo decisivo, en la práctica, fueron los instrumentos y los protocolos. El telescopio, el microscopio de Hooke y Leeuwenhoek, el barómetro de Torricelli, el reloj de péndulo de Huygens y la bomba de vacío de Boyle y Hooke crearon fenómenos que nadie había visto y que exigían una manera nueva de acreditarlos.\n\nSteven Shapin y Simon Schaffer analizaron en 1985 esa operación. La bomba de vacío producía hechos solo si un público cualificado los presenciaba, si la prosa los describía con tal detalle que el lector se convertía en testigo virtual y si se aceptaba discutir sobre efectos observados sin remontarse a causas últimas. Hobbes objetó que ese consenso experimental era frágil y arbitrario y defendió la demostración deductiva. Ganó Boyle, y con él una forma de autoridad basada en el testimonio colectivo.\n\nLas revistas cerraron el círculo. Las *Philosophical Transactions*, desde 1665, fecharon la prioridad, sometieron los textos al juicio de otros miembros y crearon un archivo acumulativo. Con la imprenta, que Elizabeth Eisenstein situó en el centro del proceso, el conocimiento pasó a ser reproducible, comparable y corregible por terceros.","callout":null},{"type":"section","title":"Newton y la síntesis","text":"Los *Principia mathematica philosophiae naturalis*, de 1687, resolvieron el problema abierto por Kepler: por qué los planetas siguen esas órbitas. Newton demostró que una fuerza atractiva inversamente proporcional al cuadrado de la distancia produce las tres leyes keplerianas y explica al mismo tiempo la caída de una piedra, las mareas y la trayectoria de los cometas. Una sola física para el cielo y la tierra.\n\nEl precio fue conceptual. La gravedad actuaba a distancia, sin contacto ni mecanismo visible, lo que a los cartesianos les pareció una recaída en las cualidades ocultas medievales. Newton respondió en el escolio general de 1713 con la fórmula *hypotheses non fingo*: no fabrico hipótesis sobre la causa de la gravedad, me basta con que sus efectos se deduzcan matemáticamente y se verifiquen. Es un desplazamiento de lo que se considera una explicación satisfactoria.\n\nSu *Óptica*, de 1704, escrita en inglés y organizada como serie de experimentos con prismas y cuestiones abiertas, tuvo tanta influencia como los *Principia* y dio el modelo experimental que siguió el siglo XVIII.\n\nLa imagen del primer científico moderno choca con los archivos. John Maynard Keynes, tras comprar en 1936 los manuscritos no publicados, escribió que Newton no fue el primero de la edad de la razón sino el último de los magos: dedicó más páginas a la alquimia y a la cronología bíblica que a la física. La revolución científica no consistió en que unos hombres modernos derrotaran a unos antiguos, sino en que ciertas prácticas —matemáticas, experimentales, públicas— fueron seleccionadas dentro de un conjunto de intereses mucho más amplio.","callout":null},{"type":"section","title":"¿Revolución? El debate historiográfico","text":"Pierre Duhem sostuvo a comienzos del siglo XX que la ciencia moderna nace en la Edad Media, con la condena parisina de 1277, la teoría del ímpetus de Buridán y los calculadores de Merton College. Alistair Crombie prolongó la línea subrayando la tradición experimental medieval. Desde ahí, 1543 no abre nada: culmina.\n\nAlexandre Koyré defendió lo contrario en 1939: lo ocurrido fue una mutación intelectual, el paso del cosmos cerrado y jerarquizado al universo infinito y homogéneo, y la matematización de lo real. Herbert Butterfield popularizó en 1949 la expresión revolución científica y la calificó de acontecimiento sin igual desde el surgimiento del cristianismo. Thomas Kuhn dio en 1962 el vocabulario que aún usamos —paradigma, ciencia normal, inconmensurabilidad— y con él la idea de que los cambios profundos no son acumulativos.\n\nEl eje interno frente a externo cruza esa discusión. Boris Hessen defendió en 1931 que los *Principia* responden a problemas técnicos de la minería, la balística y la navegación. Edgar Zilsel atribuyó el nacimiento del método a la unión entre el saber manual de artesanos, ingenieros y navegantes y la formación matemática de los universitarios. Robert Merton correlacionó en 1938 puritanismo y actividad científica en la Inglaterra del XVII. Koyré replicó que las ideas cambian por su propia lógica. Hoy casi nadie sostiene ninguna de las dos posiciones en estado puro.\n\nLa formulación más radical la dio Steven Shapin en 1996 al abrir su libro afirmando que no existió tal cosa como la revolución científica, y que sobre eso trataba precisamente el libro. Su argumento: no hubo un método único, ni un momento único, ni una comunidad unificada, sino prácticas heterogéneas agrupadas después por conveniencia narrativa.\n\nEl estado actual es un equilibrio. Se conserva la etiqueta como periodización útil, se rechaza el relato heroico de genios que derrotan a la superstición, se subraya la continuidad técnica con las tradiciones latina e islámica y se admite el resultado: hacia 1700 había cambiado de manera duradera qué se aceptaba como prueba, quién podía producirla y dónde se hacía pública.","callout":"Shapin abre su libro con «no existió tal cosa como la revolución científica, y este libro trata de ella». La provocación resume el consenso: la etiqueta sirve como periodización, no como explicación."},{"type":"concepts","items":[{"term":"Ecuante","definition":"Punto ptolemaico desde el que el movimiento parece uniforme. Violaba el principio circular que decía defender: uno de los motivos de Copérnico."},{"term":"Paralaje estelar","definition":"Desplazamiento aparente de las estrellas por el movimiento terrestre. Su ausencia fue la objeción más fuerte al heliocentrismo hasta 1838."},{"term":"Escuela de Maraga","definition":"Tradición astronómica islámica de los siglos XIII-XIV. Sus modelos, como el par de Tusi, son equivalentes a los usados por Copérnico."},{"term":"Órbita elíptica","definition":"Primera ley de Kepler (1609): los planetas describen elipses con el Sol en uno de los focos. Elimina la necesidad de epiciclos."},{"term":"Ley de áreas","definition":"Segunda ley de Kepler: el radio vector barre áreas iguales en tiempos iguales. Los planetas no se mueven a velocidad constante."},{"term":"Principio de inercia","definition":"Un cuerpo mantiene su movimiento uniforme si nada lo altera. Sin él, la objeción de la piedra y el mástil hacía indefendible el heliocentrismo."},{"term":"Mecanicismo","definition":"Explicación del mundo natural solo por materia, figura y movimiento, sin causas finales ni cualidades ocultas. Programa cartesiano."},{"term":"Inducción baconiana","definition":"Ascenso desde historias naturales y tablas de presencia y ausencia hasta axiomas generales. Modelo colectivo, no individual."},{"term":"Testigo virtual","definition":"Concepto de Shapin y Schaffer: la prosa experimental detallada convierte al lector ausente en testigo del hecho."},{"term":"Hypotheses non fingo","definition":"Fórmula de Newton (1713): describe matemáticamente los efectos de la gravedad sin postular su causa. Redefine qué es explicar."},{"term":"Philosophical Transactions","definition":"Revista de la Royal Society desde 1665. Fija prioridad, somete los textos a juicio de pares y crea archivo acumulativo."},{"term":"Tesis de Zilsel","definition":"El método experimental nace de la unión entre el saber manual de artesanos e ingenieros y la formación matemática universitaria."},{"term":"Tesis de Merton","definition":"Correlación entre ética puritana y actividad científica en la Inglaterra del siglo XVII. Muy discutida en su mecanismo causal."},{"term":"Paradigma","definition":"En Kuhn (1962), el conjunto de supuestos, problemas y modelos que define la ciencia normal. Los cambios de paradigma no son acumulativos."}]},{"type":"debates","items":[{"question":"¿Ruptura revolucionaria o continuidad con la Edad Media?","positions":[{"school":"Continuidad (Duhem, Crombie)","argument":"La condena de 1277, la teoría del ímpetus, los calculadores de Merton College y la óptica medieval contienen ya lo esencial: 1543 culmina un proceso largo en lugar de abrirlo."},{"school":"Mutación intelectual (Koyré, Butterfield, Kuhn)","argument":"Lo ocurrido fue un cambio de mundo: del cosmos cerrado y jerárquico al universo infinito y homogéneo, con matematización de lo real e inconmensurabilidad entre marcos."},{"school":"Disolución (Shapin, 1996)","argument":"No hubo método único, ni momento único, ni comunidad unificada. La revolución científica es una agrupación retrospectiva de prácticas heterogéneas."}],"state":"Se conserva la etiqueta como periodización útil y se descarta el relato heroico. Hay acuerdo en la continuidad técnica con las tradiciones latina e islámica y en que hacia 1700 había cambiado de forma duradera qué contaba como prueba."},{"question":"¿Causas internas o sociales?","positions":[{"school":"Externalismo (Hessen 1931, Zilsel 1942, Merton 1938)","argument":"Los problemas venían de la minería, la balística y la navegación; el método nació del contacto entre artesanos y universitarios, y ciertas confesiones favorecieron la práctica científica."},{"school":"Internalismo (Koyré)","argument":"Las ideas cambian por su propia lógica. Ni la técnica ni la religión explican por qué se abandonó el círculo perfecto o se matematizó el movimiento."}],"state":"Nadie sostiene ya ninguna posición pura. Se estudian conjuntamente las prácticas materiales, el mecenazgo, la circulación impresa y la argumentación teórica, sin reducir unas a otras."},{"question":"El caso Galileo: ¿ciencia contra religión?","positions":[{"school":"Tesis del conflicto (Draper 1874, White 1896)","argument":"La condena de 1633 ilustra la oposición estructural entre la investigación libre y una autoridad religiosa que defiende el dogma frente a la evidencia."},{"school":"Lectura contextual (Blackwell, Fantoli, Biagioli)","argument":"Pesaron la jurisdicción sobre la interpretación de la Escritura, el mecenazgo roto con Urbano VIII, la elección del vulgar toscano, la guerra de los Treinta Años y los intereses de los aristotélicos universitarios."}],"state":"La tesis del conflicto está abandonada como marco general. La lectura contextual predomina, sin que ello reste gravedad a la condena ni convierta el episodio en un simple malentendido personal."}]},{"type":"timeline","items":[{"date":"1543","event":"Copérnico publica *De revolutionibus* y Vesalio *De humani corporis fabrica*."},{"date":"1572 y 1577","event":"Tycho Brahe observa una nova y un cometa por encima de la Luna: los cielos cambian."},{"date":"1600","event":"Giordano Bruno es quemado en Roma; Gilbert publica *De magnete*."},{"date":"1609–1619","event":"Kepler formula las tres leyes del movimiento planetario a partir de los datos de Tycho."},{"date":"1610","event":"*Sidereus nuncius*: Galileo publica lo que ve con el telescopio."},{"date":"1620","event":"Bacon publica el *Novum Organum* y propone un método inductivo y colectivo."},{"date":"1628","event":"Harvey demuestra la circulación de la sangre en *De motu cordis*."},{"date":"1632–1633","event":"El *Diálogo* de Galileo y su condena por el Santo Oficio."},{"date":"1637","event":"Descartes publica el *Discurso del método* con la *Geometría* como apéndice."},{"date":"1660–1666","event":"Se fundan la Royal Society de Londres y la Académie des Sciences de París."},{"date":"1665","event":"Aparecen las *Philosophical Transactions*, primera revista científica periódica."},{"date":"1687","event":"Newton publica los *Principia*: una sola ley explica la caída de los cuerpos y las órbitas."}]},{"type":"sources","items":[{"author":"Nicolás Copérnico","title":"De revolutionibus orbium coelestium","year":"1543","kind":"primaria","note":"Con el prefacio anónimo de Osiander que presenta el heliocentrismo como recurso de cálculo."},{"author":"Andrés Vesalio","title":"De humani corporis fabrica","year":"1543","kind":"primaria","note":"Anatomía basada en disección propia frente a la autoridad de Galeno."},{"author":"William Gilbert","title":"De magnete","year":"1600","kind":"primaria","note":"La Tierra como imán. Trabajo experimental temprano y muy citado por Galileo y Kepler."},{"author":"Johannes Kepler","title":"Astronomia nova","year":"1609","kind":"primaria","note":"Órbitas elípticas y ley de áreas, deducidas de los datos de Marte de Tycho Brahe."},{"author":"Galileo Galilei","title":"Sidereus nuncius","year":"1610","kind":"primaria","note":"Montañas lunares y satélites de Júpiter, dedicados a los Médici como operación de mecenazgo."},{"author":"Francis Bacon","title":"Novum Organum","year":"1620","kind":"primaria","note":"Método inductivo, crítica de los ídolos y programa de investigación colectiva."},{"author":"William Harvey","title":"De motu cordis","year":"1628","kind":"primaria","note":"Circulación de la sangre demostrada con medición del volumen expulsado por el corazón."},{"author":"Galileo Galilei","title":"Diálogo sobre los dos máximos sistemas del mundo","year":"1632","kind":"primaria","note":"En toscano y con licencia. El argumento de Urbano VIII lo pronuncia el personaje Simplicio."},{"author":"Santo Oficio","title":"Sentencia y abjuración de Galileo","year":"1633","kind":"primaria","note":"Documento central para reconstruir los cargos reales y el papel del precepto de 1616."},{"author":"René Descartes","title":"Discurso del método","year":"1637","kind":"primaria","note":"Duda metódica y mecanicismo. Incluye la *Geometría*, que une álgebra y geometría."},{"author":"Robert Boyle","title":"New Experiments Physico-Mechanical","year":"1660","kind":"primaria","note":"Experimentos con la bomba de vacío y protocolo de testimonio público del hecho."},{"author":"Robert Hooke","title":"Micrographia","year":"1665","kind":"primaria","note":"El microscopio como productor de fenómenos nuevos. Acuña el término célula."},{"author":"Isaac Newton","title":"Philosophiae naturalis principia mathematica","year":"1687","kind":"primaria","note":"Gravitación universal: una sola ley para la caída de los cuerpos y las órbitas planetarias."},{"author":"Isaac Newton","title":"Óptica","year":"1704","kind":"primaria","note":"En inglés y organizada como serie de experimentos. Modelo para la ciencia experimental del XVIII."},{"author":"Boris Hessen","title":"Las raíces socioeconómicas de la mecánica de Newton","year":"1931","kind":"estudio","note":"Manifiesto externalista presentado en Londres en 1931."},{"author":"Robert K. Merton","title":"Ciencia, tecnología y sociedad en la Inglaterra del siglo XVII","year":"1938","kind":"estudio","note":"Correlación entre puritanismo y práctica científica."},{"author":"Alexandre Koyré","title":"Estudios galileanos","year":"1939","kind":"estudio","note":"La revolución como mutación intelectual y matematización de lo real."},{"author":"Herbert Butterfield","title":"Los orígenes de la ciencia moderna","year":"1949","kind":"estudio","note":"Populariza la expresión «revolución científica» y su valoración máxima."},{"author":"Thomas S. Kuhn","title":"La estructura de las revoluciones científicas","year":"1962","kind":"estudio","note":"Paradigma, ciencia normal e inconmensurabilidad. Cambia el vocabulario de toda la disciplina."},{"author":"Elizabeth Eisenstein","title":"La imprenta como agente de cambio","year":"1979","kind":"estudio","note":"Fijeza tipográfica, reproducción de tablas y láminas, acumulación y corrección pública."},{"author":"Steven Shapin y Simon Schaffer","title":"El Leviathan y la bomba de vacío","year":"1985","kind":"estudio","note":"Boyle contra Hobbes: cómo se fabrica un hecho experimental y quién puede atestiguarlo."},{"author":"Steven Shapin","title":"La revolución científica","year":"1996","kind":"estudio","note":"Niega la existencia de un método y un momento únicos y reconstruye prácticas heterogéneas."},{"author":"George Saliba","title":"Islamic Science and the Making of the European Renaissance","year":"2007","kind":"estudio","note":"Documenta la equivalencia entre los modelos de Maraga y los de Copérnico."}]},{"type":"images","items":[{"src":"/img/revolucion-cientifica/portada.jpg","alt":"Retrato de Galileo Galilei anciano, de tres cuartos, con barba blanca y gola oscura","width":1200,"height":1524,"role":"portada","caption":"Galileo retratado por Justus Sustermans en 1636, ya condenado y bajo arresto domiciliario.","author":"Justus Sustermans","title":"Portrait of Galileo Galilei","year":"1636","source":"Wikimedia Commons","license":"Public domain","url":"https://commons.wikimedia.org/wiki/File:Justus_Sustermans_-_Portrait_of_Galileo_Galilei%2C_1636.jpg"}]}]'::jsonb, 0, true
from public.topics where slug = 'revolucion-cientifica'
on conflict (topic_id, position) do update set
  title = excluded.title, body = excluded.body, published = excluded.published;

-- Lección: revolucion-francesa
insert into public.lessons (topic_id, title, body, position, published)
select id, 'Revolución francesa y era napoleónica', '[{"type":"section","title":"Una quiebra, no una decadencia","text":"El siglo XVIII francés fue de crecimiento: la población pasó de unos veintidós a veintiocho millones, el comercio atlántico se multiplicó, la producción agraria aumentó y las ciudades se llenaron de profesionales, funcionarios y rentistas. Explicar 1789 por la miseria no funciona; la coyuntura de 1788, con una cosecha desastrosa y el pan a precios inasumibles, agravó la crisis pero no la causó.\n\nLo que estaba roto era la hacienda. Las guerras del siglo, y sobre todo el apoyo a la independencia de las trece colonias, dejaron una deuda cuyo servicio consumía en torno a la mitad del gasto. Francia no era pobre: recaudaba mal. Los dos primeros estados y numerosas ciudades, provincias y corporaciones disfrutaban de exenciones, y los intentos de gravar la riqueza de forma general chocaron con los parlamentos, que se presentaban como defensores de la nación frente al despotismo ministerial.\n\nCuando Calonne propuso en 1787 una contribución territorial sin exenciones, la Asamblea de Notables respondió que semejante reforma solo podía aprobarla la nación reunida. La aristocracia bloqueó el arreglo fiscal en nombre de la libertad y con ello abrió la puerta a los Estados Generales, que no se reunían desde 1614. Georges Lefebvre llamó a ese episodio revuelta aristocrática; sin ella no hay 1789.\n\nLa convocatoria trajo dos novedades explosivas. Se duplicó la representación del tercer estado, sin garantizar el voto por cabeza en lugar de por orden, y se pidieron cuadernos de quejas a todas las circunscripciones. Los cahiers de doléances son la mayor encuesta de opinión del Antiguo Régimen: miles de textos que critican el privilegio fiscal, la justicia señorial y los diezmos, y que en su inmensa mayoría no piden abolir la monarquía sino repararla.\n\nEl panfleto de Sieyès de enero de 1789 formuló el argumento decisivo con tres preguntas: qué es el tercer estado, todo; qué ha sido hasta ahora en el orden político, nada; qué pide, ser algo. La nación se define ahí como el conjunto de quienes trabajan y sostienen la sociedad, y el privilegio queda fuera de ella por definición.","callout":"La reforma fiscal la bloqueó la aristocracia, no el pueblo. Sin la revuelta de los privilegiados de 1787-1788 no se habrían convocado los Estados Generales."},{"type":"section","title":"1789: cuatro meses que inventan un régimen","text":"La cuestión del voto por cabeza paralizó la asamblea desde mayo. El 17 de junio los diputados del tercero se proclamaron Asamblea Nacional, y el 20, encontrando cerrada su sala, juraron en la del Juego de Pelota no separarse hasta dar a Francia una constitución. Es el acto fundacional: un grupo de representantes decide que la soberanía está en la nación y actúa en consecuencia.\n\nLa toma de la Bastilla el 14 de julio fue militarmente menor —había siete presos— y políticamente decisiva: mostró que París podía imponerse por la fuerza y que el ejército no era fiable. En las semanas siguientes el Gran Miedo, estudiado por Lefebvre en 1932, propagó por el campo el rumor de un complot aristocrático con bandidos a sueldo; los campesinos se armaron, asaltaron castillos y quemaron sobre todo los archivos donde constaban sus obligaciones señoriales.\n\nLa noche del 4 de agosto la Asamblea respondió a esa presión con una renuncia colectiva de privilegios que abolió el régimen señorial, los diezmos, la venalidad y las exenciones. La letra pequeña llegó días después: los derechos considerados propiedad debían rescatarse con pago, condición que el campesinado ignoró y que quedó suprimida sin indemnización en 1793.\n\nEl 26 de agosto se aprobó la Declaración de Derechos del Hombre y del Ciudadano: los hombres nacen libres e iguales en derechos, la soberanía reside esencialmente en la nación, la ley es expresión de la voluntad general, nadie puede ser inquietado por sus opiniones ni detenido sin ley previa. No era un programa social sino una demolición jurídica del orden estamental, y como tal se leyó en toda Europa.\n\nEn octubre, las mujeres de los mercados parisinos marcharon a Versalles por el precio del pan y trajeron a la familia real a París. El poder quedaba bajo la vigilancia física de la capital, un hecho que condicionará todo lo que sigue.","callout":null},{"type":"section","title":"Reconstruir el reino y partirlo en dos","text":"La Asamblea Constituyente hizo en dos años una obra administrativa enorme: dividió Francia en departamentos de tamaño homogéneo, suprimió las aduanas interiores, unificó pesos y medidas con el sistema métrico, abolió los gremios, declaró libre el trabajo, reorganizó la justicia con jueces electos y creó el jurado. Buena parte de esa arquitectura sigue en pie.\n\nTambién tomó la decisión que rompería el consenso. Para saldar la deuda nacionalizó los bienes de la Iglesia, emitió contra ellos unos títulos, los asignados, que acabaron convertidos en papel moneda inflacionario, y reorganizó la institución eclesiástica mediante la Constitución civil del clero de julio de 1790: diócesis ajustadas a los departamentos, obispos y párrocos elegidos por los ciudadanos y sueldo del Estado. Al exigir en noviembre un juramento de fidelidad, el país se partió: alrededor de la mitad del clero lo prestó y la otra mitad no, con distribución geográfica muy marcada.\n\nTimothy Tackett ha demostrado que ese juramento es el mejor predictor territorial de la contrarrevolución posterior. La Revolución dejó de ser un conflicto entre privilegio y nación y pasó a serlo también entre dos formas de entender la vida religiosa de comunidades enteras.\n\nLa huida del rey a Varennes en junio de 1791, detenido a pocos kilómetros de la frontera tras dejar un manifiesto que desautorizaba todo lo hecho, destruyó la ficción del monarca constitucional. La Constitución de 1791 se aprobó igualmente, con sufragio censitario y distinción entre ciudadanos activos y pasivos, pero ya nadie creía en su viabilidad.\n\nLa Asamblea legisló además contra la organización obrera: la ley Le Chapelier de junio de 1791 prohibió coaliciones y asociaciones profesionales en nombre de la libertad individual y de la unidad de la nación. Estuvo vigente hasta 1864 y es la prueba de que la igualdad proclamada era jurídica, no social.","callout":"El juramento exigido al clero en 1790 partió a Francia por la mitad y predice, comarca a comarca, dónde habrá contrarrevolución tres años después."},{"type":"section","title":"Guerra, república y Terror","text":"La guerra declarada a Austria en abril de 1792 fue querida por casi todos: por los girondinos, que esperaban propagar la libertad y desenmascarar al rey; por la corte, que esperaba la derrota; solo Robespierre advirtió que nadie ama a los misioneros armados. Las derrotas iniciales y el manifiesto de Brunswick, que amenazaba a París con la destrucción, produjeron el asalto a las Tullerías del 10 de agosto y el fin de la monarquía.\n\nEn septiembre, con los prusianos avanzando, multitudes asaltaron las prisiones parisinas y ejecutaron a más de mil detenidos. Las masacres de septiembre son el primer episodio de violencia masiva no espontáneamente popular sino tolerada por las autoridades, y marcan el clima en que se elige la Convención. Esta proclama la República el 21 de septiembre y juzga al rey: ejecutado el 21 de enero de 1793.\n\nLa primavera de 1793 acumula catástrofes: coalición europea, traición de Dumouriez, insurrección campesina y católica en la Vendée, revueltas federalistas en Lyon, Marsella, Burdeos y Tolón, y hambre urbana. La respuesta fue el gobierno revolucionario: un Comité de Salvación Pública con poderes ejecutivos, representantes en misión con autoridad plena en provincias, tribunal revolucionario, requisas, control de precios mediante el maximum général, leva en masa de agosto y Ley de Sospechosos de septiembre, que permitía detener por conducta, relaciones o escritos.\n\nLas cifras conocidas ayudan a medir. Los tribunales revolucionarios dictaron alrededor de diecisiete mil condenas a muerte; las víctimas totales de la represión, incluidas ejecuciones sumarias y muertes en prisión, se estiman entre treinta y cuarenta mil; la guerra de la Vendée causó entre ciento cincuenta mil y doscientos cincuenta mil muertos en ambos bandos. La mayor parte de la violencia se concentra en las zonas de guerra civil y de frontera, no en París.\n\nEl Terror tuvo también una dimensión cultural: descristianización, calendario republicano, culto del Ser Supremo, fiestas cívicas. Y terminó por implosión: tras la ley de Pradial que suprimió las garantías procesales y aceleró las ejecuciones, la propia Convención derribó a Robespierre el 9 de Termidor, temiendo ser la siguiente en la lista.","callout":null},{"type":"section","title":"Cómo se explica el Terror","text":"La lectura clásica, de Albert Mathiez a Albert Soboul, subraya las circunstancias: invasión exterior, guerra civil interior, hambre y conspiración real. El gobierno revolucionario habría sido una dictadura de salud pública, transitoria y eficaz, que salvó a la República y cuya violencia se explica por la presión de las masas urbanas y por la emergencia. Soboul añadió el análisis social de los sans-culottes: artesanos, tenderos y asalariados organizados por secciones, con una cultura política propia de democracia directa y precio justo.\n\nLa crítica revisionista invirtió la causalidad. Augustin Cochin ya había señalado el papel de las sociedades de pensamiento; François Furet sostuvo en 1978 que el Terror no fue un accidente sino una consecuencia del propio lenguaje revolucionario: si la soberanía pertenece a una voluntad general única e indivisible, quien discrepa no es minoría sino enemigo, y no hay lugar institucional para la oposición. La Revolución se explicaría por su dinámica discursiva más que por su situación militar.\n\nTimothy Tackett ha propuesto una tercera vía documentada con centenares de cartas y diarios: ni pura circunstancia ni pura ideología, sino un proceso de radicalización alimentado por el miedo, la experiencia real de complots y deserciones y el aprendizaje político acelerado de gente que en 1789 no era revolucionaria. Su punto fuerte es explicar por qué unos mismos hombres cambian de posición en cuatro años.\n\nLa Vendée genera un debate propio. Reynald Secher sostuvo en 1986 que las columnas infernales practicaron un genocidio planificado. Jean-Clément Martin ha respondido que la represión fue atroz pero descentralizada, sin plan de exterminio de una población definida como tal, y que la cifra de víctimas se ha inflado; la mayoría de la historiografía académica rechaza hoy la calificación de genocidio sin minimizar la magnitud de la matanza.\n\nQueda la pregunta de fondo: ¿fue la Revolución burguesa? Alfred Cobban negó en 1964 que existiera una burguesía capitalista enfrentada a una nobleza feudal: los revolucionarios eran sobre todo juristas y funcionarios, y nobles y burgueses compartían inversiones y modo de vida. Furet y Doyle desarrollaron esa crítica hasta convertir la Revolución en un acontecimiento político antes que social. La historiografía actual, con Peter McPhee o William Sewell, ha vuelto a lo social sin volver al esquema de clases: estudia el trabajo, el género, la esclavitud colonial y la cultura material.","callout":"Furet: si la soberanía es una voluntad general indivisible, el que discrepa no es adversario sino enemigo. El Terror estaría inscrito en la gramática de 1789, no solo en la guerra de 1793."},{"type":"section","title":"Napoleón: heredero y liquidador","text":"El Directorio sobrevivió cuatro años entre golpes de mano contra realistas y jacobinos, con una economía sin crédito y una guerra permanente que dio a los generales un poder político creciente. El 18 de Brumario de 1799 Bonaparte, general prestigioso por Italia y hábil publicista de su campaña de Egipto, liquidó el régimen con apoyo de una parte del propio Directorio.\n\nEl Consulado consolidó lo que la burguesía revolucionaria quería conservar y suprimió lo que temía. Concordato con Roma en 1801, que reconocía al catolicismo como religión de la mayoría sin devolver los bienes nacionales; Banco de Francia y franco germinal; prefectos nombrados desde París al frente de los departamentos; liceos y Universidad imperial; y sobre todo el Código Civil de 1804, que fijó igualdad ante la ley, propiedad absoluta, libertad contractual, matrimonio civil y secularización del estado civil.\n\nEl mismo código consagró la autoridad marital, la incapacidad jurídica de la mujer casada y la desigualdad en el divorcio y en el adulterio. Y en 1802 el régimen restableció la esclavitud en las colonias, revocando la abolición de 1794; en Saint-Domingue la expedición enviada a imponerla fue derrotada y la colonia proclamó su independencia como Haití en 1804. La Revolución produjo la primera abolición de la esclavitud de la historia moderna y también su primera restauración.\n\nEl Imperio proclamado en 1804 llevó la guerra a toda Europa. Austerlitz en 1805 marcó el cénit continental; Trafalgar, el mismo año, la imposibilidad de vencer en el mar. El bloqueo continental intentó asfixiar económicamente a Gran Bretaña y acabó asfixiando a los aliados de Francia y empujando a Napoleón a intervenir en España en 1808 y a invadir Rusia en 1812. De los más de seiscientos mil hombres de la Grande Armée regresaron pocas decenas de miles.\n\nEl balance es doble y así se enseña. Napoleón exportó a media Europa la igualdad ante la ley, la abolición del régimen señorial, el registro civil y el código, disolvió el Sacro Imperio y provocó, por reacción, los nacionalismos alemán y español. Y lo hizo mediante conquista, censura, policía política y una guerra que costó entre tres y cinco millones de vidas. Los dos hechos son el mismo hecho.","callout":null},{"type":"concepts","items":[{"term":"Cahiers de doléances","definition":"Cuadernos de quejas redactados en 1789 por todas las circunscripciones. La mayor encuesta de opinión del Antiguo Régimen."},{"term":"Voto por cabeza","definition":"Reivindicación del tercer estado frente al voto por orden, que anulaba su doble representación. Origen del bloqueo de mayo de 1789."},{"term":"Gran Miedo","definition":"Pánico rural de julio-agosto de 1789 ante un supuesto complot aristocrático. Estudiado por Lefebvre en 1932."},{"term":"Noche del 4 de agosto","definition":"Renuncia colectiva de privilegios que abolió el régimen señorial y los diezmos, con rescate en dinero suprimido después en 1793."},{"term":"Constitución civil del clero","definition":"Ley de 1790 que reorganiza la Iglesia francesa y exige juramento. Divide al país y anticipa la geografía de la contrarrevolución."},{"term":"Asignado","definition":"Título emitido contra los bienes nacionalizados de la Iglesia. Convertido en papel moneda, provocó una inflación devastadora."},{"term":"Ley Le Chapelier","definition":"Norma de 1791 que prohíbe coaliciones y asociaciones profesionales. Vigente hasta 1864: la igualdad proclamada era jurídica, no social."},{"term":"Sans-culottes","definition":"Artesanos, tenderos y asalariados parisinos organizados por secciones. Democracia directa, precio justo y presión armada sobre la Convención."},{"term":"Comité de Salvación Pública","definition":"Órgano ejecutivo del gobierno revolucionario desde 1793, con poderes de guerra, policía y administración."},{"term":"Ley de Sospechosos","definition":"Norma de septiembre de 1793 que autoriza detener por conducta, relaciones o escritos. Base jurídica del Terror."},{"term":"Maximum général","definition":"Control de precios y salarios impuesto en 1793 bajo presión de los sans-culottes. Abandonado tras Termidor."},{"term":"Termidor","definition":"Caída de Robespierre el 9 de Termidor del año II (27 de julio de 1794) por iniciativa de la propia Convención."},{"term":"Código Civil","definition":"Código de 1804: igualdad ante la ley, propiedad absoluta y libertad contractual, junto a la incapacidad jurídica de la mujer casada."},{"term":"Bloqueo continental","definition":"Cierre del continente al comercio británico desde 1806. Arruinó a los aliados de Francia y arrastró al Imperio a España y a Rusia."}]},{"type":"debates","items":[{"question":"¿Fue una revolución burguesa?","positions":[{"school":"Interpretación clásica (Lefebvre, Soboul)","argument":"Una burguesía en ascenso derribó el orden feudal con apoyo campesino y popular, e impuso las condiciones jurídicas del capitalismo: propiedad libre, mercado unificado, abolición del privilegio."},{"school":"Revisionismo (Cobban 1964, Furet, Doyle)","argument":"No había una burguesía capitalista enfrentada a una nobleza feudal: los revolucionarios fueron juristas y funcionarios, y nobles y burgueses compartían rentas e inversiones. La Revolución fue política antes que social."},{"school":"Nueva historia social (McPhee, Sewell)","argument":"Vuelve a lo social sin el esquema de clases: trabajo, género, campesinado, esclavitud colonial y cultura material explican el proceso mejor que la lucha entre dos bloques."}],"state":"El modelo clásico de dos clases está abandonado; también lo está la reducción de todo a discurso político. La síntesis actual combina crisis fiscal, cultura política, conflicto rural y dimensión colonial."},{"question":"El Terror: ¿circunstancias o ideología?","positions":[{"school":"Circunstancias (Mathiez, Soboul)","argument":"Invasión, guerra civil, hambre y conspiración explican una dictadura de salud pública transitoria que salvó a la República y respondió a la presión popular."},{"school":"Lógica del discurso (Furet, 1978)","argument":"Una soberanía concebida como voluntad general única no deja lugar institucional a la oposición: el disidente se convierte en enemigo. El Terror es coherente con el lenguaje de 1789."},{"school":"Radicalización contingente (Tackett)","argument":"Cartas y diarios muestran a hombres que no eran revolucionarios en 1789 y que se radicalizan por miedo, complots reales y aprendizaje político acelerado."}],"state":"Se ha impuesto una lectura de proceso: la violencia no estaba escrita en 1789 ni se deduce solo de la guerra. Se estudia como resultado de decisiones sucesivas bajo presión, con la ideología funcionando como marco interpretativo del miedo."},{"question":"¿Fue la Vendée un genocidio?","positions":[{"school":"Secher (1986)","argument":"Las columnas infernales ejecutaron un plan de exterminio de una población definida por su territorio y su fe: corresponde la calificación jurídica de genocidio."},{"school":"Martin y la historiografía académica mayoritaria","argument":"La represión fue atroz pero descentralizada y sin plan de exterminio poblacional; las cifras se han inflado y el marco de guerra civil describe mejor lo ocurrido."}],"state":"La calificación de genocidio es minoritaria en la investigación académica y muy presente en el debate público francés. Hay acuerdo en la magnitud de la matanza: entre 150.000 y 250.000 muertos en ambos bandos."}]},{"type":"timeline","items":[{"date":"1787–1788","event":"La Asamblea de Notables rechaza la reforma fiscal y fuerza la convocatoria de los Estados Generales."},{"date":"17–20 de junio de 1789","event":"El tercer estado se proclama Asamblea Nacional y jura no separarse sin dar una constitución."},{"date":"14 de julio de 1789","event":"Toma de la Bastilla; en las semanas siguientes el Gran Miedo recorre el campo."},{"date":"4 y 26 de agosto de 1789","event":"Abolición nocturna de los privilegios y Declaración de Derechos del Hombre y del Ciudadano."},{"date":"Julio de 1790","event":"Constitución civil del clero: la ruptura que parte al país en dos."},{"date":"Junio de 1791","event":"Fuga a Varennes. El rey deja de ser creíble como monarca constitucional."},{"date":"Abril–agosto de 1792","event":"Guerra contra Austria y Prusia; asalto a las Tullerías y caída de la monarquía."},{"date":"Enero–marzo de 1793","event":"Ejecución de Luis XVI, coalición europea y sublevación de la Vendée."},{"date":"Septiembre de 1793 – julio de 1794","event":"Gobierno revolucionario, Ley de Sospechosos y Terror hasta el 9 de Termidor."},{"date":"9 de noviembre de 1799","event":"18 de Brumario: Bonaparte liquida el Directorio."},{"date":"1801–1804","event":"Concordato, Banco de Francia, Código Civil y proclamación del Imperio."},{"date":"1812–1815","event":"Campaña de Rusia, Leipzig, primera abdicación y Waterloo."}]},{"type":"sources","items":[{"author":"Emmanuel Sieyès","title":"¿Qué es el tercer estado?","year":"1789","kind":"primaria","note":"Todo, nada, algo. Define la nación excluyendo al privilegio por definición."},{"author":"Circunscripciones francesas","title":"Cahiers de doléances","year":"1789","kind":"primaria","note":"Miles de cuadernos de quejas. Critican el privilegio fiscal sin pedir abolir la monarquía."},{"author":"Asamblea Nacional","title":"Declaración de Derechos del Hombre y del Ciudadano","year":"1789","kind":"primaria","note":"Soberanía nacional, igualdad ante la ley y derechos anteriores al Estado."},{"author":"Asamblea Nacional","title":"Constitución civil del clero","year":"1790","kind":"primaria","note":"Reorganiza la Iglesia y exige juramento. Rompe el consenso de 1789."},{"author":"Edmund Burke","title":"Reflexiones sobre la Revolución en Francia","year":"1790","kind":"primaria","note":"Primera gran formulación del conservadurismo moderno frente al racionalismo constituyente."},{"author":"Asamblea Nacional","title":"Ley Le Chapelier","year":"1791","kind":"primaria","note":"Prohíbe coaliciones y asociaciones profesionales. Vigente hasta 1864."},{"author":"Olympe de Gouges","title":"Declaración de los derechos de la mujer y de la ciudadana","year":"1791","kind":"primaria","note":"Denuncia que la ciudadanía proclamada excluye a la mitad de la población."},{"author":"Convención Nacional","title":"Ley de Sospechosos","year":"1793","kind":"primaria","note":"Permite detener por conducta, relaciones o escritos. Base jurídica del Terror."},{"author":"Maximilien Robespierre","title":"Sobre los principios de moral política","year":"1794","kind":"primaria","note":"Virtud y terror como principios del gobierno revolucionario en tiempo de guerra."},{"author":"Toussaint Louverture","title":"Constitución de Saint-Domingue","year":"1801","kind":"primaria","note":"Autonomía colonial y abolición de la esclavitud antes de la expedición napoleónica."},{"author":"Estado francés","title":"Código Civil de los franceses","year":"1804","kind":"primaria","note":"Igualdad ante la ley y propiedad absoluta, junto a la incapacidad jurídica de la mujer casada."},{"author":"Jules Michelet","title":"Historia de la Revolución francesa","year":"1847-1853","kind":"estudio","note":"El pueblo como sujeto colectivo. Fundacional para la tradición republicana francesa."},{"author":"Albert Mathiez","title":"La Revolución francesa","year":"1922-1927","kind":"estudio","note":"Defensa del gobierno revolucionario como dictadura de salud pública."},{"author":"Georges Lefebvre","title":"El Gran Miedo de 1789","year":"1932","kind":"estudio","note":"Reconstruye el pánico rural y sitúa al campesinado como actor autónomo."},{"author":"Albert Soboul","title":"Los sans-culottes parisinos en el año II","year":"1958","kind":"estudio","note":"Análisis social del movimiento seccional y de su cultura política."},{"author":"Alfred Cobban","title":"The Social Interpretation of the French Revolution","year":"1964","kind":"estudio","note":"Abre el revisionismo: no había una burguesía capitalista contra una nobleza feudal."},{"author":"François Furet","title":"Pensar la Revolución francesa","year":"1978","kind":"estudio","note":"El Terror como consecuencia de la lógica de la voluntad general indivisible."},{"author":"Lynn Hunt","title":"Politics, Culture, and Class in the French Revolution","year":"1984","kind":"estudio","note":"Giro cultural: símbolos, retórica y prácticas como objeto central del análisis."},{"author":"Reynald Secher","title":"La Vendée-Vengé: le génocide franco-français","year":"1986","kind":"estudio","note":"Tesis del genocidio vendeano, minoritaria en la academia y muy presente en el debate público."},{"author":"William Doyle","title":"The Oxford History of the French Revolution","year":"1989","kind":"estudio","note":"Síntesis revisionista de referencia en lengua inglesa."},{"author":"Timothy Tackett","title":"Becoming a Revolutionary","year":"1996","kind":"estudio","note":"Muestra con diarios y cartas cómo diputados no revolucionarios se radicalizan."},{"author":"Laurent Dubois","title":"Avengers of the New World","year":"2004","kind":"estudio","note":"La revolución haitiana como parte constitutiva, y no periférica, del ciclo revolucionario."},{"author":"Jean-Clément Martin","title":"La Vendée et la Révolution","year":"2007","kind":"estudio","note":"Refuta el plan de exterminio y reconstruye una represión descentralizada y atroz."},{"author":"Peter McPhee","title":"Liberty or Death","year":"2016","kind":"estudio","note":"Síntesis reciente que reintegra lo social, lo rural y lo colonial sin volver al esquema de clases."}]},{"type":"images","items":[{"src":"/img/revolucion-francesa/portada.jpg","alt":"Pintura del asalto a la Bastilla, con humo de artillería y multitud armada frente a las torres de la fortaleza","width":1200,"height":912,"role":"portada","caption":"La toma de la Bastilla, 14 de julio de 1789, por Jean-Pierre Houël.","author":"Jean-Pierre Houël","title":"Prise de la Bastille","year":"1789","source":"Wikimedia Commons","license":"Public domain","url":"https://commons.wikimedia.org/wiki/File:Prise_de_la_Bastille.jpg"}]}]'::jsonb, 0, true
from public.topics where slug = 'revolucion-francesa'
on conflict (topic_id, position) do update set
  title = excluded.title, body = excluded.body, published = excluded.published;

